class _GameTable extends StatelessWidget {
  const _GameTable();

  @override
  Widget build(BuildContext context) {
    return Consumer<BlackjackViewModel>(
      builder: (context, viewModel, child) {
        return GlassCard(
          child: Padding(
            padding: const EdgeInsets.all(20),
            child: Column(
              children: [
                // Dealer hand
                Expanded(
                  flex: 2,
                  child: Column(
                    children: [
                      Text(
                        'Dealer',
                        style: Theme.of(context).textTheme.titleMedium?.copyWith(
                          color: Theme.of(context).casinoColors.textPrimary,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      const SizedBox(height: 12),
                      Expanded(
                        child: Center(
                          child: HandDisplayWidget(
                            hand: viewModel.dealerHand,
                            isDealer: true,
                            label: 'Dealer',
                            valueText: viewModel.dealerTurn || !viewModel.gameInProgress 
                                ? viewModel.getHandValueString(viewModel.dealerHand)
                                : null,
                            cardWidth: 70,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),

                // Divider
                Container(
                  height: 2,
                  margin: const EdgeInsets.symmetric(vertical: 20),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      colors: [
                        Colors.transparent,
                        CasinoColors.gold.withOpacity(0.5),
                        Colors.transparent,
                      ],
                    ),
                  ),
                ),

                // Player hands
                Expanded(
                  flex: 3,
                  child: viewModel.playerHands.length == 1
                      ? _buildSingleHand(viewModel)
                      : _buildMultipleHands(viewModel),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _buildSingleHand(BlackjackViewModel viewModel) {
    return Center(
      child: HandDisplayWidget(
        hand: viewModel.playerHands[0],
        isActive: viewModel.gameInProgress && viewModel.currentHandIndex == 0,
        label: 'Player',
        valueText: viewModel.getHandValueString(viewModel.playerHands[0]),
        cardWidth: 80,
      ),
    );
  }

  Widget _buildMultipleHands(BlackjackViewModel viewModel) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceEvenly,
      children: viewModel.playerHands.asMap().entries.map((entry) {
        final index = entry.key;
        final hand = entry.value;

        return Expanded(
          child: HandDisplayWidget(
            hand: hand,
            isActive: viewModel.gameInProgress && viewModel.currentHandIndex == index,
            label: 'Hand ${index + 1}',
            valueText: viewModel.getHandValueString(hand),
            cardWidth: 60,
          ),
        );
      }).toList(),
    );
  }
}

class _GameControls extends StatelessWidget {
  const _GameControls();

  @override
  Widget build(BuildContext context) {
    return Consumer<BlackjackViewModel>(
      builder: (context, viewModel, child) {
        if (!viewModel.gameInProgress) {
          return _buildBettingControls(viewModel);
        } else {
          return _buildGameActionControls(viewModel);
        }
      },
    );
  }

  Widget _buildBettingControls(BlackjackViewModel viewModel) {
    return Column(
      children: [
        // Bet selector
        GlassCard(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'Place Your Bet',
                style: Theme.of(context).textTheme.titleMedium?.copyWith(
                  color: CasinoColors.gold,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 12),
              ChipSelector(
                availableChips: viewModel.betAmounts,
                selectedChip: viewModel.selectedBet,
                onChipSelected: viewModel.setBet,
                size: 60,
              ),
            ],
          ),
        ),

        const SizedBox(height: 16),

        // Deal button
        PlayButton(
          onPressed: viewModel.startNewGame,
          text: 'DEAL CARDS',
          icon: FontAwesomeIcons.handHolding,
          width: double.infinity,
        ),
      ],
    );
  }

  Widget _buildGameActionControls(BlackjackViewModel viewModel) {
    final actions = viewModel.availableActions;

    return Column(
      children: [
        // Basic strategy hint
        if (viewModel.showBasicStrategy || viewModel.autoPlayBasicStrategy)
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(12),
            margin: const EdgeInsets.only(bottom: 16),
            decoration: BoxDecoration(
              color: CasinoColors.emerald.withOpacity(0.1),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: CasinoColors.emerald, width: 1),
            ),
            child: Row(
              children: [
                const FaIcon(FontAwesomeIcons.brain, 
                    color: CasinoColors.emerald, size: 16),
                const SizedBox(width: 8),
                Text(
                  'Basic Strategy: ${_getActionName(viewModel.basicStrategyAction)}',
                  style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                    color: CasinoColors.emerald,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const Spacer(),
                GestureDetector(
                  onTap: viewModel.toggleAutoPlayBasicStrategy,
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    decoration: BoxDecoration(
                      color: viewModel.autoPlayBasicStrategy 
                          ? CasinoColors.emerald 
                          : Colors.transparent,
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(color: CasinoColors.emerald),
                    ),
                    child: Text(
                      'AUTO',
                      style: TextStyle(
                        color: viewModel.autoPlayBasicStrategy 
                            ? Colors.black 
                            : CasinoColors.emerald,
                        fontSize: 10,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),

        // Action buttons
        Wrap(
          spacing: 12,
          runSpacing: 12,
          children: [
            if (actions.contains(BlackjackAction.hit))
              GlassButton(
                onPressed: viewModel.hit,
                style: GlassButtonStyle.filled,
                child: const Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    FaIcon(FontAwesomeIcons.plus, size: 16),
                    SizedBox(width: 8),
                    Text('HIT'),
                  ],
                ),
              ),

            if (actions.contains(BlackjackAction.stand))
              GlassButton(
                onPressed: viewModel.stand,
                style: GlassButtonStyle.outline,
                child: const Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    FaIcon(FontAwesomeIcons.handPaper, size: 16),
                    SizedBox(width: 8),
                    Text('STAND'),
                  ],
                ),
              ),

            if (actions.contains(BlackjackAction.doubleDown))
              GlassButton(
                onPressed: viewModel.doubleDown,
                style: GlassButtonStyle.glass,
                child: const Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    FaIcon(FontAwesomeIcons.arrowUp, size: 16),
                    SizedBox(width: 8),
                    Text('DOUBLE'),
                  ],
                ),
              ),

            if (actions.contains(BlackjackAction.split))
              GlassButton(
                onPressed: viewModel.split,
                style: GlassButtonStyle.glass,
                child: const Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    FaIcon(FontAwesomeIcons.scissors, size: 16),
                    SizedBox(width: 8),
                    Text('SPLIT'),
                  ],
                ),
              ),

            if (actions.contains(BlackjackAction.surrender))
              GlassButton(
                onPressed: viewModel.surrender,
                style: GlassButtonStyle.outline,
                child: const Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    FaIcon(FontAwesomeIcons.flag, size: 16),
                    SizedBox(width: 8),
                    Text('SURRENDER'),
                  ],
                ),
              ),
          ],
        ),
      ],
    );
  }

  String _getActionName(BlackjackAction action) {
    switch (action) {
      case BlackjackAction.hit:
        return 'Hit';
      case BlackjackAction.stand:
        return 'Stand';
      case BlackjackAction.doubleDown:
        return 'Double Down';
      case BlackjackAction.split:
        return 'Split';
      case BlackjackAction.surrender:
        return 'Surrender';
    }
  }
}

import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:audioplayers/audioplayers.dart';
import 'blackjack_engine.dart';
import '../../core/agents/agents.dart';

/// Animation states for blackjack game
enum BlackjackAnimationState {
  idle,
  dealing,
  cardFlip,
  celebrating,
  gameOver,
}

/// View model for blackjack game with MVVM architecture
class BlackjackViewModel extends ChangeNotifier {
  final BlackjackEngine _engine;
  final AudioPlayer _audioPlayer = AudioPlayer();

  // Animation and UI state
  BlackjackAnimationState _animationState = BlackjackAnimationState.idle;
  bool _soundEnabled = true;
  bool _hapticsEnabled = true;
  bool _animationsEnabled = true;

  // Game state
  BlackjackGameResult? _lastResult;
  int _selectedBet = 25;
  String _statusMessage = 'Place your bet to start!';
  bool _showBasicStrategy = false;
  bool _showSettings = false;
  bool _showGameHistory = false;
  bool _autoPlayBasicStrategy = false;

  // Card dealing animation
  int _dealingCardIndex = 0;
  bool _isDealingCards = false;

  BlackjackViewModel({
    required BlackjackEngine engine,
  }) : _engine = engine;

  // Getters for engine state
  int get balance => _engine.balance;
  BlackjackHand get dealerHand => _engine.dealerHand;
  List<BlackjackHand> get playerHands => _engine.playerHands;
  List<int> get handBets => _engine.handBets;
  int get currentHandIndex => _engine.currentHandIndex;
  BlackjackHand get currentHand => _engine.currentHand;
  int get currentBet => _engine.currentBet;
  bool get gameInProgress => _engine.gameInProgress;
  bool get dealerTurn => _engine.dealerTurn;
  bool get isDemoMode => _engine.isDemoMode;
  BlackjackConfig get config => _engine.config;
  Map<String, dynamic> get stats => _engine.getStats();
  List<BlackjackGameResult> get history => _engine.history;
  List<BlackjackAction> get availableActions => _engine.getAvailableActions();
  BlackjackAction get basicStrategyAction => _engine.getBasicStrategyAction();

  // UI state getters
  BlackjackAnimationState get animationState => _animationState;
  BlackjackGameResult? get lastResult => _lastResult;
  int get selectedBet => _selectedBet;
  String get statusMessage => _statusMessage;
  bool get soundEnabled => _soundEnabled;
  bool get hapticsEnabled => _hapticsEnabled;
  bool get animationsEnabled => _animationsEnabled;
  bool get showBasicStrategy => _showBasicStrategy;
  bool get showSettings => _showSettings;
  bool get showGameHistory => _showGameHistory;
  bool get autoPlayBasicStrategy => _autoPlayBasicStrategy;
  bool get isDealingCards => _isDealingCards;

  /// Available bet amounts
  List<int> get betAmounts => [5, 10, 25, 50, 100, 250, 500, 1000];

  /// Initialize the blackjack game
  void initialize(int startingBalance, {bool demoMode = false}) {
    _engine.initialize(startingBalance, demoMode: demoMode);
    _selectedBet = betAmounts.where((bet) => bet <= balance).first;
    _updateStatusMessage();
    notifyListeners();
  }

  /// Set bet amount
  void setBet(int amount) {
    if (betAmounts.contains(amount) && (isDemoMode || amount <= balance)) {
      _selectedBet = amount;
      _updateStatusMessage();
      notifyListeners();
    }
  }

  /// Start a new game
  Future<void> startNewGame() async {
    if (gameInProgress) return;

    if (_engine.startNewGame(_selectedBet)) {
      _setAnimationState(BlackjackAnimationState.dealing);
      _statusMessage = 'Dealing cards...';

      if (_animationsEnabled) {
        await _animateCardDealing();
      }

      _setAnimationState(BlackjackAnimationState.idle);

      // Check for immediate results
      if (currentHand.isBlackjack) {
        if (dealerHand.cards.first.isAce || 
            dealerHand.cards.first.blackjackValue == 10) {
          _statusMessage = 'Checking for dealer blackjack...';
          await Future.delayed(const Duration(milliseconds: 1000));
        }

        await _finishGame();
      } else {
        _updateStatusMessage();
      }

      if (_soundEnabled) {
        _playSound('deal_cards');
      }

      if (_hapticsEnabled) {
        HapticFeedback.lightImpact();
      }

      notifyListeners();
    }
  }

  /// Hit - take another card
  Future<void> hit() async {
    if (_engine.hit()) {
      if (_animationsEnabled) {
        await _animateCardDeal();
      }

      if (_soundEnabled) {
        _playSound('card_deal');
      }

      if (_hapticsEnabled) {
        HapticFeedback.lightImpact();
      }

      // Check if hand is bust or game is over
      if (currentHand.isBust || !gameInProgress) {
        await _finishGame();
      } else {
        _updateStatusMessage();
      }

      notifyListeners();
    }
  }

  /// Stand - keep current hand
  Future<void> stand() async {
    if (_engine.stand()) {
      if (_soundEnabled) {
        _playSound('stand');
      }

      // Check if game is over (all hands played)
      if (!gameInProgress) {
        await _finishGame();
      } else {
        _updateStatusMessage();
      }

      notifyListeners();
    }
  }

  /// Double down - double bet and take exactly one more card
  Future<void> doubleDown() async {
    if (_engine.doubleDown()) {
      if (_animationsEnabled) {
        await _animateCardDeal();
      }

      if (_soundEnabled) {
        _playSound('double_down');
      }

      if (_hapticsEnabled) {
        HapticFeedback.mediumImpact();
      }

      // Check if game is over
      if (!gameInProgress) {
        await _finishGame();
      } else {
        _updateStatusMessage();
      }

      notifyListeners();
    }
  }

  /// Split - create two hands from a pair
  Future<void> split() async {
    if (_engine.split()) {
      if (_animationsEnabled) {
        await _animateCardSplit();
      }

      if (_soundEnabled) {
        _playSound('split');
      }

      if (_hapticsEnabled) {
        HapticFeedback.mediumImpact();
      }

      _updateStatusMessage();
      notifyListeners();
    }
  }

  /// Surrender - forfeit half the bet
  Future<void> surrender() async {
    if (_engine.surrender()) {
      if (_soundEnabled) {
        _playSound('surrender');
      }

      await _finishGame();
      notifyListeners();
    }
  }

  /// Perform the basic strategy recommended action
  Future<void> performBasicStrategyAction() async {
    if (!gameInProgress || availableActions.isEmpty) return;

    final action = basicStrategyAction;

    switch (action) {
      case BlackjackAction.hit:
        await hit();
        break;
      case BlackjackAction.stand:
        await stand();
        break;
      case BlackjackAction.doubleDown:
        if (availableActions.contains(BlackjackAction.doubleDown)) {
          await doubleDown();
        } else {
          await hit(); // Fall back to hit if can't double
        }
        break;
      case BlackjackAction.split:
        await split();
        break;
      case BlackjackAction.surrender:
        if (availableActions.contains(BlackjackAction.surrender)) {
          await surrender();
        } else {
          await hit(); // Fall back to hit if can't surrender
        }
        break;
    }
  }

  /// Toggle auto play basic strategy
  void toggleAutoPlayBasicStrategy() {
    _autoPlayBasicStrategy = !_autoPlayBasicStrategy;

    if (_autoPlayBasicStrategy && gameInProgress && !dealerTurn) {
      _playBasicStrategyAuto();
    }

    notifyListeners();
  }

  /// Toggle basic strategy display
  void toggleBasicStrategy() {
    _showBasicStrategy = !_showBasicStrategy;
    notifyListeners();
  }

  /// Toggle settings display
  void toggleSettings() {
    _showSettings = !_showSettings;
    notifyListeners();
  }

  /// Toggle game history display
  void toggleGameHistory() {
    _showGameHistory = !_showGameHistory;
    notifyListeners();
  }

  /// Update sound setting
  void setSoundEnabled(bool enabled) {
    _soundEnabled = enabled;
    notifyListeners();
  }

  /// Update haptics setting
  void setHapticsEnabled(bool enabled) {
    _hapticsEnabled = enabled;
    notifyListeners();
  }

  /// Update animations setting
  void setAnimationsEnabled(bool enabled) {
    _animationsEnabled = enabled;
    notifyListeners();
  }

  /// Reset game statistics
  void resetStats() {
    _engine.resetStats();
    _lastResult = null;
    _updateStatusMessage();
    notifyListeners();
  }

  /// Get hand value display string
  String getHandValueString(BlackjackHand hand) {
    final value = hand.value;

    if (hand.isBust) {
      return 'BUST ($value)';
    } else if (hand.isBlackjack) {
      return 'BLACKJACK';
    } else if (hand.isSoft && value < 21) {
      return 'Soft $value';
    } else {
      return value.toString();
    }
  }

  /// Get result text for a hand
  String getHandResultText(HandResult handResult) {
    switch (handResult.result) {
      case BlackjackResult.win:
        return 'WIN';
      case BlackjackResult.lose:
        return 'LOSE';
      case BlackjackResult.push:
        return 'PUSH';
      case BlackjackResult.blackjack:
        return 'BLACKJACK!';
      case BlackjackResult.bust:
        return 'BUST';
      case BlackjackResult.surrender:
        return 'SURRENDER';
    }
  }

  /// Get result color for a hand
  Color getHandResultColor(HandResult handResult) {
    switch (handResult.result) {
      case BlackjackResult.win:
      case BlackjackResult.blackjack:
        return const Color(0xFF4CAF50); // Green
      case BlackjackResult.lose:
      case BlackjackResult.bust:
        return const Color(0xFFF44336); // Red
      case BlackjackResult.push:
        return const Color(0xFFFF9800); // Orange
      case BlackjackResult.surrender:
        return const Color(0xFF9E9E9E); // Grey
    }
  }

  // Private methods

  void _setAnimationState(BlackjackAnimationState state) {
    _animationState = state;
  }

  Future<void> _animateCardDealing() async {
    _isDealingCards = true;
    _dealingCardIndex = 0;

    // Animate dealing 4 cards (2 to player, 2 to dealer)
    for (int i = 0; i < 4; i++) {
      await Future.delayed(const Duration(milliseconds: 400));
      _dealingCardIndex++;
      notifyListeners();
    }

    _isDealingCards = false;
    notifyListeners();
  }

  Future<void> _animateCardDeal() async {
    if (!_animationsEnabled) return;

    _setAnimationState(BlackjackAnimationState.dealing);
    await Future.delayed(const Duration(milliseconds: 300));
    _setAnimationState(BlackjackAnimationState.idle);
  }

  Future<void> _animateCardSplit() async {
    if (!_animationsEnabled) return;

    await Future.delayed(const Duration(milliseconds: 500));
  }

  Future<void> _finishGame() async {
    if (dealerTurn) {
      // Animate dealer card reveal
      if (_animationsEnabled) {
        _setAnimationState(BlackjackAnimationState.cardFlip);
        await Future.delayed(const Duration(milliseconds: 600));
      }

      if (_soundEnabled) {
        _playSound('card_flip');
      }
    }

    // Game is finished, get final result
    _lastResult = history.isNotEmpty ? history.last : null;

    if (_lastResult != null) {
      if (_lastResult!.hasWin) {
        _setAnimationState(BlackjackAnimationState.celebrating);

        if (_lastResult!.hasBlackjack) {
          _statusMessage = '🎉 BLACKJACK! You won \$${_lastResult!.netResult}!';
          if (_soundEnabled) _playSound('blackjack');
          if (_hapticsEnabled) HapticFeedback.heavyImpact();
        } else {
          _statusMessage = '🎊 You won \$${_lastResult!.netResult}!';
          if (_soundEnabled) _playSound('win');
          if (_hapticsEnabled) HapticFeedback.mediumImpact();
        }
      } else if (_lastResult!.hasPush) {
        _statusMessage = '🤝 Push - bet returned';
        if (_soundEnabled) _playSound('push');
      } else {
        _statusMessage = '😞 You lost \$${_lastResult!.totalBet}';
        if (_soundEnabled) _playSound('lose');
      }

      await Future.delayed(const Duration(seconds: 2));
    }

    _setAnimationState(BlackjackAnimationState.idle);
    _statusMessage = 'Place your bet to start next game!';
    notifyListeners();
  }

  Future<void> _playBasicStrategyAuto() async {
    while (_autoPlayBasicStrategy && gameInProgress && !dealerTurn) {
      await Future.delayed(const Duration(milliseconds: 800));

      if (_autoPlayBasicStrategy && gameInProgress && !dealerTurn) {
        await performBasicStrategyAction();
      }
    }
  }

  Future<void> _playSound(String soundName) async {
    if (!_soundEnabled) return;

    try {
      await _audioPlayer.play(AssetSource('sounds/blackjack_$soundName.mp3'));
    } catch (e) {
      debugPrint('Failed to play sound $soundName: $e');
    }
  }

  void _updateStatusMessage() {
    if (!gameInProgress) {
      _statusMessage = 'Place your bet to start!';
    } else if (dealerTurn) {
      _statusMessage = 'Dealer\'s turn...';
    } else {
      final handNum = playerHands.length > 1 ? ' (Hand ${currentHandIndex + 1})' : '';
      final value = getHandValueString(currentHand);

      if (_autoPlayBasicStrategy) {
        final action = basicStrategyAction;
        _statusMessage = 'Auto: $value - Playing ${_getActionName(action)}$handNum';
      } else {
        _statusMessage = 'Your turn: $value$handNum';
      }
    }
  }

  String _getActionName(BlackjackAction action) {
    switch (action) {
      case BlackjackAction.hit:
        return 'Hit';
      case BlackjackAction.stand:
        return 'Stand';
      case BlackjackAction.doubleDown:
        return 'Double';
      case BlackjackAction.split:
        return 'Split';
      case BlackjackAction.surrender:
        return 'Surrender';
    }
  }

  @override
  void dispose() {
    _audioPlayer.dispose();
    super.dispose();
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';
import '../blackjack_engine.dart';
import '../../../ui/theme/app_theme.dart';

/// Animated playing card widget for blackjack
class PlayingCardWidget extends StatefulWidget {
  final PlayingCard? card;
  final bool isHidden;
  final bool isHighlighted;
  final double width;
  final double height;
  final VoidCallback? onTap;
  final bool showAnimation;

  const PlayingCardWidget({
    super.key,
    this.card,
    this.isHidden = false,
    this.isHighlighted = false,
    this.width = 80,
    this.height = 112,
    this.onTap,
    this.showAnimation = true,
  });

  @override
  State<PlayingCardWidget> createState() => _PlayingCardWidgetState();
}

class _PlayingCardWidgetState extends State<PlayingCardWidget>
    with TickerProviderStateMixin {
  late AnimationController _flipController;
  late AnimationController _highlightController;

  late Animation<double> _flipAnimation;
  late Animation<double> _highlightAnimation;

  @override
  void initState() {
    super.initState();

    _flipController = AnimationController(
      duration: const Duration(milliseconds: 600),
      vsync: this,
    );

    _highlightController = AnimationController(
      duration: const Duration(milliseconds: 300),
      vsync: this,
    );

    _flipAnimation = Tween<double>(
      begin: 0.0,
      end: 1.0,
    ).animate(CurvedAnimation(
      parent: _flipController,
      curve: Curves.easeInOut,
    ));

    _highlightAnimation = Tween<double>(
      begin: 0.0,
      end: 1.0,
    ).animate(CurvedAnimation(
      parent: _highlightController,
      curve: Curves.easeInOut,
    ));
  }

  @override
  void didUpdateWidget(PlayingCardWidget oldWidget) {
    super.didUpdateWidget(oldWidget);

    // Handle card flip animation
    if (widget.card != null && 
        oldWidget.card?.isHidden != widget.card?.isHidden &&
        widget.showAnimation) {
      if (widget.card!.isHidden) {
        _flipController.reverse();
      } else {
        _flipController.forward();
      }
    }

    // Handle highlight animation
    if (widget.isHighlighted != oldWidget.isHighlighted) {
      if (widget.isHighlighted) {
        _highlightController.forward();
      } else {
        _highlightController.reverse();
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    if (widget.card == null) {
      return _buildEmptySlot();
    }

    return GestureDetector(
      onTap: widget.onTap,
      child: AnimatedBuilder(
        animation: Listenable.merge([_flipAnimation, _highlightAnimation]),
        builder: (context, child) {
          return Transform(
            alignment: Alignment.center,
            transform: Matrix4.identity()
              ..setEntry(3, 2, 0.001)
              ..rotateY(_flipAnimation.value * 3.14159),
            child: Container(
              width: widget.width,
              height: widget.height,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(8),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withOpacity(0.2),
                    blurRadius: 4,
                    offset: const Offset(2, 2),
                  ),
                  if (widget.isHighlighted)
                    BoxShadow(
                      color: CasinoColors.gold.withOpacity(0.6 * _highlightAnimation.value),
                      blurRadius: 8,
                      spreadRadius: 2,
                    ),
                ],
              ),
              child: _flipAnimation.value < 0.5 || !widget.showAnimation
                  ? _buildCardFace()
                  : Transform(
                      alignment: Alignment.center,
                      transform: Matrix4.identity()..rotateY(3.14159),
                      child: _buildCardFace(),
                    ),
            ),
          );
        },
      ),
    );
  }

  Widget _buildCardFace() {
    final card = widget.card!;
    final isHidden = widget.isHidden || card.isHidden;

    return Container(
      width: widget.width,
      height: widget.height,
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: widget.isHighlighted 
              ? CasinoColors.gold 
              : Colors.grey.shade400,
          width: widget.isHighlighted ? 2 : 1,
        ),
      ),
      child: isHidden ? _buildCardBack() : _buildCardFront(card),
    );
  }

  Widget _buildCardBack() {
    return Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(7),
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            CasinoColors.darkBackground,
            CasinoColors.darkSurface,
          ],
        ),
      ),
      child: Stack(
        children: [
          // Pattern background
          Container(
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(7),
              image: const DecorationImage(
                image: AssetImage('assets/images/card_back_pattern.png'),
                fit: BoxFit.cover,
                opacity: 0.3,
              ),
            ),
          ),

          // Center logo
          const Center(
            child: Icon(
              Icons.casino,
              color: CasinoColors.gold,
              size: 32,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildCardFront(PlayingCard card) {
    final isRed = card.suit.isRed;
    final suitColor = isRed ? Colors.red : Colors.black;

    return Padding(
      padding: const EdgeInsets.all(4),
      child: Stack(
        children: [
          // Top-left rank and suit
          Positioned(
            top: 2,
            left: 2,
            child: Column(
              children: [
                Text(
                  card.rank.symbol,
                  style: TextStyle(
                    color: suitColor,
                    fontSize: widget.width * 0.15,
                    fontWeight: FontWeight.bold,
                    height: 0.9,
                  ),
                ),
                Text(
                  card.suit.symbol,
                  style: TextStyle(
                    color: suitColor,
                    fontSize: widget.width * 0.15,
                    height: 0.8,
                  ),
                ),
              ],
            ),
          ),

          // Bottom-right rank and suit (upside down)
          Positioned(
            bottom: 2,
            right: 2,
            child: Transform.rotate(
              angle: 3.14159, // 180 degrees
              child: Column(
                children: [
                  Text(
                    card.rank.symbol,
                    style: TextStyle(
                      color: suitColor,
                      fontSize: widget.width * 0.15,
                      fontWeight: FontWeight.bold,
                      height: 0.9,
                    ),
                  ),
                  Text(
                    card.suit.symbol,
                    style: TextStyle(
                      color: suitColor,
                      fontSize: widget.width * 0.15,
                      height: 0.8,
                    ),
                  ),
                ],
              ),
            ),
          ),

          // Center suit symbol(s)
          Center(
            child: _buildCenterPattern(card, suitColor),
          ),
        ],
      ),
    );
  }

  Widget _buildCenterPattern(PlayingCard card, Color suitColor) {
    if (card.isFaceCard) {
      return _buildFaceCardCenter(card, suitColor);
    }

    if (card.rank == CardRank.ace) {
      return Text(
        card.suit.symbol,
        style: TextStyle(
          color: suitColor,
          fontSize: widget.width * 0.4,
          fontWeight: FontWeight.bold,
        ),
      );
    }

    return _buildNumberCardCenter(card, suitColor);
  }

  Widget _buildFaceCardCenter(PlayingCard card, Color suitColor) {
    String faceSymbol;

    switch (card.rank) {
      case CardRank.jack:
        faceSymbol = 'J';
        break;
      case CardRank.queen:
        faceSymbol = 'Q';
        break;
      case CardRank.king:
        faceSymbol = 'K';
        break;
      default:
        faceSymbol = card.rank.symbol;
    }

    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          faceSymbol,
          style: TextStyle(
            color: suitColor,
            fontSize: widget.width * 0.25,
            fontWeight: FontWeight.bold,
          ),
        ),
        const SizedBox(height: 2),
        Text(
          card.suit.symbol,
          style: TextStyle(
            color: suitColor,
            fontSize: widget.width * 0.2,
          ),
        ),
      ],
    );
  }

  Widget _buildNumberCardCenter(PlayingCard card, Color suitColor) {
    final value = card.rank.value;

    if (value <= 1 || value > 10) {
      return Text(
        card.suit.symbol,
        style: TextStyle(
          color: suitColor,
          fontSize: widget.width * 0.25,
        ),
      );
    }

    // Create pattern based on card value
    return _buildSuitPattern(value, card.suit.symbol, suitColor);
  }

  Widget _buildSuitPattern(int count, String suitSymbol, Color color) {
    final symbols = <Widget>[];
    final symbolSize = widget.width * 0.12;

    for (int i = 0; i < count && i < 10; i++) {
      symbols.add(
        Text(
          suitSymbol,
          style: TextStyle(
            color: color,
            fontSize: symbolSize,
            height: 0.8,
          ),
        ),
      );
    }

    if (count <= 3) {
      return Column(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        children: symbols,
      );
    } else if (count <= 6) {
      return Column(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceEvenly,
            children: symbols.take(2).toList(),
          ),
          if (count >= 4)
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: symbols.skip(2).take(2).toList(),
            ),
          if (count >= 6)
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: symbols.skip(4).take(2).toList(),
            ),
        ],
      );
    } else {
      return Wrap(
        alignment: WrapAlignment.center,
        spacing: 2,
        runSpacing: 1,
        children: symbols,
      );
    }
  }

  Widget _buildEmptySlot() {
    return Container(
      width: widget.width,
      height: widget.height,
      decoration: BoxDecoration(
        color: Colors.transparent,
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: Colors.white.withOpacity(0.2),
          width: 1,
          style: BorderStyle.solid,
        ),
      ),
      child: const Center(
        child: Icon(
          Icons.add,
          color: Colors.white24,
          size: 24,
        ),
      ),
    );
  }

  @override
  void dispose() {
    _flipController.dispose();
    _highlightController.dispose();
    super.dispose();
  }
}

/// Hand of cards display widget
class HandDisplayWidget extends StatelessWidget {
  final BlackjackHand hand;
  final bool isDealer;
  final bool isActive;
  final String? label;
  final String? valueText;
  final double cardWidth;
  final double cardSpacing;

  const HandDisplayWidget({
    super.key,
    required this.hand,
    this.isDealer = false,
    this.isActive = false,
    this.label,
    this.valueText,
    this.cardWidth = 80,
    this.cardSpacing = 20,
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return Column(
      children: [
        // Label and value
        if (label != null || valueText != null)
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
            decoration: BoxDecoration(
              color: isActive 
                  ? CasinoColors.gold.withOpacity(0.2)
                  : theme.casinoColors.glassBackground,
              borderRadius: BorderRadius.circular(20),
              border: Border.all(
                color: isActive 
                    ? CasinoColors.gold
                    : theme.casinoColors.glassBorder,
                width: 1,
              ),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                if (label != null) ...[
                  Text(
                    label!,
                    style: theme.textTheme.bodyMedium?.copyWith(
                      color: isActive 
                          ? CasinoColors.gold
                          : theme.casinoColors.textPrimary,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  if (valueText != null) const SizedBox(width: 8),
                ],
                if (valueText != null)
                  Text(
                    valueText!,
                    style: theme.textTheme.bodyMedium?.copyWith(
                      color: isActive 
                          ? CasinoColors.gold
                          : CasinoColors.gold,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
              ],
            ),
          ),

        const SizedBox(height: 12),

        // Cards
        SizedBox(
          height: cardWidth * 1.4, // Card aspect ratio
          child: Stack(
            children: hand.cards.asMap().entries.map((entry) {
              final index = entry.key;
              final card = entry.value;

              return Positioned(
                left: index * cardSpacing,
                child: PlayingCardWidget(
                  card: card,
                  isHidden: card.isHidden,
                  width: cardWidth,
                  height: cardWidth * 1.4,
                  isHighlighted: isActive,
                ),
              );
            }).toList(),
          ),
        ),
      ],
    );
  }
}

/// Card dealing animation helper
class CardDealAnimation extends StatefulWidget {
  final Widget child;
  final bool isDealing;
  final Duration delay;

  const CardDealAnimation({
    super.key,
    required this.child,
    this.isDealing = false,
    this.delay = Duration.zero,
  });

  @override
  State<CardDealAnimation> createState() => _CardDealAnimationState();
}

class _CardDealAnimationState extends State<CardDealAnimation>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<Offset> _slideAnimation;
  late Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();

    _controller = AnimationController(
      duration: const Duration(milliseconds: 600),
      vsync: this,
    );

    _slideAnimation = Tween<Offset>(
      begin: const Offset(0, -2),
      end: Offset.zero,
    ).animate(CurvedAnimation(
      parent: _controller,
      curve: Curves.elasticOut,
    ));

    _scaleAnimation = Tween<double>(
      begin: 0.0,
      end: 1.0,
    ).animate(CurvedAnimation(
      parent: _controller,
      curve: Curves.elasticOut,
    ));

    Future.delayed(widget.delay, () {
      if (mounted) _controller.forward();
    });
  }

  @override
  void didUpdateWidget(CardDealAnimation oldWidget) {
    super.didUpdateWidget(oldWidget);

    if (widget.isDealing && !oldWidget.isDealing) {
      _controller.reset();
      Future.delayed(widget.delay, () {
        if (mounted) _controller.forward();
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, child) {
        return SlideTransition(
          position: _slideAnimation,
          child: ScaleTransition(
            scale: _scaleAnimation,
            child: widget.child,
          ),
        );
      },
    );
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }
}

import 'dart:math';
import '../../core/agents/agents.dart';

/// Roulette number with color and properties
class RouletteNumber {
  final int number;
  final RouletteColor color;
  final bool isEven;
  final bool isLow; // 1-18
  final int column; // 1, 2, or 3
  final int dozen; // 1, 2, or 3

  RouletteNumber(this.number)
      : color = _getColor(number),
        isEven = number > 0 && number % 2 == 0,
        isLow = number >= 1 && number <= 18,
        column = number == 0 ? 0 : ((number - 1) % 3) + 1,
        dozen = number == 0 ? 0 : ((number - 1) ~/ 12) + 1;

  bool get isOdd => number > 0 && !isEven;
  bool get isHigh => number >= 19 && number <= 36;

  static RouletteColor _getColor(int number) {
    if (number == 0) return RouletteColor.green;

    const redNumbers = [1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36];
    return redNumbers.contains(number) ? RouletteColor.red : RouletteColor.black;
  }
}

/// Roulette number colors
enum RouletteColor {
  red,
  black,
  green,
}

/// Types of bets in roulette
enum BetType {
  // Inside bets
  straight(35, 'Straight Up'),
  split(17, 'Split'),
  street(11, 'Street'),
  corner(8, 'Corner'),
  sixLine(5, 'Six Line'),

  // Outside bets
  red(1, 'Red'),
  black(1, 'Black'),
  even(1, 'Even'),
  odd(1, 'Odd'),
  low(1, '1-18'),
  high(1, '19-36'),
  dozen1(2, '1st Dozen'),
  dozen2(2, '2nd Dozen'),
  dozen3(2, '3rd Dozen'),
  column1(2, '1st Column'),
  column2(2, '2nd Column'),
  column3(2, '3rd Column');

  const BetType(this.payout, this.name);

  final int payout;
  final String name;

  bool get isInside => [straight, split, street, corner, sixLine].contains(this);
  bool get isOutside => !isInside;
}

/// Individual bet placed on the table
class RouletteBet {
  final BetType type;
  final List<int> numbers;
  final int amount;
  final String id;

  const RouletteBet({
    required this.type,
    required this.numbers,
    required this.amount,
    required this.id,
  });

  /// Check if this bet wins for the given number
  bool isWinner(int winningNumber) {
    return numbers.contains(winningNumber);
  }

  /// Calculate payout if this bet wins
  int calculatePayout() {
    return amount * type.payout;
  }
}

/// Result of a roulette spin
class RouletteSpinResult {
  final RouletteNumber winningNumber;
  final List<RouletteBet> winningBets;
  final List<RouletteBet> losingBets;
  final int totalWin;
  final int totalLoss;
  final double spinDuration;
  final DateTime timestamp;

  const RouletteSpinResult({
    required this.winningNumber,
    required this.winningBets,
    required this.losingBets,
    required this.totalWin,
    required this.totalLoss,
    required this.spinDuration,
    required this.timestamp,
  });

  int get netResult => totalWin - totalLoss;
  bool get hasWin => totalWin > 0;
}

/// Roulette game configuration
class RouletteConfig {
  final RouletteType type;
  final int minBet;
  final int maxBet;
  final int maxTotalBet;
  final Map<BetType, int> betLimits;
  final double houseEdge;

  const RouletteConfig({
    this.type = RouletteType.european,
    this.minBet = 1,
    this.maxBet = 1000,
    this.maxTotalBet = 5000,
    this.betLimits = const {},
    this.houseEdge = 0.027, // European roulette
  });

  /// European roulette (single zero)
  static const RouletteConfig european = RouletteConfig(
    type: RouletteType.european,
    houseEdge: 0.027,
  );

  /// American roulette (double zero)
  static const RouletteConfig american = RouletteConfig(
    type: RouletteType.american,
    houseEdge: 0.053,
  );

  /// High roller configuration
  static const RouletteConfig highRoller = RouletteConfig(
    type: RouletteType.european,
    minBet: 100,
    maxBet: 10000,
    maxTotalBet: 50000,
    houseEdge: 0.027,
  );
}

enum RouletteType {
  european,
  american,
}

/// Core roulette game engine
class RouletteEngine {
  final RouletteConfig config;
  final GameEngineAgent _gameEngine;
  final Random _random;

  // Game state
  int _balance = 0;
  List<RouletteBet> _currentBets = [];
  List<RouletteSpinResult> _history = [];
  int _totalSpins = 0;
  int _totalWins = 0;
  double _totalWagered = 0;
  double _totalWon = 0;

  // Demo mode
  bool _isDemoMode = true;
  bool _betsLocked = false;

  RouletteEngine({
    required this.config,
    required GameEngineAgent gameEngine,
    int? seed,
  }) : _gameEngine = gameEngine,
       _random = Random(seed);

  // Getters
  int get balance => _balance;
  List<RouletteBet> get currentBets => List.unmodifiable(_currentBets);
  List<RouletteSpinResult> get history => List.unmodifiable(_history);
  int get totalSpins => _totalSpins;
  int get totalWins => _totalWins;
  double get totalWagered => _totalWagered;
  double get totalWon => _totalWon;
  double get winRate => _totalSpins > 0 ? (_totalWins / _totalSpins) * 100 : 0;
  double get actualRtp => _totalWagered > 0 ? (_totalWon / _totalWagered) * 100 : 0;
  bool get isDemoMode => _isDemoMode;
  bool get betsLocked => _betsLocked;
  bool get hasBets => _currentBets.isNotEmpty;
  int get totalBetAmount => _currentBets.fold(0, (sum, bet) => sum + bet.amount);

  /// All roulette numbers (0-36 for European, 0-37 for American)
  List<RouletteNumber> get allNumbers {
    final numbers = List.generate(37, (i) => RouletteNumber(i));
    if (config.type == RouletteType.american) {
      numbers.add(RouletteNumber(37)); // 00 in American roulette
    }
    return numbers;
  }

  /// Initialize the engine
  void initialize(int startingBalance, {bool demoMode = false}) {
    _balance = startingBalance;
    _isDemoMode = demoMode;
    _currentBets.clear();
    _betsLocked = false;
  }

  /// Place a straight bet on a single number
  bool placeStraightBet(int number, int amount) {
    if (!_canPlaceBet(amount) || number < 0 || number > 36) return false;

    final bet = RouletteBet(
      type: BetType.straight,
      numbers: [number],
      amount: amount,
      id: _generateBetId(),
    );

    return _addBet(bet);
  }

  /// Place a split bet on two adjacent numbers
  bool placeSplitBet(int number1, int number2, int amount) {
    if (!_canPlaceBet(amount) || !_isValidSplit(number1, number2)) return false;

    final bet = RouletteBet(
      type: BetType.split,
      numbers: [number1, number2],
      amount: amount,
      id: _generateBetId(),
    );

    return _addBet(bet);
  }

  /// Place a street bet (row of 3 numbers)
  bool placeStreetBet(int startNumber, int amount) {
    if (!_canPlaceBet(amount) || !_isValidStreet(startNumber)) return false;

    final numbers = [startNumber, startNumber + 1, startNumber + 2];
    final bet = RouletteBet(
      type: BetType.street,
      numbers: numbers,
      amount: amount,
      id: _generateBetId(),
    );

    return _addBet(bet);
  }

  /// Place a corner bet (4 numbers)
  bool placeCornerBet(int topLeftNumber, int amount) {
    if (!_canPlaceBet(amount) || !_isValidCorner(topLeftNumber)) return false;

    final numbers = [
      topLeftNumber,
      topLeftNumber + 1,
      topLeftNumber + 3,
      topLeftNumber + 4,
    ];

    final bet = RouletteBet(
      type: BetType.corner,
      numbers: numbers,
      amount: amount,
      id: _generateBetId(),
    );

    return _addBet(bet);
  }

  /// Place an outside bet (red, black, even, odd, etc.)
  bool placeOutsideBet(BetType betType, int amount) {
    if (!_canPlaceBet(amount) || betType.isInside) return false;

    final numbers = _getOutsideBetNumbers(betType);
    final bet = RouletteBet(
      type: betType,
      numbers: numbers,
      amount: amount,
      id: _generateBetId(),
    );

    return _addBet(bet);
  }

  /// Remove a specific bet
  bool removeBet(String betId) {
    if (_betsLocked) return false;

    final betIndex = _currentBets.indexWhere((bet) => bet.id == betId);
    if (betIndex == -1) return false;

    final bet = _currentBets[betIndex];
    if (!_isDemoMode) {
      _balance += bet.amount;
    }

    _currentBets.removeAt(betIndex);
    return true;
  }

  /// Clear all bets
  void clearBets() {
    if (_betsLocked) return;

    if (!_isDemoMode) {
      final totalAmount = _currentBets.fold(0, (sum, bet) => sum + bet.amount);
      _balance += totalAmount;
    }

    _currentBets.clear();
  }

  /// Lock bets (no more changes allowed)
  void lockBets() {
    _betsLocked = true;
  }

  /// Spin the wheel
  Future<RouletteSpinResult> spin() async {
    if (!hasBets) {
      throw Exception('No bets placed');
    }

    lockBets();

    final startTime = DateTime.now();

    // Generate winning number
    final maxNumber = config.type == RouletteType.american ? 38 : 37;
    final winningNumberValue = _random.nextInt(maxNumber);
    final winningNumber = RouletteNumber(winningNumberValue);

    // Determine winning and losing bets
    final winningBets = <RouletteBet>[];
    final losingBets = <RouletteBet>[];
    int totalWin = 0;
    int totalLoss = 0;

    for (final bet in _currentBets) {
      if (bet.isWinner(winningNumber.number)) {
        winningBets.add(bet);
        totalWin += bet.calculatePayout() + bet.amount; // Include original bet
      } else {
        losingBets.add(bet);
        totalLoss += bet.amount;
      }
    }

    // Update balance
    if (!_isDemoMode) {
      _balance += totalWin;
    }

    // Update statistics
    _totalSpins++;
    if (totalWin > 0) {
      _totalWins++;
    }
    _totalWagered += totalLoss + (totalWin > 0 ? winningBets.fold(0, (sum, bet) => sum + bet.amount) : 0);
    _totalWon += totalWin;

    final spinDuration = DateTime.now().difference(startTime).inMilliseconds / 1000.0;

    final result = RouletteSpinResult(
      winningNumber: winningNumber,
      winningBets: winningBets,
      losingBets: losingBets,
      totalWin: totalWin,
      totalLoss: totalLoss,
      spinDuration: spinDuration,
      timestamp: DateTime.now(),
    );

    // Add to history (keep last 100 spins)
    _history.add(result);
    if (_history.length > 100) {
      _history = _history.skip(_history.length - 100).toList();
    }

    // Reset for next round
    _currentBets.clear();
    _betsLocked = false;

    return result;
  }

  /// Get recent numbers for display
  List<RouletteNumber> getRecentNumbers({int count = 10}) {
    return _history
        .take(count)
        .map((result) => result.winningNumber)
        .toList();
  }

  /// Get hot numbers (most frequent)
  List<MapEntry<int, int>> getHotNumbers({int count = 5}) {
    final numberCount = <int, int>{};

    for (final result in _history) {
      final number = result.winningNumber.number;
      numberCount[number] = (numberCount[number] ?? 0) + 1;
    }

    final sorted = numberCount.entries.toList()
      ..sort((a, b) => b.value.compareTo(a.value));

    return sorted.take(count).toList();
  }

  /// Get cold numbers (least frequent)
  List<MapEntry<int, int>> getColdNumbers({int count = 5}) {
    final numberCount = <int, int>{};

    // Initialize all numbers with 0
    for (int i = 0; i <= 36; i++) {
      numberCount[i] = 0;
    }

    // Count occurrences
    for (final result in _history) {
      final number = result.winningNumber.number;
      numberCount[number] = numberCount[number]! + 1;
    }

    final sorted = numberCount.entries.toList()
      ..sort((a, b) => a.value.compareTo(b.value));

    return sorted.take(count).toList();
  }

  /// Reset game statistics
  void resetStats() {
    _totalSpins = 0;
    _totalWins = 0;
    _totalWagered = 0;
    _totalWon = 0;
    _history.clear();
  }

  // Helper methods

  bool _canPlaceBet(int amount) {
    if (_betsLocked) return false;
    if (amount < config.minBet || amount > config.maxBet) return false;
    if (totalBetAmount + amount > config.maxTotalBet) return false;
    if (!_isDemoMode && amount > _balance) return false;

    return true;
  }

  bool _addBet(RouletteBet bet) {
    if (!_canPlaceBet(bet.amount)) return false;

    // Deduct from balance (except in demo mode)
    if (!_isDemoMode) {
      _balance -= bet.amount;
    }

    _currentBets.add(bet);
    return true;
  }

  String _generateBetId() {
    return 'bet_${DateTime.now().millisecondsSinceEpoch}_${_random.nextInt(1000)}';
  }

  bool _isValidSplit(int num1, int num2) {
    if (num1 == num2) return false;
    if (num1 < 0 || num1 > 36 || num2 < 0 || num2 > 36) return false;

    // Check if numbers are adjacent horizontally or vertically
    final diff = (num1 - num2).abs();
    return diff == 1 || diff == 3;
  }

  bool _isValidStreet(int startNumber) {
    return startNumber >= 1 && startNumber <= 34 && (startNumber - 1) % 3 == 0;
  }

  bool _isValidCorner(int topLeftNumber) {
    if (topLeftNumber < 1 || topLeftNumber > 32) return false;
    return (topLeftNumber - 1) % 3 != 2; // Not in rightmost column
  }

  List<int> _getOutsideBetNumbers(BetType betType) {
    switch (betType) {
      case BetType.red:
        return [1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36];
      case BetType.black:
        return [2, 4, 6, 8, 10, 11, 13, 15, 17, 20, 22, 24, 26, 28, 29, 31, 33, 35];
      case BetType.even:
        return List.generate(18, (i) => (i + 1) * 2);
      case BetType.odd:
        return List.generate(18, (i) => (i * 2) + 1);
      case BetType.low:
        return List.generate(18, (i) => i + 1);
      case BetType.high:
        return List.generate(18, (i) => i + 19);
      case BetType.dozen1:
        return List.generate(12, (i) => i + 1);
      case BetType.dozen2:
        return List.generate(12, (i) => i + 13);
      case BetType.dozen3:
        return List.generate(12, (i) => i + 25);
      case BetType.column1:
        return [1, 4, 7, 10, 13, 16, 19, 22, 25, 28, 31, 34];
      case BetType.column2:
        return [2, 5, 8, 11, 14, 17, 20, 23, 26, 29, 32, 35];
      case BetType.column3:
        return [3, 6, 9, 12, 15, 18, 21, 24, 27, 30, 33, 36];
      default:
        return [];
    }
  }

  /// Get game statistics summary
  Map<String, dynamic> getStats() {
    return {
      'totalSpins': _totalSpins,
      'totalWins': _totalWins,
      'winRate': winRate,
      'totalWagered': _totalWagered,
      'totalWon': _totalWon,
      'actualRtp': actualRtp,
      'balance': _balance,
      'currentBetAmount': totalBetAmount,
      'recentNumbers': getRecentNumbers().map((n) => n.number).toList(),
      'hotNumbers': getHotNumbers().map((e) => {'number': e.key, 'count': e.value}).toList(),
      'coldNumbers': getColdNumbers().map((e) => {'number': e.key, 'count': e.value}).toList(),
    };
  }
}

import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
