  }

  Color _getBackgroundColor(RouletteColor color) {
    switch (color) {
      case RouletteColor.red:
        return CasinoColors.ruby;
      case RouletteColor.black:
        return Colors.black87;
      case RouletteColor.green:
        return CasinoColors.emerald;
    }
  }
