        onTap: () => context.read<SlotsViewModel>().toggleSettings(),
        child: Container(
          color: Colors.black.withOpacity(0.7),
          child: Center(
            child: GlassContainer(
              width: 350,
              height: 500,
              borderRadius: 24,
              child: Column(
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Text(
                        'Settings',
                        style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                          color: CasinoColors.gold,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      GlassButton(
                        onPressed: () => context.read<SlotsViewModel>().toggleSettings(),
                        style: GlassButtonStyle.outline,
                        width: 40,
                        child: const FaIcon(FontAwesomeIcons.xmark, size: 16),
                      ),
                    ],
                  ),
                  const SizedBox(height: 24),
                  Expanded(
                    child: Consumer<SlotsViewModel>(
                      builder: (context, viewModel, child) {
                        return Column(
                          children: [
                            _SettingsSwitch(
                              title: 'Sound Effects',
                              value: viewModel.soundEnabled,
                              onChanged: viewModel.setSoundEnabled,
                            ),
                            _SettingsSwitch(
                              title: 'Haptic Feedback',
                              value: viewModel.hapticsEnabled,
                              onChanged: viewModel.setHapticsEnabled,
                            ),
                            _SettingsSwitch(
                              title: 'Animations',
                              value: viewModel.animationsEnabled,
                              onChanged: viewModel.setAnimationsEnabled,
                            ),
                            const SizedBox(height: 20),
                            _SettingsSlider(
                              title: 'Spin Speed',
                              value: viewModel.spinSpeed,
                              min: 0.5,
                              max: 2.0,
                              onChanged: viewModel.setSpinSpeed,
                            ),
                          ],
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _SettingsSwitch extends StatelessWidget {
  final String title;
  final bool value;
  final ValueChanged<bool> onChanged;

  const _SettingsSwitch({
    required this.title,
    required this.value,
    required this.onChanged,
  });

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 16),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(
            title,
            style: Theme.of(context).textTheme.bodyLarge?.copyWith(
              color: Theme.of(context).casinoColors.textPrimary,
            ),
          ),
          Switch(
            value: value,
            onChanged: onChanged,
            activeColor: CasinoColors.gold,
          ),
        ],
      ),
    );
  }
}

class _SettingsSlider extends StatelessWidget {
  final String title;
  final double value;
  final double min;
  final double max;
  final ValueChanged<double> onChanged;

  const _SettingsSlider({
    required this.title,
    required this.value,
    required this.min,
    required this.max,
    required this.onChanged,
  });

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Text(
              title,
              style: Theme.of(context).textTheme.bodyLarge?.copyWith(
                color: Theme.of(context).casinoColors.textPrimary,
              ),
