  }
}

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:audioplayers/audioplayers.dart';
import 'slots_engine.dart';
import '../../core/agents/agents.dart';

/// Animation states for the slot machine
enum SlotAnimationState {
  idle,
  spinning,
  stopping,
  celebrating,
  paylineFlash,
}

/// View model for slots game with MVVM architecture
class SlotsViewModel extends ChangeNotifier {
  final SlotsEngine _engine;
  final AudioPlayer _audioPlayer = AudioPlayer();

  // Animation and UI state
  SlotAnimationState _animationState = SlotAnimationState.idle;
  List<bool> _reelSpinning = [false, false, false, false, false];
  double _spinSpeed = 1.0;
  bool _soundEnabled = true;
  bool _hapticsEnabled = true;
  bool _animationsEnabled = true;

  // Game state
  SpinResult? _lastResult;
  List<WinLine> _flashingWinLines = [];
  bool _showPaytable = false;
  bool _showSettings = false;
  String _statusMessage = 'Ready to spin!';

  // Auto play state
  bool _autoPlayPaused = false;
  Duration _autoPlayDelay = const Duration(milliseconds: 1500);

  SlotsViewModel({
    required SlotsEngine engine,
  }) : _engine = engine;

  // Getters for engine state
  int get balance => _engine.balance;
  int get currentBet => _engine.currentBet;
  bool get canSpin => _engine.canSpin();
  SlotConfig get config => _engine.config;
  bool get isDemoMode => _engine.isDemoMode;
  bool get isAutoPlay => _engine.isAutoPlay;
  int get autoPlayRemaining => _engine.autoPlayRemaining;
  Map<String, dynamic> get stats => _engine.getStats();
  List<SpinResult> get history => _engine.history;

  // UI state getters
  SlotAnimationState get animationState => _animationState;
  List<bool> get reelSpinning => List.unmodifiable(_reelSpinning);
  SpinResult? get lastResult => _lastResult;
  List<WinLine> get flashingWinLines => List.unmodifiable(_flashingWinLines);
  bool get isSpinning => _animationState == SlotAnimationState.spinning;
  bool get showPaytable => _showPaytable;
  bool get showSettings => _showSettings;
  String get statusMessage => _statusMessage;
  bool get soundEnabled => _soundEnabled;
  bool get hapticsEnabled => _hapticsEnabled;
  bool get animationsEnabled => _animationsEnabled;
  double get spinSpeed => _spinSpeed;

  /// Initialize the slots game
  void initialize(int startingBalance, {bool demoMode = false}) {
    _engine.initialize(startingBalance, demoMode: demoMode);
    _updateStatusMessage();
    notifyListeners();
  }

  /// Set bet amount
  void setBet(int amount) {
    if (_engine.setBet(amount)) {
      _updateStatusMessage();
      notifyListeners();
    }
  }

  /// Increase bet by one step
  void increaseBet() {
    final betOptions = [1, 2, 5, 10, 25, 50, 100, 250, 500, 1000];
    final currentIndex = betOptions.indexOf(currentBet);

    if (currentIndex < betOptions.length - 1) {
      setBet(betOptions[currentIndex + 1]);
    }
  }

  /// Decrease bet by one step
  void decreaseBet() {
    final betOptions = [1, 2, 5, 10, 25, 50, 100, 250, 500, 1000];
    final currentIndex = betOptions.indexOf(currentBet);

    if (currentIndex > 0) {
      setBet(betOptions[currentIndex - 1]);
    }
  }

  /// Set maximum bet
  void maxBet() {
    final maxAffordable = isDemoMode ? config.maxBet : balance;
    setBet(maxAffordable.clamp(config.minBet, config.maxBet));
  }

  /// Perform a single spin
  Future<void> spin() async {
    if (!canSpin || isSpinning) return;

    try {
      // Start spin animation
      _startSpinAnimation();

      // Play spin sound
      if (_soundEnabled) {
        _playSound('spin_start');
      }

      // Haptic feedback
      if (_hapticsEnabled) {
        HapticFeedback.mediumImpact();
      }

      // Perform the actual spin
      final result = await _engine.spin();

      // Animate reel stopping with staggered timing
      await _animateReelStopping(result);

      // Update result and check for wins
      _lastResult = result;

      if (result.hasWin) {
        await _celebrateWin(result);
      } else {
        _setAnimationState(SlotAnimationState.idle);
        _statusMessage = 'Try again!';
      }

    } catch (e) {
      _setAnimationState(SlotAnimationState.idle);
      _statusMessage = 'Error: ${e.toString()}';
      debugPrint('Spin error: $e');
    }

    notifyListeners();
  }

  /// Start auto play
  void startAutoPlay(int spins) {
    if (spins <= 0 || !canSpin) return;

    _engine.startAutoPlay(spins);
    _autoPlayPaused = false;
    _statusMessage = 'Auto play started ($spins spins)';
    notifyListeners();

    _runAutoPlay();
  }

  /// Stop auto play
  void stopAutoPlay() {
    _engine.stopAutoPlay();
    _autoPlayPaused = false;
    _statusMessage = 'Auto play stopped';
    notifyListeners();
  }

  /// Pause/resume auto play
  void toggleAutoPlayPause() {
    _autoPlayPaused = !_autoPlayPaused;

    if (!_autoPlayPaused && isAutoPlay) {
      _runAutoPlay();
    }

    notifyListeners();
  }

  /// Run auto play sequence
  Future<void> _runAutoPlay() async {
    while (isAutoPlay && !_autoPlayPaused && canSpin) {
      await spin();

      if (isAutoPlay && !_autoPlayPaused) {
        await Future.delayed(_autoPlayDelay);
      }
    }
  }

  /// Toggle paytable display
  void togglePaytable() {
    _showPaytable = !_showPaytable;
    notifyListeners();
  }

  /// Toggle settings display
  void toggleSettings() {
    _showSettings = !_showSettings;
    notifyListeners();
  }

  /// Update sound setting
  void setSoundEnabled(bool enabled) {
    _soundEnabled = enabled;
    notifyListeners();
  }

  /// Update haptics setting
  void setHapticsEnabled(bool enabled) {
    _hapticsEnabled = enabled;
    notifyListeners();
  }

  /// Update animations setting
  void setAnimationsEnabled(bool enabled) {
    _animationsEnabled = enabled;
    notifyListeners();
  }

  /// Update spin speed
  void setSpinSpeed(double speed) {
    _spinSpeed = speed.clamp(0.5, 2.0);
    notifyListeners();
  }

  /// Set auto play delay
  void setAutoPlayDelay(Duration delay) {
    _autoPlayDelay = delay;
    notifyListeners();
  }

  /// Reset game statistics
  void resetStats() {
    _engine.resetStats();
    _lastResult = null;
    _flashingWinLines.clear();
    _updateStatusMessage();
    notifyListeners();
  }

  /// Get symbol at specific position
  SlotSymbol getSymbolAt(int reel, int row) {
    if (_lastResult == null) return SlotSymbol.cherry;
    if (reel < 0 || reel >= _lastResult!.reels.length) return SlotSymbol.cherry;
    if (row < 0 || row >= _lastResult!.reels[reel].length) return SlotSymbol.cherry;

    return _lastResult!.reels[reel][row];
  }

  /// Check if position is part of winning line
  bool isWinningPosition(int reel, int row) {
    if (_lastResult == null) return false;

    final gridPosition = row * config.reelCount + reel;

    return _flashingWinLines.any((line) => 
        line.positions.contains(gridPosition));
  }

  /// Start spin animation
  void _startSpinAnimation() {
    _setAnimationState(SlotAnimationState.spinning);
    _reelSpinning = List.filled(config.reelCount, true);
    _flashingWinLines.clear();
    _statusMessage = 'Spinning...';
  }

  /// Animate reels stopping with staggered timing
  Future<void> _animateReelStopping(SpinResult result) async {
    _setAnimationState(SlotAnimationState.stopping);

    // Stop reels one by one with delay
    for (int i = 0; i < config.reelCount; i++) {
      await Future.delayed(Duration(milliseconds: (200 / _spinSpeed).round()));
      _reelSpinning[i] = false;

      if (_soundEnabled) {
        _playSound('reel_stop');
      }

      if (_hapticsEnabled && i == config.reelCount - 1) {
        HapticFeedback.lightImpact();
      }

      notifyListeners();
    }
  }

  /// Celebrate winning result
  Future<void> _celebrateWin(SpinResult result) async {
    _setAnimationState(SlotAnimationState.celebrating);

    if (result.isJackpot) {
      _statusMessage = '🎰 JACKPOT! You won ${result.totalWin}!';
      if (_soundEnabled) _playSound('jackpot');
      if (_hapticsEnabled) HapticFeedback.heavyImpact();
    } else if (result.isBigWin) {
      _statusMessage = '💎 BIG WIN! You won ${result.totalWin}!';
      if (_soundEnabled) _playSound('big_win');
      if (_hapticsEnabled) HapticFeedback.mediumImpact();
    } else {
      _statusMessage = '🎉 You won ${result.totalWin}!';
      if (_soundEnabled) _playSound('win');
      if (_hapticsEnabled) HapticFeedback.lightImpact();
    }

    // Flash winning paylines
    if (_animationsEnabled) {
      await _flashWinLines(result.winLines);
    }

    _setAnimationState(SlotAnimationState.idle);
  }

  /// Flash winning paylines animation
  Future<void> _flashWinLines(List<WinLine> winLines) async {
    _setAnimationState(SlotAnimationState.paylineFlash);

    for (int flash = 0; flash < 3; flash++) {
      _flashingWinLines = winLines;
      notifyListeners();
      await Future.delayed(const Duration(milliseconds: 300));

      _flashingWinLines.clear();
      notifyListeners();
      await Future.delayed(const Duration(milliseconds: 200));
    }
  }

  /// Set animation state and notify
  void _setAnimationState(SlotAnimationState state) {
    _animationState = state;
    notifyListeners();
  }

  /// Play sound effect
  Future<void> _playSound(String soundName) async {
    try {
      await _audioPlayer.play(AssetSource('sounds/$soundName.mp3'));
    } catch (e) {
      debugPrint('Failed to play sound $soundName: $e');
    }
  }

  /// Update status message based on game state
  void _updateStatusMessage() {
    if (!canSpin && !isDemoMode) {
      _statusMessage = 'Insufficient balance';
    } else if (isAutoPlay) {
      _statusMessage = 'Auto play: $autoPlayRemaining spins remaining';
    } else {
      _statusMessage = 'Ready to spin!';
    }
  }

  @override
  void dispose() {
    _audioPlayer.dispose();
    super.dispose();
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';
import '../slots_engine.dart';
import '../../../ui/theme/app_theme.dart';

/// Animated spinning reel widget for slot machine
class ReelWidget extends StatefulWidget {
  final int reelIndex;
  final List<SlotSymbol> symbols;
  final bool isSpinning;
  final double spinSpeed;
  final bool isWinningReel;
  final List<bool> winningPositions;
  final VoidCallback? onSpinComplete;

  const ReelWidget({
    super.key,
    required this.reelIndex,
    required this.symbols,
    required this.isSpinning,
    this.spinSpeed = 1.0,
    this.isWinningReel = false,
    this.winningPositions = const [false, false, false],
    this.onSpinComplete,
  });

  @override
  State<ReelWidget> createState() => _ReelWidgetState();
}

class _ReelWidgetState extends State<ReelWidget>
    with TickerProviderStateMixin {
  late AnimationController _spinController;
  late AnimationController _stopController;
  late AnimationController _winController;

  late Animation<double> _spinAnimation;
  late Animation<double> _stopAnimation;
  late Animation<double> _winGlowAnimation;

  bool _wasPreviouslySpinning = false;

  @override
  void initState() {
    super.initState();
    _initializeAnimations();
  }

  void _initializeAnimations() {
    // Continuous spin animation
    _spinController = AnimationController(
      duration: Duration(milliseconds: (1000 / widget.spinSpeed).round()),
      vsync: this,
    );

    _spinAnimation = Tween<double>(
      begin: 0.0,
      end: 1.0,
    ).animate(CurvedAnimation(
      parent: _spinController,
      curve: Curves.linear,
    ));

    // Stop animation with bounce effect
    _stopController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );

    _stopAnimation = Tween<double>(
      begin: 0.0,
      end: 1.0,
    ).animate(CurvedAnimation(
      parent: _stopController,
      curve: Curves.elasticOut,
    ));

    // Win glow animation
    _winController = AnimationController(
      duration: const Duration(milliseconds: 1500),
      vsync: this,
    );

    _winGlowAnimation = Tween<double>(
      begin: 0.0,
      end: 1.0,
    ).animate(CurvedAnimation(
      parent: _winController,
      curve: Curves.easeInOut,
    ));
  }

  @override
  void didUpdateWidget(ReelWidget oldWidget) {
    super.didUpdateWidget(oldWidget);

    // Handle spin state changes
    if (widget.isSpinning != oldWidget.isSpinning) {
      if (widget.isSpinning) {
        _startSpinning();
      } else {
        _stopSpinning();
      }
    }

    // Handle win state changes
    if (widget.isWinningReel != oldWidget.isWinningReel) {
      if (widget.isWinningReel) {
        _startWinAnimation();
      } else {
        _winController.reset();
      }
    }

    // Update spin speed
    if (widget.spinSpeed != oldWidget.spinSpeed && widget.isSpinning) {
      _updateSpinSpeed();
    }
  }

  void _startSpinning() {
    _winController.reset();
    _stopController.reset();
    _spinController.repeat();
    _wasPreviouslySpinning = true;
  }

  void _stopSpinning() {
    if (_wasPreviouslySpinning) {
      _spinController.stop();
      _stopController.forward().then((_) {
        widget.onSpinComplete?.call();
      });
      _wasPreviouslySpinning = false;
    }
  }

  void _startWinAnimation() {
    _winController.repeat(reverse: true);
  }

  void _updateSpinSpeed() {
    if (_spinController.isAnimating) {
      _spinController.duration = Duration(
        milliseconds: (1000 / widget.spinSpeed).round(),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return Container(
      width: 80,
      height: 240,
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: theme.casinoColors.glassBorder,
          width: 2,
        ),
        gradient: LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            theme.casinoColors.glassBackground.withOpacity(0.3),
            theme.casinoColors.glassBackground.withOpacity(0.1),
            theme.casinoColors.glassBackground.withOpacity(0.3),
          ],
        ),
        boxShadow: widget.isWinningReel
            ? CasinoColors.getNeonGlow(CasinoColors.gold, intensity: 0.8)
            : CasinoColors.glassMorphismShadow,
      ),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(10),
        child: AnimatedBuilder(
          animation: Listenable.merge([
            _spinAnimation,
            _stopAnimation,
            _winGlowAnimation,
          ]),
          builder: (context, child) {
            return Stack(
              children: [
                // Background pattern
                _buildReelBackground(),

                // Symbol column
                _buildSymbolColumn(),

                // Win glow overlay
                if (widget.isWinningReel) _buildWinGlow(),

                // Reel frame overlay
                _buildReelFrame(),
              ],
            );
          },
        ),
      ),
    );
  }

  Widget _buildReelBackground() {
    return Container(
      width: double.infinity,
      height: double.infinity,
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          colors: [
            Colors.black.withOpacity(0.1),
            Colors.transparent,
            Colors.black.withOpacity(0.1),
          ],
        ),
      ),
    );
  }

  Widget _buildSymbolColumn() {
    return Transform.translate(
      offset: Offset(0, _getSpinOffset()),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          // Extra symbols above for smooth spinning effect
          if (widget.isSpinning) ..._buildSpinningSymbols(),

          // Actual visible symbols
          for (int i = 0; i < widget.symbols.length; i++)
            _buildSymbolCell(widget.symbols[i], i),

          // Extra symbols below for smooth spinning effect
          if (widget.isSpinning) ..._buildSpinningSymbols(),
        ],
      ),
    );
  }

  double _getSpinOffset() {
    if (widget.isSpinning) {
      return -(_spinAnimation.value * 240); // Height of 3 symbols
    } else if (_stopController.isAnimating) {
      return -(_stopAnimation.value * 20); // Bounce effect
    }
    return 0;
  }

  List<Widget> _buildSpinningSymbols() {
    // Generate random symbols for spinning effect
    final spinSymbols = SlotSymbol.values.toList()..shuffle();
    return spinSymbols.take(6).map((symbol) => 
        _buildSymbolCell(symbol, -1, isSpinning: true)).toList();
  }

  Widget _buildSymbolCell(SlotSymbol symbol, int position, {bool isSpinning = false}) {
    final isWinning = !isSpinning && 
        position >= 0 && 
        position < widget.winningPositions.length && 
        widget.winningPositions[position];

    return Container(
      width: 76,
      height: 76,
      margin: const EdgeInsets.all(2),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(8),
        color: isWinning 
            ? CasinoColors.gold.withOpacity(0.2)
            : Colors.white.withOpacity(0.05),
        border: isWinning 
            ? Border.all(color: CasinoColors.gold, width: 2)
            : null,
        boxShadow: isWinning 
            ? CasinoColors.getNeonGlow(CasinoColors.gold, intensity: 0.5)
            : null,
      ),
      child: Center(
        child: Text(
          symbol.emoji,
          style: TextStyle(
            fontSize: isWinning ? 32 : 28,
            fontWeight: isWinning ? FontWeight.bold : FontWeight.normal,
          ),
        ).animate(target: isWinning ? 1 : 0)
         .scale(
           duration: const Duration(milliseconds: 300),
           begin: const Offset(1.0, 1.0),
           end: const Offset(1.1, 1.1),
         ),
      ),
    );
  }

  Widget _buildWinGlow() {
    return Positioned.fill(
      child: Container(
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(10),
          gradient: RadialGradient(
            center: Alignment.center,
            radius: 1.0,
            colors: [
              CasinoColors.gold.withOpacity(0.3 * _winGlowAnimation.value),
              CasinoColors.goldGlow.withOpacity(0.1 * _winGlowAnimation.value),
              Colors.transparent,
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildReelFrame() {
    return Positioned.fill(
      child: Container(
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(10),
          border: Border.all(
            color: widget.isWinningReel 
                ? CasinoColors.gold.withOpacity(0.8)
                : Colors.white.withOpacity(0.2),
            width: widget.isWinningReel ? 3 : 1,
          ),
        ),
      ),
    );
  }

  @override
  void dispose() {
    _spinController.dispose();
    _stopController.dispose();
    _winController.dispose();
    super.dispose();
  }
}

/// Symbol info display for paytable
class SymbolInfo extends StatelessWidget {
  final SlotSymbol symbol;
  final int baseMultiplier;
  final bool showMultipliers;

  const SymbolInfo({
    super.key,
    required this.symbol,
    required this.baseMultiplier,
    this.showMultipliers = true,
  });

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return Container(
      padding: const EdgeInsets.all(12),
      margin: const EdgeInsets.symmetric(vertical: 4),
      decoration: BoxDecoration(
        color: theme.casinoColors.glassBackground,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: theme.casinoColors.glassBorder,
          width: 1,
        ),
      ),
      child: Row(
        children: [
          // Symbol display
          Container(
            width: 50,
            height: 50,
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(8),
              color: Colors.white.withOpacity(0.1),
            ),
            child: Center(
              child: Text(
                symbol.emoji,
                style: const TextStyle(fontSize: 24),
              ),
            ),
          ),

          const SizedBox(width: 16),

          // Symbol name and description
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  _getSymbolName(symbol),
                  style: theme.textTheme.titleSmall?.copyWith(
                    color: theme.casinoColors.textPrimary,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                if (showMultipliers) ...[
                  const SizedBox(height: 4),
                  Text(
                    _getPayoutText(symbol, baseMultiplier),
                    style: theme.textTheme.bodySmall?.copyWith(
                      color: CasinoColors.gold,
                    ),
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }

  String _getSymbolName(SlotSymbol symbol) {
    switch (symbol) {
      case SlotSymbol.cherry:
        return 'Cherry';
      case SlotSymbol.lemon:
        return 'Lemon';
      case SlotSymbol.orange:
        return 'Orange';
      case SlotSymbol.plum:
        return 'Plum';
      case SlotSymbol.bell:
        return 'Bell';
      case SlotSymbol.bar:
        return 'Bar';
      case SlotSymbol.seven:
        return 'Lucky Seven';
      case SlotSymbol.diamond:
        return 'Diamond';
      case SlotSymbol.crown:
        return 'Crown';
      case SlotSymbol.jackpot:
        return 'Jackpot';
    }
  }

  String _getPayoutText(SlotSymbol symbol, int bet) {
    final base = symbol.multiplier * bet;
    return '3x: ${base}  4x: ${(base * 2.5).round()}  5x: ${base * 5}';
  }
}

import 'package:flutter/material.dart';
