                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      // Roulette Wheel
                      AnimatedBuilder(
                        animation: _controller,
                        builder: (context, child) {
                          return Transform.rotate(
                            angle: _controller.value * 10 * pi,
                            child: Container(
                              width: 200,
                              height: 200,
                              decoration: BoxDecoration(
