// BLACKJACK SCREEN
class BlackjackScreen extends StatefulWidget {
  const BlackjackScreen({Key? key}) : super(key: key);

  @override
  State<BlackjackScreen> createState() => _BlackjackScreenState();
}

class _BlackjackScreenState extends State<BlackjackScreen> {
  List<String> playerCards = [];
  List<String> dealerCards = [];
  bool gameStarted = false;
  bool gameOver = false;
  String? result;

  void startGame() {
    final vm = context.read<CasinoViewModel>();
    if (!vm.canBet()) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Insufficient balance!')),
      );
      return;
    }

    vm.placeBet();

    setState(() {
      playerCards = vm.dealCards(2);
      dealerCards = vm.dealCards(2);
      gameStarted = true;
      gameOver = false;
      result = null;
    });

    checkBlackjack();
  }

  void hit() {
    final vm = context.read<CasinoViewModel>();
    setState(() {
      playerCards.add(vm.dealCards(1).first);
    });

    if (getHandValue(playerCards) > 21) {
      endGame('BUST! You lose!');
    }
  }

  void stand() {
    final vm = context.read<CasinoViewModel>();

    // Dealer draws cards
    while (getHandValue(dealerCards) < 17) {
      setState(() {
        dealerCards.add(vm.dealCards(1).first);
      });
    }

    final playerValue = getHandValue(playerCards);
    final dealerValue = getHandValue(dealerCards);

    if (dealerValue > 21) {
      endGame('Dealer bust! You win!');
      vm.addWinnings(vm.currentBet * 2);
    } else if (playerValue > dealerValue) {
      endGame('You win!');
      vm.addWinnings(vm.currentBet * 2);
    } else if (playerValue < dealerValue) {
      endGame('Dealer wins!');
    } else {
      endGame('Push! It\'s a tie!');
      vm.addWinnings(vm.currentBet);
    }
  }

  void checkBlackjack() {
    final playerValue = getHandValue(playerCards);
    final dealerValue = getHandValue(dealerCards);

    if (playerValue == 21 && playerCards.length == 2) {
      if (dealerValue == 21 && dealerCards.length == 2) {
        endGame('Both have Blackjack! Push!');
        context.read<CasinoViewModel>().addWinnings(
          context.read<CasinoViewModel>().currentBet
        );
      } else {
        endGame('BLACKJACK! You win!');
        context.read<CasinoViewModel>().addWinnings(
          context.read<CasinoViewModel>().currentBet * 2.5
        );
      }
    }
  }

  void endGame(String message) {
    setState(() {
      gameOver = true;
      result = message;
    });
  }

  int getHandValue(List<String> cards) {
    final vm = context.read<CasinoViewModel>();
    int value = 0;
    int aces = 0;

    for (final card in cards) {
      final cardValue = vm.getCardValue(card);
      value += cardValue;
      if (card == 'A') aces++;
    }

    while (value > 21 && aces > 0) {
      value -= 10;
      aces--;
    }

    return value;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('BLACKJACK'),
        backgroundColor: Colors.green.withOpacity(0.3),
      ),
      body: Stack(
        children: [
          const AnimatedBackground(),
          Column(
            children: [
              const BalanceHeader(),

              Expanded(
                child: Center(
                  child: Container(
                    padding: const EdgeInsets.all(20),
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        // Dealer cards
                        Column(
                          children: [
                            const Text(
                              'DEALER',
                              style: TextStyle(
                                fontSize: 20,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                            const SizedBox(height: 10),
                            Row(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: dealerCards.map((card) => Card(
                                margin: const EdgeInsets.all(5),
                                color: Colors.black.withOpacity(0.7),
                                child: Padding(
                                  padding: const EdgeInsets.all(15),
                                  child: Text(
                                    card,
                                    style: const TextStyle(
                                      fontSize: 32,
                                      color: Colors.white,
                                    ),
                                  ),
                                ),
                              )).toList(),
                            ),
                            if (gameOver)
                              Text(
                                'Value: ${getHandValue(dealerCards)}',
                                style: const TextStyle(fontSize: 18),
                              ),
                          ],
                        ),

                        const SizedBox(height: 40),

                        // Result
                        if (result != null)
                          Container(
                            padding: const EdgeInsets.all(15),
                            decoration: BoxDecoration(
                              color: result!.contains('win') 
                                  ? Colors.green.withOpacity(0.3)
                                  : Colors.red.withOpacity(0.3),
                              borderRadius: BorderRadius.circular(10),
                            ),
                            child: Text(
                              result!,
                              style: const TextStyle(
                                fontSize: 24,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                          ),

                        const SizedBox(height: 40),

                        // Player cards
                        Column(
                          children: [
                            const Text(
                              'PLAYER',
                              style: TextStyle(
                                fontSize: 20,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                            const SizedBox(height: 10),
                            Row(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: playerCards.map((card) => Card(
                                margin: const EdgeInsets.all(5),
                                color: Colors.black.withOpacity(0.7),
                                child: Padding(
                                  padding: const EdgeInsets.all(15),
                                  child: Text(
                                    card,
                                    style: const TextStyle(
                                      fontSize: 32,
                                      color: Colors.white,
                                    ),
                                  ),
                                ),
                              )).toList(),
                            ),
                            if (gameStarted)
                              Text(
                                'Value: ${getHandValue(playerCards)}',
                                style: const TextStyle(fontSize: 18),
                              ),
                          ],
                        ),

                        const SizedBox(height: 30),

                        // Bet controls
                        if (!gameStarted) BetControls(),

                        const SizedBox(height: 20),

                        // Game controls
                        if (!gameStarted)
                          ElevatedButton(
                            key: const Key('dealButton'),
                            onPressed: startGame,
                            style: ElevatedButton.styleFrom(
                              backgroundColor: Colors.green,
                              padding: const EdgeInsets.symmetric(
                                horizontal: 50,
                                vertical: 20,
                              ),
                            ),
                            child: const Text(
                              'DEAL',
                              style: TextStyle(
                                fontSize: 24,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                          ),

                        if (gameStarted && !gameOver)
                          Row(
                            mainAxisAlignment: MainAxisAlignment.center,
                            children: [
                              ElevatedButton(
                                key: const Key('hitButton'),
                                onPressed: hit,
                                style: ElevatedButton.styleFrom(
                                  backgroundColor: Colors.blue,
                                  padding: const EdgeInsets.all(20),
                                ),
                                child: const Text(
                                  'HIT',
                                  style: TextStyle(fontSize: 20),
                                ),
                              ),
                              const SizedBox(width: 20),
                              ElevatedButton(
                                key: const Key('standButton'),
                                onPressed: stand,
                                style: ElevatedButton.styleFrom(
                                  backgroundColor: Colors.orange,
                                  padding: const EdgeInsets.all(20),
                                ),
                                child: const Text(
                                  'STAND',
                                  style: TextStyle(fontSize: 20),
                                ),
                              ),
                            ],
                          ),

                        if (gameOver)
                          ElevatedButton(
                            key: const Key('newGameButton'),
                            onPressed: () {
                              setState(() {
                                playerCards = [];
                                dealerCards = [];
                                gameStarted = false;
                                gameOver = false;
                                result = null;
                              });
                            },
                            style: ElevatedButton.styleFrom(
                              backgroundColor: Colors.green,
                              padding: const EdgeInsets.all(20),
                            ),
                            child: const Text(
                              'NEW GAME',
                              style: TextStyle(fontSize: 20),
                            ),
                          ),
                      ],
                    ),
                  ),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

// DEMO MODE SCREEN
class DemoModeScreen extends StatefulWidget {
  const DemoModeScreen({Key? key}) : super(key: key);

  @override
  State<DemoModeScreen> createState() => _DemoModeScreenState();
}

class _DemoModeScreenState extends State<DemoModeScreen> {
  bool isRunning = false;
  List<String> log = [];

  void runDemo() async {
    if (isRunning) return;

    setState(() {
      isRunning = true;
      log = ['Starting demo mode...'];
    });

    final vm = context.read<CasinoViewModel>();

    // Run 10 rounds of each game
    for (int i = 0; i < 10; i++) {
      await Future.delayed(const Duration(milliseconds: 500));

      // Slots
      final slotsResult = vm.spinSlots();
      setState(() {
        log.add('Slots: ${slotsResult.join(" ")}');
      });

      await Future.delayed(const Duration(milliseconds: 500));

      // Roulette
      final rouletteResult = vm.spinRoulette('color', i % 2 == 0 ? 'red' : 'black');
      setState(() {
        log.add('Roulette: $rouletteResult');
      });

      if (log.length > 10) {
        setState(() {
          log.removeAt(0);
        });
      }
    }

    setState(() {
      isRunning = false;
      log.add('Demo complete! Balance: \$${vm.balance.toStringAsFixed(2)}');
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('DEMO MODE'),
        backgroundColor: Colors.blue.withOpacity(0.3),
      ),
      body: Stack(
        children: [
          const AnimatedBackground(),
          Column(
            children: [
              const BalanceHeader(),

              Expanded(
                child: Container(
                  margin: const EdgeInsets.all(20),
                  padding: const EdgeInsets.all(20),
                  decoration: BoxDecoration(
                    color: Colors.black.withOpacity(0.5),
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(
                      color: Colors.blue.withOpacity(0.5),
                      width: 2,
                    ),
                  ),
                  child: Column(
                    children: [
                      const Text(
                        'AUTO-PLAY LOG',
                        style: TextStyle(
                          fontSize: 20,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      const SizedBox(height: 20),

                      Expanded(
                        child: ListView.builder(
                          itemCount: log.length,
                          itemBuilder: (context, index) {
                            return Padding(
                              padding: const EdgeInsets.symmetric(vertical: 5),
                              child: Text(
                                log[index],
                                style: TextStyle(
                                  fontSize: 16,
                                  color: Colors.white.withOpacity(0.9),
                                ),
                              ),
                            );
                          },
                        ),
                      ),

                      const SizedBox(height: 20),

                      ElevatedButton(
                        key: const Key('runDemoButton'),
                        onPressed: isRunning ? null : runDemo,
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.blue,
                          padding: const EdgeInsets.symmetric(
                            horizontal: 50,
                            vertical: 20,
                          ),
                        ),
                        child: Text(
                          isRunning ? 'RUNNING...' : 'RUN DEMO',
                          style: const TextStyle(
                            fontSize: 20,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

// Bet Controls Widget
class BetControls extends StatelessWidget {
  const BetControls({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Consumer<CasinoViewModel>(
      builder: (context, vm, _) {
        return Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            IconButton(
              key: const Key('decreaseBetButton'),
              onPressed: () => vm.setBet(vm.currentBet - 10),
              icon: const Icon(Icons.remove_circle, size: 32),
              color: Colors.red,
            ),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 10),
              decoration: BoxDecoration(
                color: Colors.black.withOpacity(0.5),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: Colors.amber),
              ),
              child: Text(
                'BET: \$${vm.currentBet.toStringAsFixed(0)}',
                style: const TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
            IconButton(
              key: const Key('increaseBetButton'),
              onPressed: () => vm.setBet(vm.currentBet + 10),
              icon: const Icon(Icons.add_circle, size: 32),
              color: Colors.green,
            ),
          ],
        );
      },
    );
  }
}

