/// Premium glass panel with gold accents
class PremiumGlassPanel extends StatelessWidget {
  const PremiumGlassPanel({
    super.key,
    required this.child,
    this.width,
    this.height,
    this.padding = const EdgeInsets.all(24),
    this.margin = const EdgeInsets.all(12),
    this.title,
    this.subtitle,
    this.onTap,
  });

  final Widget child;
  final double? width;
  final double? height;
  final EdgeInsetsGeometry padding;
  final EdgeInsetsGeometry margin;
  final String? title;
  final String? subtitle;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final casinoColors = theme.casinoColors;

    return GlassContainer(
      width: width,
      height: height,
      margin: margin,
      borderRadius: 28,
      blurIntensity: 20,
      opacity: 0.2,
      borderOpacity: 0.4,
      shadowIntensity: 0.5,
      glowEffect: true,
      glowColor: casinoColors.primaryGold,
      glowIntensity: 0.3,
      onTap: onTap,
      border: Border.all(
        color: casinoColors.primaryGold.withOpacity(0.3),
        width: 2,
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (title != null || subtitle != null) ...[
            _buildHeader(theme, casinoColors),
            const SizedBox(height: 16),
          ],
          Expanded(
            child: Padding(
              padding: padding,
              child: child,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildHeader(ThemeData theme, CasinoColorScheme colors) {
    return Container(
      padding: const EdgeInsets.fromLTRB(24, 16, 24, 8),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          colors: [
            colors.primaryGold.withOpacity(0.1),
            Colors.transparent,
          ],
        ),
        border: Border(
          bottom: BorderSide(
            color: colors.primaryGold.withOpacity(0.2),
            width: 1,
          ),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (title != null)
            Text(
              title!,
              style: theme.textTheme.titleLarge?.copyWith(
                color: colors.primaryGold,
                fontWeight: FontWeight.bold,
              ),
            ),
          if (subtitle != null) ...[
            const SizedBox(height: 4),
            Text(
              subtitle!,
              style: theme.textTheme.bodyMedium?.copyWith(
                color: colors.textSecondary,
              ),
            ),
          ],
        ],
      ),
    );
  }
}

/// Floating glass container with enhanced effects
class FloatingGlassContainer extends StatefulWidget {
  const FloatingGlassContainer({
    super.key,
    required this.child,
    this.width,
    this.height,
    this.padding = const EdgeInsets.all(20),
    this.margin = const EdgeInsets.all(10),
    this.onTap,
    this.animationDuration = const Duration(milliseconds: 300),
    this.hoverEffect = true,
  });

  final Widget child;
  final double? width;
  final double? height;
  final EdgeInsetsGeometry padding;
  final EdgeInsetsGeometry margin;
  final VoidCallback? onTap;
  final Duration animationDuration;
  final bool hoverEffect;

  @override
  State<FloatingGlassContainer> createState() => _FloatingGlassContainerState();
}

class _FloatingGlassContainerState extends State<FloatingGlassContainer>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<double> _scaleAnimation;
  late Animation<double> _elevationAnimation;
  bool _isHovered = false;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      duration: widget.animationDuration,
      vsync: this,
    );
    _scaleAnimation = Tween<double>(begin: 1.0, end: 1.05).animate(
      CurvedAnimation(parent: _controller, curve: Curves.easeInOut),
    );
    _elevationAnimation = Tween<double>(begin: 0.3, end: 0.8).animate(
      CurvedAnimation(parent: _controller, curve: Curves.easeInOut),
    );
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _handleHover(bool isHovered) {
    if (!widget.hoverEffect) return;

    setState(() {
      _isHovered = isHovered;
    });

    if (isHovered) {
      _controller.forward();
    } else {
      _controller.reverse();
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final casinoColors = theme.casinoColors;

    return MouseRegion(
      onEnter: (_) => _handleHover(true),
      onExit: (_) => _handleHover(false),
      child: AnimatedBuilder(
        animation: _controller,
        builder: (context, child) {
          return Transform.scale(
            scale: _scaleAnimation.value,
            child: GlassContainer(
              width: widget.width,
              height: widget.height,
              padding: widget.padding,
              margin: widget.margin,
              borderRadius: 24,
              blurIntensity: 12,
              opacity: 0.12,
              borderOpacity: _isHovered ? 0.4 : 0.25,
              shadowIntensity: _elevationAnimation.value,
              glowEffect: _isHovered,
              glowColor: casinoColors.primaryGold,
              glowIntensity: 0.4,
              onTap: widget.onTap,
              child: widget.child,
            ),
          );
        },
      ),
    );
  }
}

