import 'dart:io';

import 'package:flutter_keycheck/src/cli/cli_runner.dart';
import 'package:flutter_keycheck/src/commands/base_command_v3.dart';
import 'package:flutter_keycheck/src/config/config_v3.dart' as config_v3;
import 'package:flutter_keycheck/src/models/scan_result.dart';
import 'package:flutter_keycheck/src/policy/policy_engine.dart';
import 'package:flutter_keycheck/src/policy/policy_engine_v3.dart';
import 'package:flutter_keycheck/src/scanner/ast_scanner_v3.dart';
import 'package:flutter_keycheck/src/models/validation_result.dart';
import 'package:path/path.dart' as path;

/// Validate command - CI gate enforcement (primary command)
class ValidateCommandV3 extends BaseCommandV3 {
  @override
  final name = 'validate';

  @override
  final description = 'Validate keys against policies (CI gate enforcement)';

  @override
  final aliases = ['ci-validate']; // Alias for CI usage

  ValidateCommandV3() {
    argParser
      ..addFlag(
        'strict',
        help: 'Enable strict validation mode',
        defaultsTo: false,
      )
      ..addFlag(
        'fail-on-lost',
        help: 'Fail if keys are lost (not found in scan)',
        defaultsTo: true,
      )
      ..addFlag(
        'fail-on-rename',
        help: 'Fail if keys are renamed',
        defaultsTo: false,
      )
      ..addFlag(
        'fail-on-extra',
        help: 'Fail if extra keys are found',
        defaultsTo: false,
      )
      ..addFlag(
        'fail-on-package-missing',
        help: 'Fail if keys are in packages but missing in app',
        defaultsTo: false,
      )
      ..addFlag(
        'fail-on-collision',
        help: 'Fail if keys are declared in multiple sources',
        defaultsTo: false,
      )
      ..addMultiOption(
        'protected-tags',
        help: 'Tags that cannot be lost or renamed',
        defaultsTo: ['critical', 'aqa'],
      )
      ..addOption(
        'max-drift',
        help: 'Maximum allowed drift percentage',
        defaultsTo: '10',
      )
      ..addMultiOption(
        'report',
        help: 'Report formats to generate',
        allowed: ['json', 'junit', 'md'],
        defaultsTo: ['json'],
      )
      ..addOption(
        'baseline',
        help: 'Baseline source (registry, file path)',
        defaultsTo: 'registry',
      );
  }

  @override
  Future<int> run() async {
    try {
      logInfo('🔍 Validating keys...');

      final config = await loadConfig();
      final outDir = await ensureOutputDir();

      // Load or fetch baseline
      final baseline = await _loadBaseline(config);
      if (baseline == null) {
        logError(
            'No baseline found. Run "flutter_keycheck baseline create" first.');
        return ExitCode.invalidConfig;
      }

      // Perform current scan
      logVerbose('Scanning current project state...');
      String projectRoot;
      final specifiedRoot = argResults!['project-root'] as String?;
      if (specifiedRoot != null) {
        // Convert to absolute path and normalize
        final dir = Directory(specifiedRoot).absolute;
        projectRoot = path.normalize(dir.path);
      } else {
        projectRoot = Directory.current.path;
      }

      final scanner = AstScannerV3(
        projectPath: projectRoot,
        config: config,
      );
      final scanResult = await scanner.scan();

      // Configure policy engine
      final policyEngine = PolicyEngine();

      // Create policy config from arguments
      final policyConfig = PolicyConfig(
        failOnLost: argResults!['fail-on-lost'] as bool,
        failOnRename: argResults!['fail-on-rename'] as bool,
        failOnExtra: argResults!['fail-on-extra'] as bool,
        protectedTags: argResults!['protected-tags'] as List<String>,
        maxDrift: double.parse(argResults!['max-drift'] as String),
      );

      // Run validation
      final validationResult = policyEngine.validate(
        baseline: baseline,
        current: scanResult,
        config: policyConfig,
      );

      // Check package policies if enabled
      PackagePolicyResult? packagePolicyResult;
      if (argResults!['fail-on-package-missing'] as bool ||
          argResults!['fail-on-collision'] as bool) {
        packagePolicyResult = PolicyEngineV3.checkPackagePolicies(
          keyUsages: scanResult.keyUsages,
          failOnPackageMissing: argResults!['fail-on-package-missing'] as bool,
          failOnCollision: argResults!['fail-on-collision'] as bool,
        );

        // Add violations to validation result if policies failed
        if (!packagePolicyResult.passed) {
          if (packagePolicyResult.missingInApp.isNotEmpty &&
              argResults!['fail-on-package-missing'] as bool) {
            for (final key in packagePolicyResult.missingInApp) {
              validationResult.violations.add(Violation(
                type: 'package-missing',
                severity: 'error',
                key: KeyInfo(
                  id: key,
                  status: 'missing',
                  package: 'unknown',
                  tags: [],
                ),
                message: 'Key "$key" found in package but missing in app',
                remediation:
                    'Add the key to your app or remove it from the package',
                policy: 'failOnPackageMissing',
              ));
            }
          }

          if (packagePolicyResult.collisions.isNotEmpty &&
              argResults!['fail-on-collision'] as bool) {
            for (final collision in packagePolicyResult.collisions) {
              validationResult.violations.add(Violation(
                type: 'collision',
                severity: 'error',
                key: KeyInfo(
                  id: collision.key,
                  status: 'collision',
                  package: collision.sources.join(', '),
                  tags: [],
                ),
                message:
                    'Key "${collision.key}" declared in multiple sources: ${collision.sources.join(", ")}',
                remediation: 'Ensure each key is declared in only one source',
                policy: 'failOnCollision',
              ));
            }
          }
        }
      }

      // Log results
      _logValidationResults(validationResult);
      if (packagePolicyResult != null) {
        _logPackagePolicyResults(packagePolicyResult);
      }

      // Generate reports
      final formats = argResults!['report'] as List<String>;
      for (final format in formats) {
        final reporter = getReporter(format);
        final reportFile = File(path.join(
          outDir.path,
          'validation-report.${_getExtension(format)}',
        ));
        await reporter.generateValidationReport(validationResult, reportFile);
        logInfo(
            '📊 ${format.toUpperCase()} report saved to: ${reportFile.path}');
      }

      // Return appropriate exit code
      if (validationResult.hasViolations) {
        logError(
            '❌ Validation failed with ${validationResult.violations.length} violations');
        return ExitCode.policyViolation;
      } else {
        logInfo('✅ All validation checks passed!');
        return ExitCode.ok;
      }
    } catch (e) {
      return handleError(e);
    }
  }

  Future<ScanResult?> _loadBaseline(config_v3.ConfigV3 config) async {
    final baselineSource = argResults!['baseline'] as String;

    if (baselineSource == 'registry') {
      // Load from registry
      final registry = await getRegistry(config);
      return await registry.getBaseline();
    } else {
      // Load from file
      final file = File(baselineSource);
      if (!await file.exists()) {
        return null;
      }
      return ScanResult.fromJson(await file.readAsString());
    }
  }

  void _logValidationResults(ValidationResult result) {
    logInfo('📊 Validation Summary:');
    logInfo('  • Total keys: ${result.summary.totalKeys}');
    logInfo('  • Lost keys: ${result.summary.lostKeys}');
    logInfo('  • Added keys: ${result.summary.addedKeys}');
    logInfo('  • Renamed keys: ${result.summary.renamedKeys}');
    logInfo('  • Drift: ${result.summary.driftPercentage.toStringAsFixed(1)}%');

    if (result.violations.isNotEmpty) {
      logWarning('⚠️ Violations found:');
      for (final violation in result.violations) {
        logError('  • [${violation.severity}] ${violation.message}');
        if (argResults!['verbose'] as bool) {
          logVerbose('    Remediation: ${violation.remediation}');
        }
      }
    }

    if (result.warnings.isNotEmpty) {
      logWarning('⚠️ Warnings:');
      for (final warning in result.warnings) {
        logWarning('  • $warning');
      }
    }
  }

  void _logPackagePolicyResults(PackagePolicyResult result) {
    if (!result.passed) {
      logInfo('📦 Package Policy Results:');

      if (result.missingInApp.isNotEmpty) {
        logWarning(
            '  • Keys in packages but missing in app: ${result.missingInApp.length}');
        if (argResults!['verbose'] as bool) {
          for (final key in result.missingInApp) {
            logVerbose('    - $key');
          }
        }
      }

      if (result.collisions.isNotEmpty) {
        logWarning('  • Key collisions detected: ${result.collisions.length}');
        if (argResults!['verbose'] as bool) {
          for (final collision in result.collisions) {
            logVerbose(
                '    - ${collision.key}: ${collision.sources.join(", ")}');
          }
        }
      }
    }
  }

  String _getExtension(String format) {
    switch (format) {
      case 'json':
        return 'json';
      case 'junit':
        return 'xml';
      case 'md':
        return 'md';
      default:
        return format;
    }
  }
}

import 'dart:io';

import 'package:flutter_keycheck/src/commands/base_command.dart';
import 'package:flutter_keycheck/src/scanner/ast_scanner_v3.dart';
import 'package:flutter_keycheck/src/validator/policy_validator.dart';
import 'package:flutter_keycheck/src/models/validation_result.dart';

/// Validate command for CI gate enforcement
class ValidateCommand extends BaseCommand {
  @override
  final String name = 'validate';

  @override
  final String description = 'CI gate: enforce policies on key changes';

  ValidateCommand() {
    argParser
      ..addFlag(
        'fail-on-lost',
        help: 'Fail if keys are lost',
        defaultsTo: true,
      )
      ..addFlag(
        'fail-on-rename',
        help: 'Fail if keys are renamed',
        defaultsTo: false,
      )
      ..addFlag(
        'fail-on-extra',
        help: 'Fail if extra keys are found',
        defaultsTo: false,
      )
      ..addOption(
        'max-drift',
        help: 'Maximum allowed drift percentage',
        defaultsTo: '0',
      )
      ..addMultiOption(
        'report',
        help: 'Output formats (can specify multiple)',
        allowed: ['json', 'junit', 'md', 'text'],
        defaultsTo: ['text'],
      )
      ..addOption(
        'out-dir',
        help: 'Output directory for reports',
        defaultsTo: './reports',
      )
      ..addMultiOption(
        'protected-tags',
        help: 'Tags that must not be lost',
        defaultsTo: ['critical', 'aqa'],
      );
  }

  @override
  Future<int> run() async {
    try {
      final config = await loadConfig();

      // Get registry
      final registry = await getRegistry(config);
      final keyRegistry = await registry.load();

      // Use project-root if specified, otherwise current directory
      String projectRoot;
      if (argResults!.wasParsed('project-root')) {
        final specifiedRoot = argResults!['project-root'] as String;
        // Convert to absolute path
        projectRoot = Directory(specifiedRoot).absolute.path;
      } else {
        projectRoot = Directory.current.path;
      }

      // Scan current workspace
      final scanner = AstScannerV3(
        projectPath: projectRoot,
        includeTests: false,
        includeGenerated: false,
        config: config,
      );
      final snapshot = await scanner.scan();

      // Create validator with policies
      final validator = PolicyValidator();

      // Validate
      final result = await validator.validate(snapshot);

      // Generate reports
      final formats = argResults!['report'] as List<String>;
      final outDir = argResults!['out-dir'] as String;

      // Ensure output directory exists
      final dir = Directory(outDir);
      if (!await dir.exists()) {
        await dir.create(recursive: true);
      }

      // Generate each requested report format
      for (final format in formats) {
        final reporter = getReporter(config, format);
        final report = reporter.generateValidationReport(result);

        if (format == 'text') {
          // Print to stdout for human consumption
          stdout.writeln(report);
        } else {
          // Save to file
          final reportFile =
              File('$outDir/validation-report.${reporter.extension}');
          await reportFile.writeAsString(report);
          if (config.verbose) {
            stdout.writeln('📄 Generated $format report: ${reportFile.path}');
          }
        }
      }

      // Print summary
      _printSummary(result);

      // Determine exit code based on violations
      if (result.hasViolations) {
        stderr.writeln(
            '\n❌ Validation failed with ${result.totalViolations} violations');
        return BaseCommand.exitPolicyViolation;
      }

      stdout.writeln('\n✅ All validation checks passed');
      return BaseCommand.exitOk;
    } catch (e) {
      return handleError(e);
    }
  }

  void _printSummary(ValidationResult result) {
    stdout.writeln('\n📊 Validation Summary:');

    if (result.lostKeys.isNotEmpty) {
      stdout.writeln('  🔥 Lost keys: ${result.lostKeys.length}');
      if (argResults!['verbose'] as bool) {
        for (final key in result.lostKeys.take(5)) {
          stdout.writeln('     - ${key.id} (${key.tags.join(', ')})');
        }
        if (result.lostKeys.length > 5) {
          stdout.writeln('     ... and ${result.lostKeys.length - 5} more');
        }
      }
    }

    if (result.renamedKeys.isNotEmpty) {
      stdout.writeln('  ♻️  Renamed keys: ${result.renamedKeys.length}');
      if (argResults!['verbose'] as bool) {
        for (final rename in result.renamedKeys.take(3)) {
          stdout.writeln('     - ${rename.oldId} → ${rename.newId}');
        }
        if (result.renamedKeys.length > 3) {
          stdout.writeln('     ... and ${result.renamedKeys.length - 3} more');
        }
      }
    }

    if (result.extraKeys.isNotEmpty) {
      stdout.writeln('  ➕ Extra keys: ${result.extraKeys.length}');
    }

    if (result.deprecatedInUse.isNotEmpty) {
      stdout.writeln(
          '  ⚠️ Deprecated keys in use: ${result.deprecatedInUse.length}');
    }

    if (result.removedInUse.isNotEmpty) {
      stdout.writeln('  🚫 Removed keys in use: ${result.removedInUse.length}');
    }

    stdout.writeln('  📈 Drift: ${result.driftPercentage.toStringAsFixed(1)}%');
  }
}

import 'dart:io';

import 'package:path/path.dart' as path;
import 'package:yaml/yaml.dart';

/// Configuration class for flutter_keycheck CLI tool
///
/// Supports loading configuration from YAML files and merging with CLI arguments.
/// The configuration hierarchy is: CLI arguments > Config file > Defaults
class FlutterKeycheckConfig {
  /// Path to the YAML file containing expected keys
  final String? keys;

  /// Path to the Flutter project to scan
  final String? projectPath;

  /// Whether to enable strict mode (fail if integration test setup incomplete)
  final bool? strict;

  /// Whether to enable verbose output
  final bool? verbose;

  /// Whether to fail if extra keys are found
  final bool? failOnExtra;

  /// List of patterns to include only matching keys
  final List<String>? includeOnly;

  /// List of patterns to exclude matching keys
  final List<String>? exclude;

  /// Subset of keys to track/validate (when present, only these keys are checked)
  final List<String>? trackedKeys;

  /// Output report format (human, json, html, markdown, junit)
  final String? report;

  /// Export configuration for reports
  final String? exportPath;

  /// Quality thresholds (v3 features)
  final Map<String, dynamic>? qualityThresholds;

  /// Enable AST-based scanning (v3 feature)
  final bool? useAstScanning;

  /// Include test files in AST scanning
  final bool? includeTestsInAst;

  /// Cache directory for performance optimization
  final String? cacheDir;

  /// Enable performance metrics
  final bool? enableMetrics;

  const FlutterKeycheckConfig({
    this.keys,
    this.projectPath,
    this.strict,
    this.verbose,
    this.failOnExtra,
    this.includeOnly,
    this.exclude,
    this.trackedKeys,
    this.report,
    this.exportPath,
    this.qualityThresholds,
    this.useAstScanning,
    this.includeTestsInAst,
    this.cacheDir,
    this.enableMetrics,
  });

  /// Creates a default configuration with sensible defaults
  factory FlutterKeycheckConfig.defaults() {
    return const FlutterKeycheckConfig(
      keys: 'keys/expected_keys.yaml',
      projectPath: '.',
      strict: false,
      verbose: false,
      failOnExtra: false,
      includeOnly: null,
      exclude: null,
      trackedKeys: null,
      report: 'human',
      exportPath: null,
      qualityThresholds: null,
      useAstScanning: false, // Default to false for backward compatibility
      includeTestsInAst: false,
      cacheDir: '.flutter_keycheck_cache',
      enableMetrics: false,
    );
  }

  /// Loads configuration from a YAML file
  ///
  /// Returns null if file doesn't exist or has invalid format.
  /// Prints appropriate messages for user feedback.
  static FlutterKeycheckConfig? loadFromFile(String configPath) {
    final file = File(configPath);

    if (!file.existsSync()) {
      return null;
    }

    try {
      final content = file.readAsStringSync();
      final yaml = loadYaml(content) as YamlMap?;

      if (yaml == null) {
        return null;
      }

      print('📄 Loaded config from $configPath ✅');

      return FlutterKeycheckConfig(
        keys: yaml['keys']?.toString(),
        projectPath: yaml['path']?.toString(),
        strict: yaml['strict'] as bool?,
        verbose: yaml['verbose'] as bool?,
        failOnExtra: yaml['fail_on_extra'] as bool?,
        includeOnly: (yaml['include_only'] as YamlList?)
            ?.map((e) => e.toString())
            .toList(),
        exclude:
            (yaml['exclude'] as YamlList?)?.map((e) => e.toString()).toList(),
        trackedKeys: (yaml['tracked_keys'] as YamlList?)
            ?.map((e) => e.toString())
            .toList(),
        report: yaml['report']?.toString(),
        exportPath: yaml['export_path']?.toString(),
        qualityThresholds: yaml['quality_thresholds'] as Map<String, dynamic>?,
        useAstScanning: yaml['use_ast_scanning'] as bool?,
        includeTestsInAst: yaml['include_tests_in_ast'] as bool?,
        cacheDir: yaml['cache_dir']?.toString(),
        enableMetrics: yaml['enable_metrics'] as bool?,
      );
    } catch (e) {
      print('⚠️ Error reading $configPath: $e');
      return null;
    }
  }

  /// Merges this configuration with CLI arguments
  ///
  /// CLI arguments take priority over configuration file values.
  FlutterKeycheckConfig mergeWith({
    String? keys,
    String? projectPath,
    bool? strict,
    bool? verbose,
    bool? failOnExtra,
    List<String>? includeOnly,
    List<String>? exclude,
    List<String>? trackedKeys,
    String? report,
    String? exportPath,
    Map<String, dynamic>? qualityThresholds,
    bool? useAstScanning,
    bool? includeTestsInAst,
    String? cacheDir,
    bool? enableMetrics,
  }) {
    return FlutterKeycheckConfig(
      keys: keys ?? this.keys,
      projectPath: projectPath ?? this.projectPath,
      strict: strict ?? this.strict,
      verbose: verbose ?? this.verbose,
      failOnExtra: failOnExtra ?? this.failOnExtra,
      includeOnly: includeOnly ?? this.includeOnly,
      exclude: exclude ?? this.exclude,
      trackedKeys: trackedKeys ?? this.trackedKeys,
      report: report ?? this.report,
      exportPath: exportPath ?? this.exportPath,
      qualityThresholds: qualityThresholds ?? this.qualityThresholds,
      useAstScanning: useAstScanning ?? this.useAstScanning,
      includeTestsInAst: includeTestsInAst ?? this.includeTestsInAst,
      cacheDir: cacheDir ?? this.cacheDir,
      enableMetrics: enableMetrics ?? this.enableMetrics,
    );
  }

  /// Returns the effective keys file path, resolving relative paths
  String getKeysPath() {
    final keysPath = keys ?? 'keys/expected_keys.yaml';
    if (path.isAbsolute(keysPath)) {
      return keysPath;
    }
    return path.join(projectPath ?? '.', keysPath);
  }

  /// Returns the effective project path
  String getProjectPath() {
    return projectPath ?? '.';
  }

  /// Returns whether strict mode is enabled
  bool isStrict() {
    return strict ?? false;
  }

  /// Returns whether verbose mode is enabled
  bool isVerbose() {
    return verbose ?? false;
  }

  /// Returns whether to fail on extra keys
  bool shouldFailOnExtra() {
    return failOnExtra ?? false;
  }

  /// Returns the effective include-only patterns
  List<String> getIncludeOnly() {
    return includeOnly ?? [];
  }

  /// Returns the effective exclude patterns
  List<String> getExclude() {
    return exclude ?? [];
  }

  /// Returns the tracked keys list (subset of keys to validate)
  ///
  /// When present, only these keys are validated against the project.
  /// If null or empty, all keys from the expected keys file are validated.
  List<String>? getTrackedKeys() {
    return trackedKeys;
  }

  /// Returns the effective report format
  String getReportFormat() {
    return report ?? 'human';
  }

  /// Returns true if tracked keys feature is enabled
  bool hasTrackedKeys() {
    return trackedKeys != null && trackedKeys!.isNotEmpty;
  }

  /// Returns the export path for reports
  String? getExportPath() {
    return exportPath;
  }

  /// Returns quality thresholds configuration
  Map<String, dynamic> getQualityThresholds() {
    return qualityThresholds ?? {};
  }

  /// Returns whether AST scanning is enabled
  bool isAstScanningEnabled() {
    return useAstScanning ?? false;
  }

  /// Returns whether to include tests in AST scanning
  bool shouldIncludeTestsInAst() {
    return includeTestsInAst ?? false;
  }

  /// Returns the cache directory path
  String getCacheDir() {
    return cacheDir ?? '.flutter_keycheck_cache';
  }

  /// Returns whether metrics are enabled
  bool areMetricsEnabled() {
    return enableMetrics ?? false;
  }

  @override
  String toString() {
    return 'FlutterKeycheckConfig{'
        'keys: $keys, '
        'projectPath: $projectPath, '
        'strict: $strict, '
        'verbose: $verbose, '
        'failOnExtra: $failOnExtra, '
        'includeOnly: $includeOnly, '
        'exclude: $exclude, '
        'trackedKeys: $trackedKeys, '
        'report: $report, '
        'exportPath: $exportPath, '
        'qualityThresholds: $qualityThresholds, '
        'useAstScanning: $useAstScanning, '
        'includeTestsInAst: $includeTestsInAst, '
        'cacheDir: $cacheDir, '
        'enableMetrics: $enableMetrics'
        '}';
  }
}

import 'dart:io';
import 'package:yaml/yaml.dart';

/// Configuration for flutter_keycheck v3
class ConfigV3 {
  String version = '3';
  bool monorepo = false;
  bool verbose = false;

  // Registry settings
  final RegistryConfig registry;

  // Scanning settings
  final ScanConfig scan;

  // Policy settings
  final PolicyConfig policies;

  // Reporting settings
  final ReportConfig report;

  ConfigV3({
    required this.registry,
    required this.scan,
    required this.policies,
    required this.report,
  });

  /// Load configuration from file
  static Future<ConfigV3> load(String path) async {
    final file = File(path);

    // Create default config if file doesn't exist
    if (!await file.exists()) {
      return ConfigV3.defaults();
    }

    final content = await file.readAsString();

    // Parse YAML with error handling
    Map yaml;
    try {
      final parsedYaml = loadYaml(content);
      if (parsedYaml == null) {
        throw FormatException('Empty YAML file');
      }
      if (parsedYaml is! Map) {
        throw FormatException('YAML root must be a map');
      }
      yaml = parsedYaml;
    } catch (e) {
      throw FormatException('Invalid YAML configuration: $e');
    }

    return ConfigV3(
      registry: RegistryConfig.fromYaml(yaml['registry'] ?? {}),
      scan: ScanConfig.fromYaml(yaml['scan'] ?? {}),
      policies: PolicyConfig.fromYaml(yaml['policies'] ?? {}),
      report: ReportConfig.fromYaml(yaml['report'] ?? {}),
    )
      ..version = yaml['version']?.toString() ?? '3'
      ..monorepo = yaml['monorepo'] ?? false;
  }

  /// Create default configuration
  factory ConfigV3.defaults() {
    return ConfigV3(
      registry: RegistryConfig.defaults(),
      scan: ScanConfig.defaults(),
      policies: PolicyConfig.defaults(),
      report: ReportConfig.defaults(),
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'version': version,
      'monorepo': monorepo,
      'registry': registry.toMap(),
      'scan': scan.toMap(),
      'policies': policies.toMap(),
      'report': report.toMap(),
    };
  }
}

/// Registry configuration
class RegistryConfig {
  String type;
  String? repo;
  String? branch;
  String? path;
  String? url;
  String? package;

  RegistryConfig({
    required this.type,
    this.repo,
    this.branch,
    this.path,
    this.url,
    this.package,
  });

  factory RegistryConfig.fromYaml(Map yaml) {
    return RegistryConfig(
      type: yaml['type'] ?? 'git',
      repo: yaml['repo'],
      branch: yaml['branch'] ?? 'main',
      path: yaml['path'] ?? 'key-registry.yaml',
      url: yaml['url'],
      package: yaml['package'],
    );
  }

  factory RegistryConfig.defaults() {
    return RegistryConfig(
      type: 'git',
      branch: 'main',
      path: 'key-registry.yaml',
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'type': type,
      'repo': repo,
      'branch': branch,
      'path': path,
      'url': url,
      'package': package,
    };
  }
}

/// Scan configuration
class ScanConfig {
  String packages;
  bool includeTests;
  bool includeGenerated;
  List<String> excludePatterns;
  List<String>? includeOnly;
  List<String>? trackedKeys;

  ScanConfig({
    required this.packages,
    required this.includeTests,
    required this.includeGenerated,
    required this.excludePatterns,
    this.includeOnly,
    this.trackedKeys,
  });

  factory ScanConfig.fromYaml(Map yaml) {
    return ScanConfig(
      packages: yaml['packages'] ?? 'workspace',
      includeTests: yaml['include_tests'] ?? false,
      includeGenerated: yaml['include_generated'] ?? false,
      excludePatterns: List<String>.from(yaml['exclude_patterns'] ?? []),
      includeOnly: yaml['include_only'] != null
          ? List<String>.from(yaml['include_only'])
          : null,
      trackedKeys: yaml['tracked_keys'] != null
          ? List<String>.from(yaml['tracked_keys'])
          : null,
    );
  }

  factory ScanConfig.defaults() {
    return ScanConfig(
      packages: 'workspace',
      includeTests: false,
      includeGenerated: false,
      excludePatterns: [
        '**/*.g.dart',
        '**/*.freezed.dart',
      ],
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'packages': packages,
      'include_tests': includeTests,
      'include_generated': includeGenerated,
      'exclude_patterns': excludePatterns,
      if (includeOnly != null) 'include_only': includeOnly,
      if (trackedKeys != null) 'tracked_keys': trackedKeys,
    };
  }
}

