/// Configuration for metrics collection
class MetricsConfig {
  final bool enableSystemMetrics;
  final bool enablePerformanceMetrics;
  final bool enableQualityMetrics;
  final bool enableCacheMetrics;
  final bool enableTelemetry;
  final Duration samplingInterval;
  final String outputPath;
  final bool anonymizeData;

  const MetricsConfig({
    this.enableSystemMetrics = true,
    this.enablePerformanceMetrics = true,
    this.enableQualityMetrics = true,
    this.enableCacheMetrics = true,
    this.enableTelemetry = false,
    this.samplingInterval = const Duration(seconds: 1),
    this.outputPath = '.flutter_keycheck_metrics',
    this.anonymizeData = true,
  });
}

/// Comprehensive metrics collector
class MetricsCollector {
  final MetricsConfig config;
  final bool verbose;
  final String projectPath;

  final List<SystemMetrics> _systemSamples = [];
  final Map<String, Duration> _operationTimings = {};
  final Map<String, Stopwatch> _activeTimers = {};
  final List<String> _errors = [];
  final Map<String, dynamic> _customMetrics = {};

  int _filesScanned = 0;
  int _keysFound = 0;
  int _duplicateKeys = 0;
  int _missingKeys = 0;
  int _extraKeys = 0;
  double _coveragePercent = 0.0;

  MetricsCollector({
    required this.projectPath,
    this.config = const MetricsConfig(),
    this.verbose = false,
  });

  /// Start collecting metrics
  Future<void> startCollection() async {
    if (verbose) {
      print('📊 Starting metrics collection');
    }

    if (config.enableSystemMetrics) {
      await _startSystemMetricsCollection();
    }
  }

  /// Stop collecting metrics and generate report
  Future<MetricsReport> stopCollectionAndGenerateReport({
    QualityMetrics? qualityMetrics,
    CacheMetrics? cacheMetrics,
  }) async {
    if (verbose) {
      print('📊 Stopping metrics collection and generating report');
    }

    final systemMetrics = await _generateSystemMetrics();
    final scanMetrics = _generateScanMetrics();
    final finalQualityMetrics = qualityMetrics ?? _generateDefaultQualityMetrics();
    final finalCacheMetrics = cacheMetrics ?? _generateDefaultCacheMetrics();

    final report = MetricsReport(
      system: systemMetrics,
      scan: scanMetrics,
      quality: finalQualityMetrics,
      cache: finalCacheMetrics,
      generatedAt: DateTime.now(),
      version: '3.1.10', // TODO: Get from pubspec
      customMetrics: Map.from(_customMetrics),
    );

    if (config.outputPath.isNotEmpty) {
      await _saveReport(report);
    }

    return report;
  }

  /// Start timing an operation
  void startOperation(String operationName) {
    _activeTimers[operationName] = Stopwatch()..start();

    if (verbose) {
      print('⏱️  Started timing: $operationName');
    }
  }

  /// Stop timing an operation
  void stopOperation(String operationName) {
    final timer = _activeTimers.remove(operationName);
    if (timer != null) {
      timer.stop();
      _operationTimings[operationName] = 
          (_operationTimings[operationName] ?? Duration.zero) + timer.elapsed;

      if (verbose) {
        print('⏱️  Stopped timing: $operationName (${timer.elapsedMilliseconds}ms)');
      }
    }
  }

  /// Record file scanning activity
  void recordFileScanned(String filePath) {
    _filesScanned++;

    // Track file type distribution
    final extension = filePath.split('.').last.toLowerCase();
    final currentCount = _customMetrics['fileTypes'] as Map<String, int>? ?? {};
    currentCount[extension] = (currentCount[extension] ?? 0) + 1;
    _customMetrics['fileTypes'] = currentCount;
  }

  /// Record key discovery
  void recordKeyFound(String keyName) {
    _keysFound++;

    // Track key patterns
    final patterns = _customMetrics['keyPatterns'] as Map<String, int>? ?? {};
    final pattern = _extractKeyPattern(keyName);
    patterns[pattern] = (patterns[pattern] ?? 0) + 1;
    _customMetrics['keyPatterns'] = patterns;
  }

  /// Record scan results
  void recordScanResults({
    required int duplicateKeys,
    required int missingKeys,
    required int extraKeys,
    required double coveragePercent,
  }) {
    _duplicateKeys = duplicateKeys;
    _missingKeys = missingKeys;
    _extraKeys = extraKeys;
    _coveragePercent = coveragePercent;
  }

  /// Record an error
  void recordError(String error) {
    _errors.add(error);

    if (verbose) {
      print('❌ Error recorded: $error');
    }
  }

  /// Add custom metric
  void addCustomMetric(String key, dynamic value) {
    _customMetrics[key] = value;
  }

  /// Increment custom counter
  void incrementCustomCounter(String key, [int amount = 1]) {
    _customMetrics[key] = (_customMetrics[key] as int? ?? 0) + amount;
  }

  /// Start system metrics collection
  Future<void> _startSystemMetricsCollection() async {
    // Collect initial system metrics
    try {
      final systemMetrics = await _collectCurrentSystemMetrics();
      _systemSamples.add(systemMetrics);
    } catch (e) {
      if (verbose) {
        print('⚠️ Failed to collect system metrics: $e');
      }
    }
  }

  /// Collect current system metrics
  Future<SystemMetrics> _collectCurrentSystemMetrics() async {
    final timestamp = DateTime.now();
    final processId = pid;
    final platform = Platform.operatingSystem;

    double memoryUsageMB = 0.0;
    double cpuUsagePercent = 0.0;
    double diskUsageMB = 0.0;

    // Try to get memory usage (platform-specific)
    try {
      if (Platform.isLinux || Platform.isMacOS) {
        final result = await Process.run('ps', ['-o', 'rss,pcpu', '-p', '$processId']);
        if (result.exitCode == 0) {
          final lines = result.stdout.toString().trim().split('\n');
          if (lines.length > 1) {
            final parts = lines[1].trim().split(RegExp(r'\s+'));
            if (parts.length >= 2) {
              memoryUsageMB = (int.tryParse(parts[0]) ?? 0) / 1024.0; // Convert KB to MB
              cpuUsagePercent = double.tryParse(parts[1]) ?? 0.0;
            }
          }
        }
      }
    } catch (e) {
      // System metrics not available
    }

    // Get disk usage for project path
    try {
      if (Directory(projectPath).existsSync()) {
        final result = await Process.run('du', ['-sm', projectPath]);
        if (result.exitCode == 0) {
          final output = result.stdout.toString().trim();
          final sizeMB = int.tryParse(output.split('\t')[0]) ?? 0;
          diskUsageMB = sizeMB.toDouble();
        }
      }
    } catch (e) {
      // Disk usage calculation failed
    }

    final environmentInfo = {
      'dart_version': Platform.version,
      'os_version': Platform.operatingSystemVersion,
      'locale': Platform.localeName,
      'is_debug': bool.fromEnvironment('dart.vm.debug', defaultValue: false),
      'executable': Platform.executable,
    };

    return SystemMetrics(
      cpuUsagePercent: cpuUsagePercent,
      memoryUsageMB: memoryUsageMB,
      diskUsageMB: diskUsageMB,
      processId: processId,
      timestamp: timestamp,
      platform: platform,
      environmentInfo: environmentInfo,
    );
  }

  /// Generate system metrics summary
  Future<SystemMetrics> _generateSystemMetrics() async {
    if (_systemSamples.isEmpty) {
      return await _collectCurrentSystemMetrics();
    }

    // Calculate averages from samples
    final avgCpu = _systemSamples.map((s) => s.cpuUsagePercent)
        .reduce((a, b) => a + b) / _systemSamples.length;
    final avgMemory = _systemSamples.map((s) => s.memoryUsageMB)
        .reduce((a, b) => a + b) / _systemSamples.length;
    final avgDisk = _systemSamples.map((s) => s.diskUsageMB)
        .reduce((a, b) => a + b) / _systemSamples.length;

    final latest = _systemSamples.last;

    return SystemMetrics(
      cpuUsagePercent: avgCpu,
      memoryUsageMB: avgMemory,
      diskUsageMB: avgDisk,
      processId: latest.processId,
      timestamp: latest.timestamp,
      platform: latest.platform,
      environmentInfo: latest.environmentInfo,
    );
  }

  /// Generate scan metrics summary
  ScanMetrics _generateScanMetrics() {
    final totalDuration = _operationTimings.values.fold(
        Duration.zero, (sum, duration) => sum + duration);

    final fileTypes = _customMetrics['fileTypes'] as Map<String, int>? ?? {};

    return ScanMetrics(
      totalDuration: totalDuration,
      filesScanned: _filesScanned,
      keysFound: _keysFound,
      duplicateKeys: _duplicateKeys,
      missingKeys: _missingKeys,
      extraKeys: _extraKeys,
      coveragePercent: _coveragePercent,
      fileTypeDistribution: Map.from(fileTypes),
      operationTimings: Map.from(_operationTimings),
      errorsEncountered: List.from(_errors),
    );
  }

  /// Generate default quality metrics when not provided
  QualityMetrics _generateDefaultQualityMetrics() {
    final issuesFound = _missingKeys + _duplicateKeys + _errors.length;
    final overallScore = _coveragePercent; // Simplified calculation

    return QualityMetrics(
      overallScore: overallScore,
      coverageScore: _coveragePercent,
      organizationScore: _duplicateKeys == 0 ? 100.0 : 50.0,
      consistencyScore: _errors.isEmpty ? 100.0 : 70.0,
      efficiencyScore: 85.0, // Default efficiency score
      maintainabilityScore: 80.0, // Default maintainability score
      issuesFound: issuesFound,
      recommendations: _generateBasicRecommendations(),
      severityDistribution: {
        'high': _missingKeys,
        'medium': _duplicateKeys,
        'low': _errors.length,
      },
    );
  }

  /// Generate default cache metrics when not provided
  CacheMetrics _generateDefaultCacheMetrics() {
    return const CacheMetrics(
      hitCount: 0,
      missCount: 0,
      hitRate: 0.0,
      totalEntries: 0,
      sizeMB: 0.0,
      averageAccessTime: Duration.zero,
      operationCounts: {},
    );
  }

  /// Generate basic recommendations
  List<String> _generateBasicRecommendations() {
    final recommendations = <String>[];

    if (_missingKeys > 0) {
      recommendations.add('Add $_missingKeys missing keys to improve coverage');
    }

    if (_duplicateKeys > 0) {
      recommendations.add('Review $_duplicateKeys duplicate keys for optimization');
    }

    if (_errors.isNotEmpty) {
      recommendations.add('Fix ${_errors.length} errors encountered during scan');
    }

    if (_coveragePercent < 80) {
      recommendations.add('Improve key coverage to meet quality standards');
    }

    if (recommendations.isEmpty) {
      recommendations.add('All metrics look good - maintain current quality standards');
    }

    return recommendations;
  }

  /// Extract key pattern for analysis
  String _extractKeyPattern(String keyName) {
    if (keyName.contains('button') || keyName.contains('btn')) return 'button';
    if (keyName.contains('text') || keyName.contains('label')) return 'text';
    if (keyName.contains('field') || keyName.contains('input')) return 'input';
    if (keyName.contains('screen') || keyName.contains('page')) return 'screen';
    if (keyName.contains('dialog') || keyName.contains('modal')) return 'dialog';
    if (keyName.contains('menu') || keyName.contains('nav')) return 'navigation';
    return 'other';
  }

  /// Save metrics report to file
  Future<void> _saveReport(MetricsReport report) async {
    try {
      final outputDir = Directory(config.outputPath);
      if (!outputDir.existsSync()) {
        outputDir.createSync(recursive: true);
      }

      final timestamp = DateTime.now().toIso8601String()
          .replaceAll(':', '-')
          .replaceAll('.', '-');
      final filename = 'metrics_$timestamp.json';
      final file = File('${config.outputPath}/$filename');

      final jsonData = jsonEncode(report.toJson());
      await file.writeAsString(jsonData);

      if (verbose) {
        print('📊 Metrics report saved to: ${file.path}');
      }
    } catch (e) {
      if (verbose) {
        print('⚠️ Failed to save metrics report: $e');
      }
    }
  }
}

import 'package:flutter_keycheck/src/models/scan_result.dart';

/// Result of comparing two snapshots
class DiffResult {
  final Set<String> added;
  final Set<String> removed;
  final Map<String, String> renamed;
  final Set<String> unchanged;
  final ScanResult baseline;
  final ScanResult current;

  DiffResult({
    required this.added,
    required this.removed,
    required this.renamed,
    required this.unchanged,
    required this.baseline,
    required this.current,
  });

  bool get hasChanges =>
      added.isNotEmpty || removed.isNotEmpty || renamed.isNotEmpty;

  int get totalChanges => added.length + removed.length + renamed.length;

  double get driftPercentage {
    final totalKeys = baseline.keyUsages.length;
    if (totalKeys == 0) return 0.0;
    return (totalChanges / totalKeys * 100);
  }

  Map<String, dynamic> toMap() {
    return {
      'added': added.toList(),
      'removed': removed.toList(),
      'renamed': renamed,
      'unchanged': unchanged.toList(),
      'total_changes': totalChanges,
      'drift_percentage': driftPercentage,
      'has_changes': hasChanges,
    };
  }
}

import 'dart:convert';
import 'package:yaml/yaml.dart';

/// Key Registry schema v1
class KeyRegistry {
  final int version;
  final bool monorepo;
  final List<PackageKeys> packages;
  final RegistryPolicies policies;
  final DateTime? lastUpdated;

  KeyRegistry({
    this.version = 1,
    this.monorepo = false,
    required this.packages,
    required this.policies,
    this.lastUpdated,
  });

  factory KeyRegistry.fromYaml(String yaml) {
    final doc = loadYaml(yaml) as Map;

    return KeyRegistry(
      version: doc['version'] as int? ?? 1,
      monorepo: doc['monorepo'] as bool? ?? false,
      packages: (doc['packages'] as List? ?? [])
          .map((p) => PackageKeys.fromMap(p as Map<dynamic, dynamic>))
          .toList(),
      policies: RegistryPolicies.fromMap(
        doc['policies'] as Map<dynamic, dynamic>? ?? {},
      ),
      lastUpdated: doc['last_updated'] != null
          ? DateTime.parse(doc['last_updated'] as String)
          : null,
    );
  }

  factory KeyRegistry.fromJson(String json) {
    final map = jsonDecode(json) as Map<String, dynamic>;

    return KeyRegistry(
      version: map['version'] as int? ?? 1,
      monorepo: map['monorepo'] as bool? ?? false,
      packages: (map['packages'] as List? ?? [])
          .map((p) => PackageKeys.fromMap(p as Map<String, dynamic>))
          .toList(),
      policies: RegistryPolicies.fromMap(
        map['policies'] as Map<String, dynamic>? ?? {},
      ),
      lastUpdated: map['last_updated'] != null
          ? DateTime.parse(map['last_updated'] as String)
          : null,
    );
  }

  Map<String, dynamic> toMap() => {
        'version': version,
        'monorepo': monorepo,
        'packages': packages.map((p) => p.toMap()).toList(),
        'policies': policies.toMap(),
        if (lastUpdated != null) 'last_updated': lastUpdated!.toIso8601String(),
      };

  String toYaml() {
    final buffer = StringBuffer();
    buffer.writeln('version: $version');
    buffer.writeln('monorepo: $monorepo');
    if (lastUpdated != null) {
      buffer.writeln('last_updated: ${lastUpdated!.toIso8601String()}');
    }

    buffer.writeln('packages:');
    for (final package in packages) {
      buffer.writeln('  - name: ${package.name}');
      buffer.writeln('    path: ${package.path}');
      buffer.writeln('    keys:');
      for (final key in package.keys) {
        buffer.writeln('      - id: "${key.id}"');
        buffer.writeln('        path: "${key.path}"');
        buffer.writeln('        tags: ${jsonEncode(key.tags)}');
        buffer.writeln('        status: "${key.status.name}"');
        if (key.notes != null) {
          buffer.writeln('        notes: "${key.notes}"');
        }
      }
    }

    buffer.writeln('policies:');
    buffer.writeln('  fail_on_lost: ${policies.failOnLost}');
    buffer.writeln('  fail_on_rename: ${policies.failOnRename}');
    buffer.writeln('  fail_on_extra: ${policies.failOnExtra}');
    buffer.writeln('  protected_tags: ${jsonEncode(policies.protectedTags)}');
    buffer.writeln('  drift_threshold: ${policies.driftThreshold}');

    return buffer.toString();
  }

  String toJson() => const JsonEncoder.withIndent('  ').convert(toMap());
}

/// Package-level key definitions
class PackageKeys {
  final String name;
  final String path;
  final List<KeyDefinition> keys;

  PackageKeys({
    required this.name,
    required this.path,
    required this.keys,
  });

  factory PackageKeys.fromMap(Map<dynamic, dynamic> map) {
    return PackageKeys(
      name: map['name'] as String,
      path: map['path'] as String? ?? '.',
      keys: (map['keys'] as List? ?? [])
          .map((k) => KeyDefinition.fromMap(k as Map<dynamic, dynamic>))
          .toList(),
    );
  }

  Map<String, dynamic> toMap() => {
        'name': name,
        'path': path,
        'keys': keys.map((k) => k.toMap()).toList(),
      };
}

/// Individual key definition
class KeyDefinition {
  final String id;
  final String path;
  final List<String> tags;
  final KeyStatus status;
  final String? notes;
  final DateTime? addedAt;
  final DateTime? deprecatedAt;

  KeyDefinition({
    required this.id,
    required this.path,
    this.tags = const [],
    this.status = KeyStatus.active,
    this.notes,
    this.addedAt,
    this.deprecatedAt,
  });

  factory KeyDefinition.fromMap(Map<dynamic, dynamic> map) {
    return KeyDefinition(
      id: map['id'] as String,
      path: map['path'] as String,
      tags: (map['tags'] as List? ?? []).cast<String>(),
      status: KeyStatus.values.firstWhere(
        (s) => s.name == (map['status'] as String? ?? 'active'),
        orElse: () => KeyStatus.active,
      ),
      notes: map['notes'] as String?,
      addedAt: map['added_at'] != null
          ? DateTime.parse(map['added_at'] as String)
          : null,
      deprecatedAt: map['deprecated_at'] != null
          ? DateTime.parse(map['deprecated_at'] as String)
          : null,
    );
  }

  Map<String, dynamic> toMap() => {
        'id': id,
        'path': path,
        'tags': tags,
        'status': status.name,
        if (notes != null) 'notes': notes,
        if (addedAt != null) 'added_at': addedAt!.toIso8601String(),
        if (deprecatedAt != null)
          'deprecated_at': deprecatedAt!.toIso8601String(),
      };

  bool hasTag(String tag) => tags.contains(tag);

  bool hasAnyTag(List<String> checkTags) =>
      checkTags.any((tag) => tags.contains(tag));
}

/// Key lifecycle status
enum KeyStatus {
  active,
  deprecated,
  reserved,
  removed,
}

/// Registry-level policies
class RegistryPolicies {
  final bool failOnLost;
  final bool failOnRename;
  final bool failOnExtra;
  final List<String> protectedTags;
  final int driftThreshold;
  final Map<String, dynamic> custom;

  RegistryPolicies({
    this.failOnLost = true,
    this.failOnRename = false,
    this.failOnExtra = false,
    this.protectedTags = const [],
    this.driftThreshold = 0,
    this.custom = const {},
  });

  factory RegistryPolicies.fromMap(Map<dynamic, dynamic> map) {
    return RegistryPolicies(
      failOnLost: map['fail_on_lost'] as bool? ?? true,
      failOnRename: map['fail_on_rename'] as bool? ?? false,
      failOnExtra: map['fail_on_extra'] as bool? ?? false,
      protectedTags: (map['protected_tags'] as List? ?? []).cast<String>(),
      driftThreshold: map['drift_threshold'] as int? ?? 0,
      custom: Map<String, dynamic>.from(map)
        ..removeWhere((key, _) => [
              'fail_on_lost',
              'fail_on_rename',
              'fail_on_extra',
              'protected_tags',
              'drift_threshold',
            ].contains(key)),
    );
  }

  Map<String, dynamic> toMap() => {
        'fail_on_lost': failOnLost,
        'fail_on_rename': failOnRename,
        'fail_on_extra': failOnExtra,
        'protected_tags': protectedTags,
        'drift_threshold': driftThreshold,
        ...custom,
      };
}

import 'scan_result.dart' show ScanResult;
export 'scan_result.dart' show ScanResult;

typedef KeySnapshot = ScanResult;

// This file is deprecated - use ScanMetrics from scan_result.dart instead
// Export the actual ScanMetrics from scan_result.dart for backward compatibility
export 'scan_result.dart' show ScanMetrics;

import 'dart:convert';

/// Complete scan result with metrics and coverage
class ScanResult {
  final ScanMetrics metrics;
  final Map<String, FileAnalysis> fileAnalyses;
  final Map<String, KeyUsage> keyUsages;
  final List<BlindSpot> blindSpots;
  final Duration duration;

  ScanResult({
    required this.metrics,
    required this.fileAnalyses,
    required this.keyUsages,
    required this.blindSpots,
    required this.duration,
  });

  Map<String, dynamic> toMap() {
    // Aggregate keys from all file analyses
    final aggregatedKeys = <Map<String, dynamic>>[];
    for (final entry in fileAnalyses.entries) {
      final fa = entry.value;
      for (final keyName in fa.keysFound) {
        // Try to find location info from keyUsages
        final usage = keyUsages[keyName];
        KeyLocation? location;
        if (usage != null && usage.locations.isNotEmpty) {
          try {
            location = usage.locations.firstWhere(
              (loc) => loc.file == fa.relativePath,
            );
          } catch (_) {
            // No matching location found
          }
        }

        aggregatedKeys.add({
          'key': keyName,
          'file': fa.relativePath,
          if (location != null && location.line > 0) 'line': location.line,
          if (usage?.source != null) 'source': usage!.source,
          if (usage?.package != null) 'package': usage!.package,
        });
      }
    }

    return {
      'schemaVersion': '1.0',
      'timestamp': DateTime.now().toIso8601String(),
      'keys': aggregatedKeys, // critical for tests
      'metrics': metrics.toMap(),
      'file_analyses': fileAnalyses.map((k, v) => MapEntry(k, v.toMap())),
      'key_usages': keyUsages.map((k, v) => MapEntry(k, v.toMap())),
      'blind_spots': blindSpots.map((e) => e.toMap()).toList(),
      'duration_ms': duration.inMilliseconds,
    };
  }

  factory ScanResult.fromMap(Map<String, dynamic> map) {
    return ScanResult(
      metrics: ScanMetrics.fromMap(map['metrics']),
      fileAnalyses: Map<String, FileAnalysis>.from(
        (map['file_analyses'] as Map).map(
          (k, v) => MapEntry(k, FileAnalysis.fromMap(v)),
        ),
      ),
      keyUsages: Map<String, KeyUsage>.from(
        (map['key_usages'] as Map).map(
          (k, v) => MapEntry(k, KeyUsage.fromMap(v)),
        ),
      ),
      blindSpots: List<BlindSpot>.from(
        (map['blind_spots'] as List).map((x) => BlindSpot.fromMap(x)),
      ),
      duration: Duration(milliseconds: map['duration_ms']),
    );
  }

  String toJson() => json.encode(toMap());

  factory ScanResult.fromJson(String source) =>
      ScanResult.fromMap(json.decode(source));
}

/// Scan metrics with coverage information
class ScanMetrics {
  int totalFiles = 0;
  int scannedFiles = 0;
  int totalLines = 0;
  int analyzedNodes = 0;
  double fileCoverage = 0;
  double widgetCoverage = 0;
  double handlerCoverage = 0;
  Map<String, int> detectorHits = {};
  List<ScanError> errors = [];
  bool incrementalScan = false;
  String? incrementalBase;
  Map<String, dynamic>? dependencyTree;

  // Performance optimization metrics
  int parallelFilesProcessed = 0;
  int cacheHits = 0;
  int cacheMisses = 0;
  int largeFilesProcessed = 0;
  double avgFileSizeKB = 0;
  Duration totalScanTime = Duration.zero;

  // Default constructor
  ScanMetrics();

  Map<String, dynamic> toMap() {
    return {
      'total_files': totalFiles,
      'scanned_files': scannedFiles,
      'total_lines': totalLines,
      'analyzed_nodes': analyzedNodes,
      'file_coverage': fileCoverage,
      'widget_coverage': widgetCoverage,
      'handler_coverage': handlerCoverage,
      'detector_hits': detectorHits,
      'errors': errors.map((e) => e.toMap()).toList(),
      'incremental_scan': incrementalScan,
      'incremental_base': incrementalBase,
      'parallel_files_processed': parallelFilesProcessed,
      'cache_hits': cacheHits,
      'cache_misses': cacheMisses,
      'cache_hit_rate': cacheHits + cacheMisses > 0
          ? '${(cacheHits / (cacheHits + cacheMisses) * 100).toStringAsFixed(1)}%'
          : '0%',
      'large_files_processed': largeFilesProcessed,
      'avg_file_size_kb': avgFileSizeKB.toStringAsFixed(1),
      'total_scan_time_ms': totalScanTime.inMilliseconds,
      if (dependencyTree != null) 'dependency_tree': dependencyTree,
    };
  }

  factory ScanMetrics.fromMap(Map<String, dynamic> map) {
    final metrics = ScanMetrics();
    metrics.totalFiles = map['total_files'] ?? 0;
    metrics.scannedFiles = map['scanned_files'] ?? 0;
    metrics.totalLines = map['total_lines'] ?? 0;
    metrics.analyzedNodes = map['analyzed_nodes'] ?? 0;
    metrics.fileCoverage = (map['file_coverage'] ?? 0).toDouble();
    metrics.widgetCoverage = (map['widget_coverage'] ?? 0).toDouble();
    metrics.handlerCoverage = (map['handler_coverage'] ?? 0).toDouble();
    metrics.detectorHits = Map<String, int>.from(map['detector_hits'] ?? {});
    metrics.errors = List<ScanError>.from(
      (map['errors'] ?? []).map((x) => ScanError.fromMap(x)),
    );
    metrics.incrementalScan = map['incremental_scan'] ?? false;
    metrics.incrementalBase = map['incremental_base'];
    metrics.parallelFilesProcessed = map['parallel_files_processed'] ?? 0;
    metrics.cacheHits = map['cache_hits'] ?? 0;
    metrics.cacheMisses = map['cache_misses'] ?? 0;
    metrics.largeFilesProcessed = map['large_files_processed'] ?? 0;
    metrics.avgFileSizeKB = (map['avg_file_size_kb'] ?? 0).toDouble();
    metrics.totalScanTime =
        Duration(milliseconds: map['total_scan_time_ms'] ?? 0);
    metrics.dependencyTree = map['dependency_tree'];
    return metrics;
  }
}

/// File-level analysis
class FileAnalysis {
  final String path;
  final String relativePath;
  final Set<String> keysFound = {};
  final Set<String> widgetTypes = {};
  final Set<String> uncoveredWidgetTypes = {};
  final List<String> functions = [];
  final List<String> methods = [];
  final Map<String, int> detectorHits = {};
  int nodesAnalyzed = 0;
  int widgetCount = 0;
  int widgetsWithKeys = 0;

  FileAnalysis({
    required this.path,
    required this.relativePath,
  });

  Map<String, dynamic> toMap() {
    return {
      'path': path,
      'relative_path': relativePath,
      'keys_found': keysFound.toList(),
      'widget_types': widgetTypes.toList(),
      'uncovered_widget_types': uncoveredWidgetTypes.toList(),
      'functions': functions,
      'methods': methods,
      'detector_hits': detectorHits,
      'nodes_analyzed': nodesAnalyzed,
      'widget_count': widgetCount,
      'widgets_with_keys': widgetsWithKeys,
    };
  }

  factory FileAnalysis.fromMap(Map<String, dynamic> map) {
    final analysis = FileAnalysis(
      path: map['path'],
      relativePath: map['relative_path'],
    );
    analysis.keysFound.addAll(List<String>.from(map['keys_found'] ?? []));
    analysis.widgetTypes.addAll(List<String>.from(map['widget_types'] ?? []));
    analysis.uncoveredWidgetTypes
        .addAll(List<String>.from(map['uncovered_widget_types'] ?? []));
    analysis.functions.addAll(List<String>.from(map['functions'] ?? []));
    analysis.methods.addAll(List<String>.from(map['methods'] ?? []));
    analysis.detectorHits
        .addAll(Map<String, int>.from(map['detector_hits'] ?? {}));
    analysis.nodesAnalyzed = map['nodes_analyzed'] ?? 0;
    analysis.widgetCount = map['widget_count'] ?? 0;
    analysis.widgetsWithKeys = map['widgets_with_keys'] ?? 0;
    return analysis;
  }
}

/// Key usage information
class KeyUsage {
  final String id;
  final List<KeyLocation> locations = [];
  final List<HandlerInfo> handlers = [];
  final Set<String> tags = {};
  String status = 'active';
  String? notes;
  String source = 'workspace'; // 'workspace' or 'package'
  String? package; // 'name@version' for deps

  KeyUsage({required this.id, this.source = 'workspace', this.package});

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'locations': locations.map((e) => e.toMap()).toList(),
      'handlers': handlers.map((e) => e.toMap()).toList(),
      'tags': tags.toList(),
      'status': status,
      'notes': notes,
      'source': source,
      'package': package,
    };
  }

  factory KeyUsage.fromMap(Map<String, dynamic> map) {
    final usage = KeyUsage(
      id: map['id'],
      source: map['source'] ?? 'workspace',
      package: map['package'],
    );
    usage.locations.addAll(
      (map['locations'] ?? []).map<KeyLocation>((x) => KeyLocation.fromMap(x)),
    );
    usage.handlers.addAll(
      (map['handlers'] ?? []).map<HandlerInfo>((x) => HandlerInfo.fromMap(x)),
    );
    usage.tags.addAll(List<String>.from(map['tags'] ?? []));
    usage.status = map['status'] ?? 'active';
    usage.notes = map['notes'];
    return usage;
  }
}

/// Key location in code
class KeyLocation {
  final String file;
  final int line;
  final int column;
  final String detector;
  final String context;

  KeyLocation({
    required this.file,
    required this.line,
    required this.column,
    required this.detector,
    required this.context,
  });

  Map<String, dynamic> toMap() {
    return {
      'file': file,
      'line': line,
      'column': column,
      'detector': detector,
      'context': context,
    };
  }

  factory KeyLocation.fromMap(Map<String, dynamic> map) {
    return KeyLocation(
      file: map['file'],
      line: map['line'],
      column: map['column'],
      detector: map['detector'],
      context: map['context'],
    );
  }
}

