  /// Build the header section
  String _buildHeader(ReportData data, QualityBreakdown quality) {
    final status = data.passed ? 'passed' : 'failed';
    final statusIcon = data.passed ? '✅' : '❌';
    final statusText = data.passed ? 'All Checks Passed' : 'Issues Found';

    return '''
<div class="glass-header">
    <div class="theme-toggle" onclick="toggleTheme()">
        <span id="theme-icon">🌙</span>
    </div>

    <h1 class="header-title">🔑 Flutter KeyCheck Report</h1>
    <p class="header-subtitle">${_escapeHtml(data.projectPath)}</p>
    <p class="text-muted mb-3">Generated on ${data.timestamp.toIso8601String()}</p>

    <div class="status-badge status-$status">
        <span>$statusIcon</span>
        <span>$statusText</span>
    </div>

    <div class="progress-container">
        <div class="progress-label">
            <span>Overall Quality Score</span>
            <span>${quality.overall.toStringAsFixed(1)}/100</span>
        </div>
        <div class="progress-bar">
            <div class="progress-fill" style="width: ${quality.overall}%"></div>
        </div>
    </div>
</div>
''';
  }

  /// Build the dashboard section
  String _buildDashboard(ReportData data, QualityBreakdown quality, KeyStatistics stats) {
    return '''
<div class="glass-card">
    <h2 class="mb-3">📊 Dashboard Overview</h2>

    <div class="dashboard-grid">
        <div class="metric-card">
            <div class="metric-value">${data.coverage.toStringAsFixed(1)}%</div>
            <div class="metric-label">Test Coverage</div>
            <div class="metric-change ${data.coverage >= 80 ? 'change-positive' : 'change-negative'}">
                ${data.coverage >= 80 ? '📈 Good' : '📉 Needs Improvement'}
            </div>
        </div>

        <div class="metric-card">
            <div class="metric-value">${data.expectedKeys.length}</div>
            <div class="metric-label">Expected Keys</div>
            <div class="metric-change change-positive">📋 Total Target</div>
        </div>

        <div class="metric-card">
            <div class="metric-value">${data.foundKeys.length}</div>
            <div class="metric-label">Found Keys</div>
            <div class="metric-change ${data.foundKeys.length >= data.expectedKeys.length ? 'change-positive' : 'change-negative'}">
                ${data.foundKeys.length >= data.expectedKeys.length ? '✅ Complete' : '⚠️ Partial'}
            </div>
        </div>

        <div class="metric-card">
            <div class="metric-value">${data.missingKeys.length}</div>
            <div class="metric-label">Missing Keys</div>
            <div class="metric-change ${data.missingKeys.isEmpty ? 'change-positive' : 'change-negative'}">
                ${data.missingKeys.isEmpty ? '🎯 Perfect' : '🔍 Action Needed'}
            </div>
        </div>

        <div class="metric-card">
            <div class="metric-value">${quality.overall.toStringAsFixed(0)}</div>
            <div class="metric-label">Quality Score</div>
            <div class="metric-change ${quality.overall >= 80 ? 'change-positive' : quality.overall >= 60 ? 'change-warning' : 'change-negative'}">
                ${_getQualityBadge(quality.overall)}
            </div>
        </div>

        <div class="metric-card">
            <div class="metric-value">${data.scanDuration?.inMilliseconds ?? 0}ms</div>
            <div class="metric-label">Scan Time</div>
            <div class="metric-change change-positive">⚡ Performance</div>
        </div>
    </div>
</div>
''';
  }

  /// Build quality gates section
  String _buildQualitySection(QualityBreakdown quality) {
    final gates = [
      ('Coverage', quality.coverage, 80.0, '🎯'),
      ('Organization', quality.organization, 70.0, '📁'),
      ('Consistency', quality.consistency, 75.0, '🔄'),
      ('Efficiency', quality.efficiency, 70.0, '⚡'),
      ('Maintainability', quality.maintainability, 65.0, '🔧'),
    ];

    final gateItems = gates.map((gate) {
      final name = gate.$1;
      final score = gate.$2;
      final threshold = gate.$3;
      final icon = gate.$4;
      final passed = score >= threshold;
      final statusIcon = passed ? '✅' : '❌';

      return '''
<div class="quality-gate">
    <div class="gate-header">
        <span class="gate-name">$icon $name</span>
        <span class="gate-status">$statusIcon</span>
    </div>
    <div class="gate-score ${passed ? 'text-success' : 'text-error'}">
        ${score.toStringAsFixed(1)}%
    </div>
    <div class="progress-bar">
        <div class="progress-fill" style="width: ${math.min(score, 100)}%"></div>
    </div>
    <div class="text-muted text-center" style="font-size: 0.8em; margin-top: 8px;">
        Threshold: ${threshold.toStringAsFixed(0)}%
    </div>
</div>
''';
    }).join('\n');

    return '''
<div class="glass-card">
    <h2 class="mb-3">🎯 Quality Gates</h2>
    <div class="quality-grid">
        $gateItems
    </div>
</div>
''';
  }

  /// Build issues section
  String _buildIssuesSection(ReportData data) {
    if (data.missingKeys.isEmpty && data.extraKeys.isEmpty) {
      return '''
<div class="glass-card">
    <h2 class="mb-3">✨ Issues Analysis</h2>
    <div class="text-center">
        <div style="font-size: 4em; margin-bottom: 16px;">🎉</div>
        <h3 class="text-success">No Issues Found!</h3>
        <p class="text-muted">All keys are properly organized and accounted for.</p>
    </div>
</div>
''';
    }

    final issues = StringBuffer();

    // Missing keys
    if (data.missingKeys.isNotEmpty) {
      issues.writeln('<h3 class="text-error mb-2">🔴 Critical: Missing Keys (${data.missingKeys.length})</h3>');
      for (final key in data.missingKeys.take(10)) {
        issues.writeln('''
<div class="issue-item issue-critical">
    <div class="issue-header">
        <span>❌</span>
        <span>${_escapeHtml(key)}</span>
    </div>
    <div class="issue-description">This key is expected but not found in the codebase</div>
</div>
''');
      }
      if (data.missingKeys.length > 10) {
        issues.writeln('<p class="text-muted">... and ${data.missingKeys.length - 10} more missing keys</p>');
      }
    }

    // Extra keys
    if (data.extraKeys.isNotEmpty) {
      issues.writeln('<h3 class="text-warning mb-2">🟡 Warning: Extra Keys (${data.extraKeys.length})</h3>');
      for (final key in data.extraKeys.take(10)) {
        issues.writeln('''
<div class="issue-item issue-warning">
    <div class="issue-header">
        <span>⚠️</span>
        <span>${_escapeHtml(key)}</span>
    </div>
    <div class="issue-description">This key was found but is not in the expected keys list</div>
</div>
''');
      }
      if (data.extraKeys.length > 10) {
        issues.writeln('<p class="text-muted">... and ${data.extraKeys.length - 10} more extra keys</p>');
      }
    }

    return '''
<div class="glass-card">
    <h2 class="mb-3">🚨 Issues Analysis</h2>
    $issues
</div>
''';
  }

  /// Build statistics section
  String _buildStatisticsSection(KeyStatistics stats) {
    return '''
<div class="glass-card">
    <h2 class="mb-3">📈 Detailed Statistics</h2>

    <div class="mb-4">
        <h3 class="mb-2">Coverage Analysis</h3>
        <table class="data-table">
            <thead>
                <tr>
                    <th>Metric</th>
                    <th>Value</th>
                    <th>Status</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td>Coverage Percentage</td>
                    <td>${stats.coverage['percentage']?.toStringAsFixed(1) ?? 0}%</td>
                    <td class="${_getCoverageStatusClass(stats.coverage['percentage'] ?? 0)}">${_getCoverageStatusText(stats.coverage['percentage'] ?? 0)}</td>
                </tr>
                <tr>
                    <td>Files Scanned</td>
                    <td>${stats.coverage['filesScanned'] ?? 0}</td>
                    <td class="text-info">📄 Analyzed</td>
                </tr>
                <tr>
                    <td>Files with Keys</td>
                    <td>${stats.coverage['filesWithKeys'] ?? 0}</td>
                    <td class="text-info">🔑 Active</td>
                </tr>
            </tbody>
        </table>
    </div>

    ${includeCharts ? '''
    <div class="mb-4">
        <h3 class="mb-2">Key Distribution</h3>
        <div class="chart-container">
            <canvas id="distributionChart" class="chart-canvas"></canvas>
        </div>
    </div>
    ''' : ''}

    <div class="mb-4">
        <h3 class="mb-2">Performance Metrics</h3>
        <table class="data-table">
            <thead>
                <tr>
                    <th>Metric</th>
                    <th>Value</th>
                    <th>Rating</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td>Scan Time</td>
                    <td>${stats.performance['scanTimeMs'] ?? 0}ms</td>
                    <td class="${_getPerformanceStatusClass(stats.performance['scanTimeMs'] ?? 0)}">${_getPerformanceStatusText(stats.performance['scanTimeMs'] ?? 0)}</td>
                </tr>
                <tr>
                    <td>Keys per Second</td>
                    <td>${stats.performance['keysPerSecond']?.toStringAsFixed(1) ?? 0}</td>
                    <td class="text-info">⚡ Speed</td>
                </tr>
                <tr>
                    <td>Performance Score</td>
                    <td>${stats.performance['score']?.toStringAsFixed(1) ?? 0}/100</td>
                    <td class="${_getQualityStatusClass(stats.performance['score'] ?? 0)}">${_getQualityStatusText(stats.performance['score'] ?? 0)}</td>
                </tr>
            </tbody>
        </table>
    </div>
</div>
''';
  }

  /// Build file coverage section
  String _buildFileCoverageSection(List<FileCoverageResult> fileCoverage) {
    if (fileCoverage.isEmpty) {
      return '';
    }

    final rows = fileCoverage.take(10).map((file) {
      final coverage = file.coverageScore.toStringAsFixed(1);
      final statusClass = _getCoverageStatusClass(file.coverageScore);
      final statusText = _getCoverageStatusText(file.coverageScore);
      final fileType = file.isTestFile ? '🧪 Test' : (file.hasKeyConstants ? '🔑 Keys' : '📄 Source');

      return '''
<tr>
    <td>${_escapeHtml(file.filePath)}</td>
    <td>${file.keyCount}</td>
    <td>$coverage%</td>
    <td class="$statusClass">$statusText</td>
    <td>$fileType</td>
</tr>
''';
    }).join('\n');

    return '''
<div class="glass-card">
    <h2 class="mb-3">📁 File Coverage Analysis</h2>

    <table class="data-table">
        <thead>
            <tr>
                <th>File Path</th>
                <th>Key Count</th>
                <th>Coverage</th>
                <th>Status</th>
                <th>Type</th>
            </tr>
        </thead>
        <tbody>
            $rows
        </tbody>
    </table>

    ${fileCoverage.length > 10 ? '<p class="text-muted text-center">... and ${fileCoverage.length - 10} more files</p>' : ''}
</div>
''';
  }

  /// Build recommendations section
  String _buildRecommendationsSection(QualityBreakdown quality) {
    if (quality.recommendations.isEmpty) {
      return '';
    }

    final recommendations = quality.recommendations.map((rec) => '''
<div class="recommendation-item">
    <div class="d-flex align-items-center gap-2">
        <span>💡</span>
        <span>$rec</span>
    </div>
</div>
''').join('\n');

    return '''
<div class="glass-card">
    <h2 class="mb-3">💡 Recommendations</h2>
    $recommendations
</div>
''';
  }

  /// Build footer section
  String _buildFooter(ReportData data) {
    return '''
<div class="footer">
    <p class="text-muted">
        Report generated by <strong>Flutter KeyCheck v3.x</strong><br>
        ${data.timestamp.toIso8601String()}
    </p>
</div>
''';
  }

  /// Build JavaScript for interactivity
  String _buildJavaScript() {
    return '''
// Theme toggle functionality
function toggleTheme() {
    const body = document.body;
    const icon = document.getElementById('theme-icon');
    const currentTheme = body.getAttribute('data-theme');

    if (currentTheme === 'dark') {
        body.className = 'light-theme';
        body.setAttribute('data-theme', 'light');
        icon.textContent = '🌙';
    } else {
        body.className = 'dark-theme';
        body.setAttribute('data-theme', 'dark');
        icon.textContent = '☀️';
    }
}

// Chart rendering functionality
function initCharts() {
    const distributionCanvas = document.getElementById('distributionChart');
    if (!distributionCanvas) return;

    const ctx = distributionCanvas.getContext('2d');
    const data = window.reportData;

    if (!data || !data.stats || !data.stats.distribution) return;

    drawDistributionChart(ctx, data.stats.distribution);
}

function drawDistributionChart(ctx, distribution) {
    const canvas = ctx.canvas;
    const width = canvas.width = canvas.offsetWidth;
    const height = canvas.height = canvas.offsetHeight;

    // Clear canvas
    ctx.clearRect(0, 0, width, height);

    // Chart data
    const categories = Object.keys(distribution.byCategory || {});
    const values = Object.values(distribution.byCategory || {});

    if (categories.length === 0) {
        ctx.fillStyle = '#666';
        ctx.font = '16px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('No data available', width / 2, height / 2);
        return;
    }

    // Colors for chart segments
    const colors = [
        '#667eea', '#764ba2', '#f093fb', '#f5576c',
        '#4facfe', '#00f2fe', '#43e97b', '#38f9d7',
        '#ffecd2', '#fcb69f', '#a8edea', '#fed6e3'
    ];

    // Calculate total
    const total = values.reduce((sum, val) => sum + val, 0);

    // Draw pie chart
    const centerX = width / 2;
    const centerY = height / 2;
    const radius = Math.min(width, height) / 3;

    let currentAngle = -Math.PI / 2;

    categories.forEach((category, index) => {
        const value = values[index];
        const angle = (value / total) * 2 * Math.PI;

        // Draw slice
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + angle);
        ctx.closePath();

        ctx.fillStyle = colors[index % colors.length];
        ctx.fill();

        // Draw label
        const labelAngle = currentAngle + angle / 2;
        const labelX = centerX + Math.cos(labelAngle) * (radius + 30);
        const labelY = centerY + Math.sin(labelAngle) * (radius + 30);

        ctx.fillStyle = '#333';
        ctx.font = '12px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(category, labelX, labelY);
        ctx.fillText(`\${value}`, labelX, labelY + 15);

        currentAngle += angle;
    });
}

// Initialize animations
function initAnimations() {
    // Animate progress bars
    const progressBars = document.querySelectorAll('.progress-fill');
    progressBars.forEach(bar => {
        const width = bar.style.width;
        bar.style.width = '0%';
        setTimeout(() => {
            bar.style.width = width;
        }, 500);
    });

    // Animate metric cards
    const metricCards = document.querySelectorAll('.metric-card');
    metricCards.forEach((card, index) => {
        card.style.opacity = '0';
        card.style.transform = 'translateY(20px)';
        setTimeout(() => {
            card.style.transition = 'all 0.6s ease';
            card.style.opacity = '1';
            card.style.transform = 'translateY(0)';
        }, index * 100);
    });
}

// Export functionality
function exportReport(format) {
    if (format === 'json') {
        const data = JSON.stringify(window.reportData, null, 2);
        downloadFile(data, 'flutter-keycheck-report.json', 'application/json');
    } else if (format === 'csv') {
        // Convert to CSV format
        const csv = convertToCSV(window.reportData);
        downloadFile(csv, 'flutter-keycheck-report.csv', 'text/csv');
    }
}

function downloadFile(content, filename, contentType) {
    const blob = new Blob([content], { type: contentType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
}

function convertToCSV(data) {
    // Simple CSV conversion for basic metrics
    let csv = 'Metric,Value\\n';
    csv += `Coverage,\${data.coverage}%\\n`;
    csv += `Expected Keys,\${data.expectedKeys}\\n`;
    csv += `Found Keys,\${data.foundKeys}\\n`;
    csv += `Missing Keys,\${data.missingKeys}\\n`;
    csv += `Extra Keys,\${data.extraKeys}\\n`;
    return csv;
}

// Initialize everything when DOM is loaded
document.addEventListener('DOMContentLoaded', function() {
    initAnimations();
    setTimeout(initCharts, 100);
});

// Handle window resize for responsive charts
window.addEventListener('resize', function() {
    setTimeout(initCharts, 100);
});
''';
  }

  /// Prepare structured data for JavaScript
  Map<String, dynamic> _prepareReportData(ReportData data, QualityBreakdown quality, 
                                          KeyStatistics stats, List<FileCoverageResult> fileCoverage) {
    return {
      'timestamp': data.timestamp.toIso8601String(),
      'projectPath': data.projectPath,
      'coverage': data.coverage,
      'expectedKeys': data.expectedKeys.length,
      'foundKeys': data.foundKeys.length,
      'missingKeys': data.missingKeys.length,
      'extraKeys': data.extraKeys.length,
      'passed': data.passed,
      'quality': quality.toJson(),
      'stats': stats.toJson(),
      'fileCoverage': fileCoverage.map((f) => f.toJson()).toList(),
      'scanDuration': data.scanDuration?.inMilliseconds,
    };
  }

  /// Helper methods for status classes and text
  String _getCoverageStatusClass(double coverage) {
    if (coverage >= 90) return 'text-success';
    if (coverage >= 80) return 'text-info';
    if (coverage >= 70) return 'text-warning';
    return 'text-error';
  }

  String _getCoverageStatusText(double coverage) {
    if (coverage >= 90) return '🎯 Excellent';
    if (coverage >= 80) return '👍 Good';
    if (coverage >= 70) return '👌 OK';
    return '🔧 Poor';
  }

  String _getPerformanceStatusClass(int timeMs) {
    if (timeMs < 100) return 'text-success';
    if (timeMs < 500) return 'text-info';
    if (timeMs < 2000) return 'text-warning';
    return 'text-error';
  }

  String _getPerformanceStatusText(int timeMs) {
    if (timeMs < 100) return '⚡ Fast';
    if (timeMs < 500) return '👍 Good';
    if (timeMs < 2000) return '👌 OK';
    return '🐌 Slow';
  }

  String _getQualityStatusClass(double score) {
    if (score >= 80) return 'text-success';
    if (score >= 70) return 'text-info';
    if (score >= 60) return 'text-warning';
    return 'text-error';
  }

  String _getQualityStatusText(double score) {
    if (score >= 80) return '🏆 Excellent';
    if (score >= 70) return '⭐ Good';
    if (score >= 60) return '👍 OK';
    return '🔧 Poor';
  }

  String _getQualityBadge(double score) {
    if (score >= 90) return '🏆 Excellent';
    if (score >= 80) return '⭐ Very Good';
    if (score >= 70) return '👍 Good';
    if (score >= 60) return '👌 Fair';
    return '🔧 Needs Work';
  }

  /// Escape HTML characters
  String _escapeHtml(String text) {
    return text
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#x27;');
  }

  @override
  String get fileExtension => 'html';

  @override
  String get reportType => 'Premium HTML';
}

import 'dart:convert';
import 'dart:io';

import 'package:flutter_keycheck/src/models/scan_result.dart';
import 'package:flutter_keycheck/src/models/validation_result.dart';

/// Base reporter class for v3
abstract class ReporterV3 {
  /// Create reporter based on format
  static ReporterV3 create(String format) {
    switch (format) {
      case 'json':
        return JsonReporter();
      case 'junit':
        return JUnitReporter();
      case 'md':
      case 'markdown':
        return MarkdownReporter();
      case 'html':
        return HtmlReporter();
      case 'text':
        return TextReporter();
      case 'ci':
      case 'gitlab':
        return CIReporter();
      default:
        return TextReporter();
    }
  }

  /// Generate scan report
  Future<void> generateScanReport(
    ScanResult result,
    File outputFile, {
    bool includeMetrics = true,
    bool includeLocations = false,
  });

  /// Generate validation report
  Future<void> generateValidationReport(
    ValidationResult result,
    File outputFile, {
    bool includeMetrics = true,
  });
}

/// JSON reporter
class JsonReporter extends ReporterV3 {
  @override
  Future<void> generateScanReport(
    ScanResult result,
    File outputFile, {
    bool includeMetrics = true,
    bool includeLocations = false,
  }) async {
    final Map<String, dynamic> report = {
      'schema_version': '1.0',
      'timestamp': DateTime.now().toIso8601String(),
      'scan_type': result.metrics.incrementalScan ? 'incremental' : 'full',
    };

    if (result.metrics.incrementalScan) {
      report['incremental_base'] = result.metrics.incrementalBase ?? '';
    }

    // Add summary
    report['summary'] = {
      'total_files': result.metrics.totalFiles,
      'scanned_files': result.metrics.scannedFiles,
      'total_keys': result.keyUsages.length,
      'file_coverage': result.metrics.fileCoverage,
      'widget_coverage': result.metrics.widgetCoverage,
      'handler_coverage': result.metrics.handlerCoverage,
    };

    // Add metrics if requested
    if (includeMetrics) {
      report['metrics'] = result.metrics.toMap();
    }

    // Add keys
    final keys = <Map<String, dynamic>>[];
    for (final entry in result.keyUsages.entries) {
      final keyData = <String, dynamic>{
        'id': entry.key,
        'tags': entry.value.tags.toList(),
        'status': entry.value.status,
        'location_count': entry.value.locations.length,
      };

      if (includeLocations) {
        keyData['locations'] = entry.value.locations
            .map((loc) => {
                  'file': loc.file,
                  'line': loc.line,
                  'column': loc.column,
                  'detector': loc.detector,
                  'context': loc.context,
                })
            .toList();
      }

      keys.add(keyData);
    }
    report['keys'] = keys;

    // Add blind spots
    if (result.blindSpots.isNotEmpty) {
      report['blind_spots'] =
          result.blindSpots.map((spot) => spot.toMap()).toList();
    }

    // Add errors if any
    if (result.metrics.errors.isNotEmpty) {
      report['errors'] =
          result.metrics.errors.map((err) => err.toMap()).toList();
    }

    // Write to file
    await outputFile.writeAsString(
      const JsonEncoder.withIndent('  ').convert(report),
    );
  }

  @override
  Future<void> generateValidationReport(
    ValidationResult result,
    File outputFile, {
    bool includeMetrics = true,
  }) async {
    final report = result.toMap();

    // Write to file
    await outputFile.writeAsString(
      const JsonEncoder.withIndent('  ').convert(report),
    );
  }
}

/// JUnit XML reporter
class JUnitReporter extends ReporterV3 {
  @override
  Future<void> generateScanReport(
    ScanResult result,
    File outputFile, {
    bool includeMetrics = true,
    bool includeLocations = false,
  }) async {
    final buffer = StringBuffer();

    buffer.writeln('<?xml version="1.0" encoding="UTF-8"?>');
    buffer.writeln(
        '<testsuites name="Flutter KeyCheck Scan" tests="${result.keyUsages.length}">');

    // Group by package
    final keysByPackage = <String, List<MapEntry<String, KeyUsage>>>{};
    for (final entry in result.keyUsages.entries) {
      final package = _getPackageFromPath(entry.value.locations.first.file);
      keysByPackage.putIfAbsent(package, () => []).add(entry);
    }

    for (final packageEntry in keysByPackage.entries) {
      buffer.writeln(
          '  <testsuite name="${packageEntry.key}" tests="${packageEntry.value.length}">');

      for (final keyEntry in packageEntry.value) {
        buffer.writeln(
            '    <testcase name="Key: ${keyEntry.key}" classname="Found">');
        if (includeLocations) {
          buffer.writeln('      <system-out>');
          for (final loc in keyEntry.value.locations) {
            buffer.writeln('        ${loc.file}:${loc.line}:${loc.column}');
          }
          buffer.writeln('      </system-out>');
        }
        buffer.writeln('    </testcase>');
      }

      buffer.writeln('  </testsuite>');
    }

    buffer.writeln('</testsuites>');

    await outputFile.writeAsString(buffer.toString());
  }

  @override
  Future<void> generateValidationReport(
    ValidationResult result,
    File outputFile, {
    bool includeMetrics = true,
  }) async {
    final buffer = StringBuffer();

    buffer.writeln('<?xml version="1.0" encoding="UTF-8"?>');
    buffer.writeln('<testsuites name="Flutter KeyCheck Validation" '
        'tests="${result.summary.totalKeys}" '
        'failures="${result.violations.length}">');

    // Group violations by package
    final violationsByPackage = <String, List<Violation>>{};
    for (final violation in result.violations) {
      if (violation.key != null) {
        final package = violation.key!.package;
        violationsByPackage.putIfAbsent(package, () => []).add(violation);
      }
    }

    // Add test suites
    for (final entry in violationsByPackage.entries) {
      buffer.writeln('  <testsuite name="${entry.key}" '
          'tests="${entry.value.length}" '
          'failures="${entry.value.length}">');

      for (final violation in entry.value) {
        buffer.writeln(
            '    <testcase name="Key: ${violation.key?.id ?? 'policy'}" '
            'classname="${violation.type}">');
        buffer.writeln(
            '      <failure message="${_escapeXml(violation.message)}">');
        buffer.writeln('        ${_escapeXml(violation.message)}');
        if (violation.key != null) {
          buffer.writeln('        Key: ${violation.key!.id}');
          buffer.writeln('        Tags: ${violation.key!.tags.join(', ')}');
          if (violation.key!.lastSeen != null) {
            buffer.writeln('        Last seen: ${violation.key!.lastSeen}');
          }
        }
        buffer.writeln(
            '        Remediation: ${_escapeXml(violation.remediation)}');
        buffer.writeln('      </failure>');
        buffer.writeln('    </testcase>');
      }

      buffer.writeln('  </testsuite>');
    }

    // Add summary as properties
    buffer.writeln('  <properties>');
    buffer.writeln(
        '    <property name="total_keys" value="${result.summary.totalKeys}"/>');
    buffer.writeln(
        '    <property name="lost_keys" value="${result.summary.lostKeys}"/>');
    buffer.writeln(
        '    <property name="added_keys" value="${result.summary.addedKeys}"/>');
    buffer.writeln(
        '    <property name="renamed_keys" value="${result.summary.renamedKeys}"/>');
    buffer.writeln(
        '    <property name="drift_percentage" value="${result.summary.driftPercentage.toStringAsFixed(1)}"/>');
    buffer.writeln('  </properties>');

    buffer.writeln('</testsuites>');

    await outputFile.writeAsString(buffer.toString());
  }

  String _escapeXml(String text) {
    return text
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&apos;');
  }

  String _getPackageFromPath(String filePath) {
    if (filePath.contains('packages/')) {
      final parts = filePath.split('/');
      final packagesIndex = parts.indexOf('packages');
      if (packagesIndex >= 0 && packagesIndex < parts.length - 1) {
        return parts[packagesIndex + 1];
      }
    }
    return 'app_main';
  }
}

/// Markdown reporter
class MarkdownReporter extends ReporterV3 {
  @override
  Future<void> generateScanReport(
    ScanResult result,
    File outputFile, {
    bool includeMetrics = true,
    bool includeLocations = false,
  }) async {
    final buffer = StringBuffer();

    buffer.writeln('# 🔍 Key Scan Report');
    buffer.writeln();
    buffer.writeln('Generated: ${DateTime.now().toIso8601String()}');
    buffer.writeln();

    // Summary section
    buffer.writeln('## Summary');
    buffer.writeln();
    buffer.writeln('- **Total Files**: ${result.metrics.totalFiles}');
    buffer.writeln('- **Scanned Files**: ${result.metrics.scannedFiles}');
    buffer.writeln('- **Total Keys**: ${result.keyUsages.length}');
    buffer.writeln(
        '- **File Coverage**: ${result.metrics.fileCoverage.toStringAsFixed(1)}%');
    buffer.writeln(
        '- **Widget Coverage**: ${result.metrics.widgetCoverage.toStringAsFixed(1)}%');
    buffer.writeln(
        '- **Handler Coverage**: ${result.metrics.handlerCoverage.toStringAsFixed(1)}%');
    buffer.writeln();

    // Keys by status
    final keysByStatus = <String, List<String>>{};
    for (final entry in result.keyUsages.entries) {
      final status = entry.value.status;
      keysByStatus.putIfAbsent(status, () => []).add(entry.key);
    }

    buffer.writeln('## Keys by Status');
    buffer.writeln();
    for (final entry in keysByStatus.entries) {
      buffer.writeln('### ${_capitalize(entry.key)} (${entry.value.length})');
      buffer.writeln();
      for (final key in entry.value..sort()) {
        buffer.write('- `$key`');
        final usage = result.keyUsages[key]!;
        if (usage.tags.isNotEmpty) {
          buffer.write(' ${usage.tags.map((t) => '`$t`').join(' ')}');
        }
        buffer.writeln();
      }
      buffer.writeln();
    }

    // Blind spots
    if (result.blindSpots.isNotEmpty) {
      buffer.writeln('## ⚠️ Blind Spots');
      buffer.writeln();
      for (final spot in result.blindSpots) {
        final icon = spot.severity == 'error'
            ? '🔴'
            : spot.severity == 'warning'
                ? '🟡'
                : 'ℹ️';
        buffer.writeln('- $icon ${spot.message}');
      }
      buffer.writeln();
    }

    // Metrics
    if (includeMetrics) {
      buffer.writeln('## 📊 Metrics');
      buffer.writeln();
      buffer.writeln('### Detector Effectiveness');
      buffer.writeln();
      buffer.writeln('| Detector | Hits |');
      buffer.writeln('|----------|------|');
      for (final entry in result.metrics.detectorHits.entries) {
        buffer.writeln('| ${entry.key} | ${entry.value} |');
      }
      buffer.writeln();
    }

    await outputFile.writeAsString(buffer.toString());
  }

  @override
  Future<void> generateValidationReport(
    ValidationResult result,
    File outputFile, {
    bool includeMetrics = true,
  }) async {
    final buffer = StringBuffer();

    buffer.writeln('# 🔑 Key Validation Report');
    buffer.writeln();
    buffer.writeln('Generated: ${result.timestamp.toIso8601String()}');
    buffer.writeln();

    // Summary
    buffer.writeln('## Summary');
    buffer.writeln();
    buffer.writeln('- **Total Keys**: ${result.summary.totalKeys}');
    buffer.writeln('- **Lost**: ${result.summary.lostKeys} 🔥');
    buffer.writeln('- **Added**: ${result.summary.addedKeys} ➕');
    buffer.writeln('- **Renamed**: ${result.summary.renamedKeys} ♻️');
    buffer.writeln(
        '- **Drift**: ${result.summary.driftPercentage.toStringAsFixed(1)}% 📈');
    buffer.writeln();

    // Status
    if (result.hasViolations) {
      buffer.writeln('## ❌ Validation Failed');
    } else {
      buffer.writeln('## ✅ Validation Passed');
    }
    buffer.writeln();

    // Violations
    if (result.violations.isNotEmpty) {
      buffer.writeln('## Critical Issues');
      buffer.writeln();
      buffer.writeln('| Type | Key | Package | Tags | Action |');
      buffer.writeln('|------|-----|---------|------|--------|');

      for (final violation in result.violations) {
        final icon = violation.type == 'lost'
            ? '🔥'
            : violation.type == 'renamed'
                ? '♻️'
                : violation.type == 'extra'
                    ? '➕'
                    : '⚠️';

        buffer.write('| $icon ${violation.type} ');
        buffer.write('| ${violation.key?.id ?? 'N/A'} ');
        buffer.write('| ${violation.key?.package ?? 'N/A'} ');
        buffer.write('| ${violation.key?.tags.join(', ') ?? ''} ');
        buffer.writeln('| ${violation.remediation} |');
      }
      buffer.writeln();
    }

    // Warnings
    if (result.warnings.isNotEmpty) {
      buffer.writeln('## Warnings');
      buffer.writeln();
      for (final warning in result.warnings) {
        buffer.writeln('- ⚠️ $warning');
      }
      buffer.writeln();
    }

    // Scanned packages
    buffer.writeln('## Scanned Packages');
    buffer.writeln();
    for (final package in result.summary.scannedPackages) {
      buffer.writeln('- `$package`');
    }

    await outputFile.writeAsString(buffer.toString());
  }

  String _capitalize(String text) {
    if (text.isEmpty) return text;
    return text[0].toUpperCase() + text.substring(1);
  }
}

/// HTML reporter for rich web reports
class HtmlReporter extends ReporterV3 {
  @override
  Future<void> generateScanReport(
    ScanResult result,
    File outputFile, {
    bool includeMetrics = true,
    bool includeLocations = false,
  }) async {
    final buffer = StringBuffer();

    // HTML header
    buffer.writeln('<!DOCTYPE html>');
    buffer.writeln('<html lang="en">');
    buffer.writeln('<head>');
    buffer.writeln('  <meta charset="UTF-8">');
    buffer.writeln(
        '  <meta name="viewport" content="width=device-width, initial-scale=1.0">');
    buffer.writeln('  <title>Flutter KeyCheck - Scan Report</title>');
    buffer.writeln('');
    buffer.writeln('');
    buffer.writeln(
        '  <script src="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/js/all.min.js"></script>');
    buffer.writeln(
        '  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>');
    buffer.writeln(
        '  <link rel="preconnect" href="https://fonts.googleapis.com">');
    buffer.writeln(
        '  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>');
    buffer.writeln(
        '  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">');
    buffer.writeln(_getInlineStyles());
    buffer.writeln('</head>');
    buffer.writeln('<body class="dark">');

    // Sidebar
    _addSidebar(buffer);

    // Header
    _addHeader(buffer);

    // Main Content with Sections
    buffer.writeln('  <div class="main-content">');

    // Dashboard Section (Default)
    buffer.writeln(
        '    <div id="dashboard-section" class="content-section active">');
    _addDashboardHeader(buffer);
    _addMetricsCards(buffer, result);
    _addKeysTable(buffer, result);
    buffer.writeln('    </div>');

    // Analysis Section
    buffer.writeln(
        '    <div id="analysis-section" class="content-section" style="display: none;">');
    _addAnalysisSection(buffer, result);
    buffer.writeln('    </div>');

    // Stats Section
    buffer.writeln(
        '    <div id="stats-section" class="content-section" style="display: none;">');
    _addStatsSection(buffer, result);
    buffer.writeln('    </div>');

    // Export Section
    buffer.writeln(
        '    <div id="export-section" class="content-section" style="display: none;">');
    _addExportSectionPage(buffer);
    buffer.writeln('    </div>');

    buffer.writeln('  </div>');

    // Location Modal
    _addLocationModal(buffer);

    // Keyboard shortcuts panel
    _addKeyboardShortcuts(buffer);

    // JavaScript
    _addJavaScriptData(buffer, result);

    buffer.writeln('</body>');
    buffer.writeln('</html>');

    await outputFile.writeAsString(buffer.toString());
  }

  @override
  Future<void> generateValidationReport(
    ValidationResult result,
    File outputFile, {
    bool includeMetrics = true,
  }) async {
    final buffer = StringBuffer();

    // HTML structure with premium dark theme
    buffer.writeln('<!DOCTYPE html>');
    buffer.writeln('<html lang="en">');
    buffer.writeln('<head>');
    buffer.writeln('  <meta charset="UTF-8">');
    buffer.writeln('  <title>Flutter KeyCheck Validation Report</title>');
    buffer.writeln(_getInlineStyles());
    buffer.writeln('</head>');
    buffer.writeln('<body>');

    final statusClass = result.hasViolations ? 'failed' : 'passed';
    buffer.writeln('<div class="container">');
    buffer.writeln(
        '  <h1 class="$statusClass">Validation ${result.hasViolations ? 'Failed' : 'Passed'}</h1>');

    // Summary section with glassmorphism cards
    buffer.writeln('  <div class="summary">');
    buffer.writeln('    <div class="stat">');
    buffer.writeln('      <span class="label">Total Keys:</span>');
    buffer.writeln(
        '      <span class="value">${result.summary.totalKeys}</span>');
    buffer.writeln('    </div>');
    buffer.writeln('    <div class="stat">');
    buffer.writeln('      <span class="label">Lost Keys:</span>');
    buffer
        .writeln('      <span class="value">${result.summary.lostKeys}</span>');
    buffer.writeln('    </div>');
    buffer.writeln('    <div class="stat">');
    buffer.writeln('      <span class="label">Added Keys:</span>');
    buffer.writeln(
        '      <span class="value">${result.summary.addedKeys}</span>');
    buffer.writeln('    </div>');
    buffer.writeln('    <div class="stat">');
    buffer.writeln('      <span class="label">Drift:</span>');
    buffer.writeln(
        '      <span class="value">${result.summary.driftPercentage.toStringAsFixed(1)}%</span>');
    buffer.writeln('    </div>');
    buffer.writeln('  </div>');

    // Violations section with premium styling
    if (result.hasViolations) {
      buffer.writeln('  <div class="violations">');
      buffer.writeln('    <h2>🚨 Critical Issues Found</h2>');

      if (result.violations.isNotEmpty) {
        buffer.writeln('    <table>');
        buffer.writeln('      <thead>');
        buffer.writeln('        <tr>');
        buffer.writeln('          <th>Type</th>');
        buffer.writeln('          <th>Key ID</th>');
        buffer.writeln('          <th>Package</th>');
        buffer.writeln('          <th>Tags</th>');
        buffer.writeln('          <th>Action Required</th>');
        buffer.writeln('        </tr>');
        buffer.writeln('      </thead>');
        buffer.writeln('      <tbody>');

        for (final violation in result.violations) {
          final icon = violation.type == 'lost'
              ? '🔥'
              : violation.type == 'renamed'
                  ? '♻️'
                  : violation.type == 'extra'
                      ? '➕'
                      : '⚠️';

          buffer.writeln('        <tr>');
          buffer.writeln('          <td>$icon ${violation.type}</td>');
          buffer.writeln(
              '          <td><code>${violation.key?.id ?? 'N/A'}</code></td>');
          buffer
              .writeln('          <td>${violation.key?.package ?? 'N/A'}</td>');
          buffer.writeln(
              '          <td>${violation.key?.tags.join(', ') ?? ''}</td>');
          buffer.writeln('          <td>${violation.remediation}</td>');
          buffer.writeln('        </tr>');
        }

        buffer.writeln('      </tbody>');
        buffer.writeln('    </table>');
      }

      // Legacy lost keys display for backward compatibility
      if (result.lostKeys.isNotEmpty) {
        buffer.writeln('    <h2>🔥 Lost Keys (${result.lostKeys.length})</h2>');
        buffer.writeln('    <ul>');
        for (final key in result.lostKeys) {
          buffer.writeln(
              '      <li><code>${key.id}</code> - Package: ${key.package}</li>');
        }
        buffer.writeln('    </ul>');
      }

      buffer.writeln('  </div>');
    } else {
      // Success message with green glassmorphism styling
      buffer.writeln(
          '  <div class="stat" style="background: rgba(52, 211, 153, 0.1); border-color: rgba(52, 211, 153, 0.2); margin: 2rem 0;">');
      buffer.writeln('    <span class="label">✅ Validation Status</span>');
      buffer.writeln(
          '    <span class="value" style="color: #34d399;">All Good!</span>');
      buffer.writeln('  </div>');
    }

    // Warnings section
    if (result.warnings.isNotEmpty) {
      buffer.writeln('  <h2>⚠️ Warnings</h2>');
      buffer.writeln('  <ul>');
      for (final warning in result.warnings) {
        buffer.writeln('    <li>$warning</li>');
      }
      buffer.writeln('  </ul>');
    }

    // Scanned packages section
    if (result.summary.scannedPackages.isNotEmpty) {
      buffer.writeln('  <h2>📦 Scanned Packages</h2>');
      buffer.writeln('  <table>');
      buffer.writeln('    <thead>');
      buffer.writeln('      <tr>');
      buffer.writeln('        <th>Package</th>');
      buffer.writeln('        <th>Status</th>');
      buffer.writeln('      </tr>');
      buffer.writeln('    </thead>');
      buffer.writeln('    <tbody>');
      for (final package in result.summary.scannedPackages) {
        buffer.writeln('      <tr>');
        buffer.writeln('        <td><code>$package</code></td>');
        buffer.writeln('        <td>✅ Scanned</td>');
        buffer.writeln('      </tr>');
      }
      buffer.writeln('    </tbody>');
      buffer.writeln('  </table>');
    }

    buffer.writeln('</div>');
    buffer.writeln('</body>');
    buffer.writeln('</html>');

    await outputFile.writeAsString(buffer.toString());
  }

