        color: #E5E7EB;
      }

      .legend-count {
        font-size: 0.875rem;
        font-weight: 600;
        color: white;
        min-width: 20px;
        text-align: right;
      }

      /* Quality Score Styles */
      .quality-metrics {
        display: flex;
