          from 0deg,
          #3B82F6 0deg,
          #3B82F6 calc(var(--score) * 3.6deg),
          rgba(255, 255, 255, 0.1) calc(var(--score) * 3.6deg),
          rgba(255, 255, 255, 0.1) 360deg
        );
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        position: relative;
      }

      .score-circle::before {
        content: '';
        position: absolute;
        width: 90px;
        height: 90px;
        border-radius: 50%;
        background: #1F2937;
      }

      .score-text {
        font-size: 1.5rem;
        font-weight: 700;
        color: white;
        z-index: 1;
      }

      .score-label {
        font-size: 0.75rem;
        color: #9CA3AF;
        z-index: 1;
      }

      .quality-breakdown {
        flex: 1;
        display: flex;
        flex-direction: column;
        gap: 12px;
      }

      .quality-item {
        display: flex;
        align-items: center;
        gap: 12px;
      }

      .quality-label {
        width: 90px;
        font-size: 0.875rem;
        color: #9CA3AF;
        flex-shrink: 0;
      }

      .quality-bar {
        flex: 1;
        height: 8px;
        background: rgba(255, 255, 255, 0.1);
        border-radius: 4px;
        overflow: hidden;
      }

      .quality-fill {
        height: 100%;
        background: linear-gradient(90deg, #10B981, #3B82F6);
        border-radius: 4px;
        transition: width 1s ease-in-out;
      }

      .quality-value {
        width: 40px;
        text-align: right;
        font-size: 0.875rem;
        font-weight: 600;
        color: white;
        flex-shrink: 0;
      }

      /* Enhanced Insights Styles */
      .insight-content {
        margin-left: 28px;
      }

      .insight-content h4 {
        margin: 0 0 8px 0;
        font-size: 1rem;
        font-weight: 600;
        color: white;
      }

      .insight-content p {
        margin: 0 0 12px 0;
        font-size: 0.875rem;
        color: #D1D5DB;
        line-height: 1.4;
      }

      .action-items {
        display: flex;
        flex-direction: column;
        gap: 4px;
      }

      .action-item {
        font-size: 0.8rem;
        color: #9CA3AF;
        line-height: 1.3;
      }

      .detail-label, .metric-label {
        color: #94a3b8;
        font-size: 14px;
      }

      .detail-value, .metric-value {
        color: #e2e8f0;
        font-weight: 600;
        font-size: 14px;
      }

      .status-chart {
        display: flex;
        flex-direction: column;
        gap: 16px;
      }

      .status-item {
        display: flex;
        align-items: center;
        gap: 12px;
      }

      .status-indicator {
        width: 16px;
        height: 16px;
        border-radius: 50%;
      }

      .status-indicator.active {
        background: #10b981;
      }

      .status-indicator.inactive {
        background: #64748b;
      }

      .status-info {
        flex: 1;
        display: flex;
        justify-content: space-between;
        align-items: center;
      }

      .status-name {
        color: #e2e8f0;
        font-size: 14px;
      }

      .status-count {
        color: #94a3b8;
        font-size: 14px;
        font-weight: 600;
      }

      .status-percent {
        color: #60a5fa;
        font-size: 12px;
        font-weight: 600;
      }

      .insights-content {
        display: flex;
        flex-direction: column;
        gap: 12px;
      }

      .insight {
        display: flex;
        align-items: flex-start;
        gap: 12px;
        padding: 16px;
        border-radius: 8px;
        border-left: 4px solid;
        font-size: 14px;
        line-height: 1.5;
      }

      .insight.success {
        background: rgba(16, 185, 129, 0.1);
        border-left-color: #10b981;
        color: #10b981;
      }

      .insight.warning {
        background: rgba(245, 158, 11, 0.1);
        border-left-color: #f59e0b;
        color: #f59e0b;
      }

      .insight.critical {
        background: rgba(239, 68, 68, 0.1);
        border-left-color: #ef4444;
        color: #ef4444;
      }

      .insight.info {
