        display: flex;
        flex-direction: column;
        align-items: center;
        text-align: center;
        gap: 16px;
      }

      .export-card:hover {
        transform: translateY(-4px);
        background: rgba(30, 41, 59, 0.6);
        border-color: rgba(59, 130, 246, 0.5);
      }

      .export-card.bulk {
        grid-column: span 2;
      }

      .export-icon {
        width: 64px;
        height: 64px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 16px;
        background: rgba(51, 65, 85, 0.3);
        font-size: 24px;
      }

      .export-content h3 {
        margin: 0 0 8px 0;
        font-size: 20px;
        font-weight: 600;
        color: #e2e8f0;
      }

      .export-description {
        margin: 0 0 16px 0;
        color: #94a3b8;
        font-size: 14px;
        line-height: 1.5;
      }

      .export-features {
        display: flex;
        gap: 8px;
        flex-wrap: wrap;
        justify-content: center;
      }

      .feature-tag {
        padding: 4px 8px;
        background: rgba(51, 65, 85, 0.5);
        border-radius: 4px;
        font-size: 12px;
        color: #94a3b8;
        font-weight: 500;
      }

      .export-action {
        margin-top: auto;
        width: 40px;
        height: 40px;
        display: flex;
        align-items: center;
        justify-content: center;
        background: rgba(59, 130, 246, 0.1);
        border-radius: 50%;
        color: #60a5fa;
        font-size: 16px;
      }

      .export-status {
        padding: 16px;
        background: rgba(30, 41, 59, 0.8);
        border-radius: 8px;
        text-align: center;
      }

      .status-content {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 12px;
      }

      .status-text {
        color: #94a3b8;
        font-size: 14px;
      }
    </style>
    ''';
  }

