        background: rgba(51, 65, 85, 0.3);
      }

      .duplicate-keys-table td {
        padding: 16px 20px;
        color: #e2e8f0;
        vertical-align: top;
      }

      .key-name-cell {
        display: flex;
        flex-direction: column;
        gap: 4px;
      }

      .key-name-cell .key-name {
