        color: #f1f5f9;
        font-weight: 500;
      }

      .key-name-cell .key-category {
        font-size: 12px;
        color: #64748b;
      }

      .reference-count {
        font-weight: 600;
        padding: 4px 8px;
        border-radius: 4px;
        font-size: 12px;
      }

      .reference-count.low {
        background: rgba(34, 197, 94, 0.2);
        color: #22c55e;
      }

      .reference-count.medium {
        background: rgba(251, 146, 60, 0.2);
        color: #fb923c;
      }

      .reference-count.high {
        background: rgba(239, 68, 68, 0.2);
        color: #ef4444;
      }

      .locations-summary {
        display: flex;
        flex-direction: column;
        gap: 2px;
      }

      .location-item {
        font-family: 'JetBrains Mono', 'Fira Code', monospace;
        font-size: 12px;
        color: #94a3b8;
        background: rgba(51, 65, 85, 0.3);
        padding: 2px 6px;
        border-radius: 3px;
        display: inline-block;
        max-width: fit-content;
      }

      .more-locations {
        font-size: 12px;
        color: #64748b;
        font-style: italic;
        margin-top: 2px;
      }

      .impact-badge {
        font-weight: 500;
        padding: 4px 8px;
        border-radius: 4px;
        font-size: 12px;
        text-transform: uppercase;
      }

      .impact-badge.low {
        background: rgba(34, 197, 94, 0.2);
        color: #22c55e;
      }

      .impact-badge.medium {
        background: rgba(251, 146, 60, 0.2);
        color: #fb923c;
      }

      .impact-badge.high {
        background: rgba(239, 68, 68, 0.2);
        color: #ef4444;
      }

      .duplicate-actions {
        display: flex;
        gap: 8px;
      }

      /* Modal Styles */
      .modal {
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;
        background: rgba(0, 0, 0, 0.8);
        backdrop-filter: blur(8px);
        display: none;
        align-items: center;
        justify-content: center;
        z-index: 10000;
      }

      .modal-container {
        max-width: 80vw;
        max-height: 80vh;
        width: 900px;
      }

      .modal-content {
        background: rgba(15, 23, 42, 0.95);
        backdrop-filter: blur(20px);
        border: 1px solid rgba(51, 65, 85, 0.5);
        border-radius: 16px;
        overflow: hidden;
        box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
        max-width: 90vw;
        width: 900px;
      }

      .modal-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 24px 30px;
        border-bottom: 1px solid rgba(51, 65, 85, 0.3);
        background: rgba(30, 41, 59, 0.5);
      }

      .modal-title {
        color: #f1f5f9;
        font-size: 16px;
        font-weight: 600;
        margin: 0;
        max-width: 70%;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }

      .close-btn {
        width: 36px;
        height: 36px;
        background: rgba(51, 65, 85, 0.5);
        border: 1px solid rgba(51, 65, 85, 0.7);
        border-radius: 8px;
        color: #94a3b8;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        transition: all 0.2s ease;
      }

      .close-btn:hover {
        background: rgba(239, 68, 68, 0.2);
        border-color: rgba(239, 68, 68, 0.5);
        color: #f87171;
      }

      .modal-body {
        padding: 24px 30px;
        max-height: 60vh;
        overflow-y: auto;
      }

      .location-item {
        background: rgba(30, 41, 59, 0.3);
        border: 1px solid rgba(51, 65, 85, 0.3);
        border-radius: 12px;
        margin-bottom: 16px;
        overflow: hidden;
      }

      .location-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 16px 20px;
        background: rgba(15, 23, 42, 0.6);
        border-bottom: 1px solid rgba(51, 65, 85, 0.2);
      }

      .location-info {
        display: flex;
        flex-direction: column;
        gap: 6px;
      }

      .file-info {
        display: flex;
        align-items: center;
        gap: 8px;
      }

      .file-icon {
        color: #60a5fa;
      }

      .file-path {
        font-family: 'JetBrains Mono', 'Fira Code', monospace;
        color: #f1f5f9;
        font-weight: 500;
        font-size: 14px;
      }

      .line-info {
        color: #64748b;
        font-size: 12px;
      }

      .location-btn {
        background: rgba(59, 130, 246, 0.1);
        border: 1px solid rgba(59, 130, 246, 0.3);
        color: #60a5fa;
        padding: 6px 12px;
        border-radius: 6px;
        cursor: pointer;
        font-size: 12px;
        font-weight: 500;
        display: flex;
        align-items: center;
        gap: 6px;
        transition: all 0.2s ease;
      }

      .location-btn:hover {
        background: rgba(59, 130, 246, 0.2);
        border-color: rgba(59, 130, 246, 0.5);
      }

      .code-container {
        background: rgba(7, 10, 18, 0.8);
        border-top: 1px solid rgba(51, 65, 85, 0.2);
        font-family: 'JetBrains Mono', 'Fira Code', monospace;
        font-size: 13px;
        line-height: 1.5;
        overflow-x: auto;
      }

      .code-line {
        display: flex;
        padding: 0 16px;
        min-height: 24px;
        align-items: center;
      }

      .code-line.highlighted-line {
        background: rgba(59, 130, 246, 0.1);
        border-left: 3px solid #3b82f6;
      }

      .code-line-number {
        width: 40px;
        color: #64748b;
        font-size: 11px;
        margin-right: 16px;
        text-align: right;
        flex-shrink: 0;
        user-select: none;
      }

      .highlighted-key {
        background: rgba(245, 158, 11, 0.3);
        color: #fbbf24;
        padding: 2px 4px;
        border-radius: 4px;
        font-weight: 600;
      }

      /* Enhanced Code syntax highlighting for Dart/Flutter - Material Theme */
      .dart-keyword { 
        color: #c792ea; 
        font-weight: 700; 
        text-shadow: 0 0 2px rgba(199, 146, 234, 0.3);
      }
      .dart-type { 
        color: #82aaff; 
        font-weight: 600;
        text-shadow: 0 0 2px rgba(130, 170, 255, 0.3);
      }
      .dart-function { 
        color: #82d4ff; 
        font-weight: 500; 
        text-decoration: none;
      }
      .dart-function:hover { 
        color: #a5e3ff; 
        text-decoration: underline;
        cursor: pointer;
      }
      .dart-string { 
        color: #c3e88d; 
        font-weight: 400;
        background: rgba(195, 232, 141, 0.1);
        padding: 1px 2px;
        border-radius: 2px;
      }
      .dart-comment { 
        color: #546e7a; 
        font-style: italic; 
        opacity: 0.85;
        background: rgba(84, 110, 122, 0.08);
        padding: 1px 3px;
        border-radius: 3px;
      }
      .dart-number { 
        color: #f78c6c; 
        font-weight: 500;
        background: rgba(247, 140, 108, 0.15);
        padding: 1px 3px;
        border-radius: 2px;
      }
      .dart-operator { 
        color: #89ddff; 
        font-weight: 600;
        text-shadow: 0 0 2px rgba(137, 221, 255, 0.4);
      }
      .punctuation { 
        color: #89ddff; 
        opacity: 0.8;
      }
      .dart-variable { 
        color: #eeffff; 
        font-weight: 400;
      }
      .dart-annotation { 
        color: #ffcb6b; 
        font-weight: 600;
        background: rgba(255, 203, 107, 0.15);
        padding: 1px 4px;
        border-radius: 3px;
        border: 1px solid rgba(255, 203, 107, 0.3);
      }

      /* Better code container styling */
      .code-container {
        background: linear-gradient(135deg, rgba(7, 10, 18, 0.95), rgba(15, 20, 30, 0.9));
        border-top: 1px solid rgba(51, 65, 85, 0.3);
        font-family: 'JetBrains Mono', 'Fira Code', 'SF Mono', Consolas, monospace;
        font-size: 13px;
        line-height: 1.6;
        overflow-x: auto;
        border-radius: 0 0 12px 12px;
      }

      .code-line {
        display: flex;
        padding: 4px 20px;
        min-height: 22px;
        align-items: flex-start;
        transition: background-color 0.1s ease;
      }

      .code-line:hover {
        background: rgba(59, 130, 246, 0.05);
      }

      .code-line.highlighted-line {
        background: linear-gradient(90deg, rgba(59, 130, 246, 0.15), rgba(59, 130, 246, 0.05));
        border-left: 3px solid #3b82f6;
        padding-left: 13px;
      }

      .code-line-number {
        width: 45px;
        color: #64748b;
        font-size: 11px;
        margin-right: 20px;
        text-align: right;
        flex-shrink: 0;
        user-select: none;
        font-weight: 500;
        line-height: 1.6;
        padding-top: 1px;
      }

      .highlighted-line .code-line-number {
        color: #60a5fa;
        font-weight: 600;
      }

      /* Glassmorphism effects */
      .glass-morphism {
        backdrop-filter: blur(20px);
        -webkit-backdrop-filter: blur(20px);
      }

      /* Custom animations */
      @keyframes fadeIn {
        from { opacity: 0; transform: translateY(10px); }
        to { opacity: 1; transform: translateY(0); }
      }

      .animate-fade-in {
        animation: fadeIn 0.3s ease-out;
      }

      /* Custom scrollbar for dark theme */
      .custom-scrollbar::-webkit-scrollbar {
        width: 6px;
      }

      .custom-scrollbar::-webkit-scrollbar-track {
        background: rgba(51, 65, 85, 0.3);
        border-radius: 3px;
      }

      .custom-scrollbar::-webkit-scrollbar-thumb {
        background: rgba(148, 163, 184, 0.5);
        border-radius: 3px;
      }

      .custom-scrollbar::-webkit-scrollbar-thumb:hover {
        background: rgba(148, 163, 184, 0.7);
      }

      /* Enhanced code container with header */
      .code-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 8px 16px;
        background: linear-gradient(90deg, rgba(51, 65, 85, 0.8), rgba(30, 41, 59, 0.6));
        border-bottom: 1px solid rgba(51, 65, 85, 0.4);
        font-size: 12px;
        color: #94a3b8;
        border-radius: 6px 6px 0 0;
      }

      .code-language {
        font-weight: 600;
        color: #60a5fa;
        text-transform: uppercase;
        letter-spacing: 0.5px;
      }

      .code-copy-btn {
        background: rgba(59, 130, 246, 0.1);
        border: 1px solid rgba(59, 130, 246, 0.3);
        border-radius: 4px;
        color: #60a5fa;
        padding: 4px 8px;
        cursor: pointer;
        font-size: 11px;
        transition: all 0.2s ease;
      }

      .code-copy-btn:hover {
        background: rgba(59, 130, 246, 0.2);
        border-color: rgba(59, 130, 246, 0.5);
        color: #93c5fd;
        transform: translateY(-1px);
      }

      .code-copy-btn.copied {
        background: rgba(34, 197, 94, 0.2);
        border-color: rgba(34, 197, 94, 0.5);
        color: #4ade80;
      }

      /* Enhanced location buttons */
      .location-btn.secondary {
        background: rgba(75, 85, 99, 0.4);
        border-color: rgba(75, 85, 99, 0.6);
        color: #9ca3af;
      }

      .location-btn.secondary:hover {
        background: rgba(75, 85, 99, 0.6);
        border-color: rgba(75, 85, 99, 0.8);
        color: #d1d5db;
      }

      .location-actions {
        display: flex;
        gap: 8px;
        align-items: center;
      }

      .detector-info {
        background: rgba(99, 102, 241, 0.15);
        color: #a5b4fc;
        padding: 2px 6px;
        border-radius: 3px;
        font-size: 10px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.3px;
      }

      /* Toast notifications */
      .toast {
        position: fixed;
        top: 20px;
        right: 20px;
        z-index: 10000;
        padding: 12px 20px;
        border-radius: 6px;
        color: white;
        font-weight: 500;
        font-size: 14px;
        transform: translateX(400px);
        transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
        backdrop-filter: blur(10px);
        -webkit-backdrop-filter: blur(10px);
        box-shadow: 0 8px 25px rgba(0, 0, 0, 0.3);
      }

      .toast.show {
        transform: translateX(0);
      }

      .toast-success {
        background: linear-gradient(135deg, rgba(34, 197, 94, 0.9), rgba(21, 128, 61, 0.9));
        border: 1px solid rgba(34, 197, 94, 0.3);
      }

      .toast-error {
        background: linear-gradient(135deg, rgba(239, 68, 68, 0.9), rgba(185, 28, 28, 0.9));
        border: 1px solid rgba(239, 68, 68, 0.3);
      }

      .toast-info {
        background: linear-gradient(135deg, rgba(59, 130, 246, 0.9), rgba(37, 99, 235, 0.9));
        border: 1px solid rgba(59, 130, 246, 0.3);
      }

      /* Keyboard shortcuts */
      .keyboard-shortcuts {
        position: fixed;
        bottom: 20px;
        left: 20px;
        background: rgba(15, 23, 42, 0.9);
        backdrop-filter: blur(10px);
        border: 1px solid rgba(51, 65, 85, 0.3);
        border-radius: 8px;
        padding: 12px 16px;
        color: #94a3b8;
        font-size: 12px;
        z-index: 1000;
        opacity: 0.7;
        transition: opacity 0.2s ease;
      }

      .keyboard-shortcuts:hover {
        opacity: 1;
      }

      .keyboard-shortcut {
        display: flex;
        justify-content: space-between;
        margin: 2px 0;
        min-width: 200px;
      }

      .shortcut-key {
        background: rgba(51, 65, 85, 0.8);
        padding: 2px 6px;
        border-radius: 3px;
        font-family: monospace;
        font-size: 11px;
        color: #e2e8f0;
      }

      /* Section Headers */
      .section-header {
        margin-bottom: 32px;
        padding: 24px 32px;
        border-radius: 16px;
      }

      .section-title-wrapper {
        display: flex;
        align-items: center;
        gap: 16px;
      }

      .section-icon {
        width: 48px;
        height: 48px;
        display: flex;
        align-items: center;
        justify-content: center;
        background: rgba(59, 130, 246, 0.1);
        border-radius: 12px;
        color: #60a5fa;
        font-size: 20px;
      }

      .section-title-content h2 {
        margin: 0 0 8px 0;
        font-size: 28px;
        font-weight: 700;
        color: #e2e8f0;
      }

      .section-subtitle {
        margin: 0;
        color: #94a3b8;
        font-size: 16px;
      }

      /* Analysis Section */
      .analysis-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
        gap: 24px;
        margin-bottom: 32px;
      }

      .analysis-card {
        padding: 24px;
        border-radius: 16px;
      }

      .analysis-header {
        display: flex;
        align-items: center;
        gap: 12px;
        margin-bottom: 20px;
      }

      .analysis-header h3 {
        margin: 0;
        font-size: 18px;
        font-weight: 600;
        color: #e2e8f0;
      }

      .quality-score {
        display: flex;
        align-items: center;
        gap: 20px;
      }

      .score-circle {
        width: 80px;
        height: 80px;
        border-radius: 50%;
        background: conic-gradient(from 0deg, #10b981 0deg, #10b981 calc(var(--percentage, 75) * 3.6deg), rgba(51, 65, 85, 0.3) calc(var(--percentage, 75) * 3.6deg));
        display: flex;
        align-items: center;
        justify-content: center;
        position: relative;
      }

      .score-circle::before {
        content: '';
        position: absolute;
        width: 60px;
        height: 60px;
        background: #1e293b;
        border-radius: 50%;
      }

      .score-text {
        position: relative;
        z-index: 1;
        font-size: 18px;
        font-weight: 700;
        color: #10b981;
      }

      .score-details {
        flex: 1;
      }

      .score-item {
        display: flex;
        justify-content: space-between;
        margin-bottom: 8px;
      }

      .score-item .label {
        color: #94a3b8;
        font-size: 14px;
      }

      .score-item .value {
        font-weight: 600;
        font-size: 14px;
      }

      .distribution-items {
        display: flex;
        flex-direction: column;
        gap: 12px;
      }

      .distribution-item {
        display: grid;
        grid-template-columns: 1fr 80px 40px;
        align-items: center;
        gap: 12px;
      }

      .category-info {
        display: flex;
        flex-direction: column;
      }

      .category-name {
        color: #e2e8f0;
        font-size: 14px;
        font-weight: 500;
      }

      .category-count {
        color: #64748b;
        font-size: 12px;
      }

      .category-bar {
        height: 8px;
        background: rgba(51, 65, 85, 0.3);
        border-radius: 4px;
        overflow: hidden;
      }

      .bar-fill {
        height: 100%;
        background: linear-gradient(90deg, #60a5fa, #3b82f6);
        transition: width 0.3s ease;
      }

      .category-percentage {
        text-align: right;
        color: #60a5fa;
        font-size: 12px;
        font-weight: 600;
      }

      .issues-list {
        display: flex;
        flex-direction: column;
        gap: 12px;
      }

      .issue-item {
        display: flex;
        align-items: center;
        gap: 12px;
        padding: 12px 16px;
        border-radius: 8px;
      }

      .issue-item.critical {
        background: rgba(239, 68, 68, 0.1);
        border: 1px solid rgba(239, 68, 68, 0.3);
      }

      .issue-item.warning {
        background: rgba(245, 158, 11, 0.1);
        border: 1px solid rgba(245, 158, 11, 0.3);
      }

      .issue-item.resolved {
        background: rgba(16, 185, 129, 0.1);
        border: 1px solid rgba(16, 185, 129, 0.3);
      }

      .issue-text {
        flex: 1;
        color: #e2e8f0;
        font-size: 14px;
      }

      .issue-severity {
        font-size: 12px;
        font-weight: 600;
        padding: 4px 8px;
        border-radius: 4px;
      }

      .critical .issue-severity { background: rgba(239, 68, 68, 0.2); color: #ef4444; }
      .warning .issue-severity { background: rgba(245, 158, 11, 0.2); color: #f59e0b; }
      .resolved .issue-severity { background: rgba(16, 185, 129, 0.2); color: #10b981; }

      /* Stats Section */
      .stats-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
        gap: 24px;
        margin-bottom: 32px;
      }

      .stats-card {
        padding: 24px;
        border-radius: 16px;
      }

      .stats-card.full-width {
        grid-column: 1 / -1;
      }

      .stats-header {
        display: flex;
        align-items: center;
        gap: 12px;
        margin-bottom: 20px;
      }

      .stats-header h3 {
        margin: 0;
        font-size: 18px;
        font-weight: 600;
        color: #e2e8f0;
      }

      .coverage-visual {
        display: flex;
        justify-content: center;
        margin-bottom: 20px;
      }

      .coverage-circle {
        width: 120px;
        height: 120px;
        border-radius: 50%;
        background: conic-gradient(from 0deg, #3b82f6 0deg, #3b82f6 calc(var(--percentage, 0) * 3.6deg), rgba(51, 65, 85, 0.3) calc(var(--percentage, 0) * 3.6deg));
        display: flex;
        align-items: center;
        justify-content: center;
        position: relative;
      }

      .coverage-circle::before {
        content: '';
        position: absolute;
        width: 90px;
        height: 90px;
        background: #1e293b;
        border-radius: 50%;
      }

      .coverage-text {
        position: relative;
        z-index: 1;
        font-size: 24px;
        font-weight: 700;
        color: #3b82f6;
      }

      .coverage-details, .performance-metrics {
        display: flex;
        flex-direction: column;
        gap: 12px;
      }

      .detail-item, .metric-row {
        display: flex;
        justify-content: space-between;
      }

      /* Enhanced Performance Metrics */
      .performance-visual {
        display: flex;
        justify-content: center;
        margin-bottom: 16px;
      }

      .metric-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 12px;
      }

      .metric-item {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 4px;
        padding: 8px;
        border-radius: 8px;
        background: rgba(255, 255, 255, 0.02);
        border: 1px solid rgba(255, 255, 255, 0.05);
      }

      .metric-label {
        font-size: 0.75rem;
        color: #9CA3AF;
        text-align: center;
      }

      .metric-value {
        font-size: 1.1rem;
        font-weight: 600;
        color: white;
      }

      .metric-trend {
        font-size: 0.8rem;
        padding: 2px 4px;
        border-radius: 4px;
      }

      .metric-trend.excellent {
        color: #10B981;
        background: rgba(16, 185, 129, 0.1);
      }

      .metric-trend.good {
        color: #3B82F6;
        background: rgba(59, 130, 246, 0.1);
      }

      .metric-trend.average {
        color: #F59E0B;
        background: rgba(245, 158, 11, 0.1);
      }

      .metric-trend.poor {
        color: #EF4444;
        background: rgba(239, 68, 68, 0.1);
      }

      /* Distribution Chart Styles */
      .distribution-content {
        display: flex;
        gap: 16px;
        align-items: center;
      }

      .distribution-visual {
        flex-shrink: 0;
      }

      .distribution-legend {
        flex: 1;
        display: flex;
        flex-direction: column;
        gap: 8px;
      }

      .legend-item {
        display: flex;
        align-items: center;
        gap: 8px;
        padding: 4px 0;
      }

      .legend-color {
        width: 12px;
        height: 12px;
        border-radius: 2px;
        flex-shrink: 0;
      }

      .legend-label {
        flex: 1;
        font-size: 0.875rem;
        color: #E5E7EB;
      }

      .legend-count {
        font-size: 0.875rem;
        font-weight: 600;
        color: white;
        min-width: 20px;
        text-align: right;
      }

      /* Quality Score Styles */
      .quality-metrics {
        display: flex;
        gap: 20px;
        align-items: center;
      }

      .quality-score {
        flex-shrink: 0;
      }

      .score-circle {
        width: 120px;
        height: 120px;
        border-radius: 50%;
        background: conic-gradient(
          from 0deg,
          #3B82F6 0deg,
          #3B82F6 calc(var(--score) * 3.6deg),
          rgba(255, 255, 255, 0.1) calc(var(--score) * 3.6deg),
          rgba(255, 255, 255, 0.1) 360deg
        );
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        position: relative;
      }

      .score-circle::before {
        content: '';
        position: absolute;
        width: 90px;
        height: 90px;
        border-radius: 50%;
        background: #1F2937;
      }

      .score-text {
        font-size: 1.5rem;
        font-weight: 700;
        color: white;
        z-index: 1;
      }

      .score-label {
        font-size: 0.75rem;
        color: #9CA3AF;
        z-index: 1;
      }

      .quality-breakdown {
        flex: 1;
        display: flex;
        flex-direction: column;
        gap: 12px;
      }

      .quality-item {
        display: flex;
        align-items: center;
        gap: 12px;
      }

      .quality-label {
        width: 90px;
        font-size: 0.875rem;
        color: #9CA3AF;
        flex-shrink: 0;
      }

      .quality-bar {
        flex: 1;
        height: 8px;
        background: rgba(255, 255, 255, 0.1);
        border-radius: 4px;
        overflow: hidden;
      }

      .quality-fill {
        height: 100%;
        background: linear-gradient(90deg, #10B981, #3B82F6);
        border-radius: 4px;
        transition: width 1s ease-in-out;
      }

      .quality-value {
        width: 40px;
        text-align: right;
        font-size: 0.875rem;
        font-weight: 600;
        color: white;
        flex-shrink: 0;
      }

      /* Enhanced Insights Styles */
      .insight-content {
        margin-left: 28px;
      }

      .insight-content h4 {
        margin: 0 0 8px 0;
        font-size: 1rem;
        font-weight: 600;
        color: white;
      }

      .insight-content p {
        margin: 0 0 12px 0;
        font-size: 0.875rem;
        color: #D1D5DB;
        line-height: 1.4;
      }

      .action-items {
        display: flex;
        flex-direction: column;
        gap: 4px;
      }

      .action-item {
        font-size: 0.8rem;
        color: #9CA3AF;
        line-height: 1.3;
      }

      .detail-label, .metric-label {
        color: #94a3b8;
        font-size: 14px;
      }

      .detail-value, .metric-value {
        color: #e2e8f0;
        font-weight: 600;
        font-size: 14px;
      }

      .status-chart {
        display: flex;
        flex-direction: column;
        gap: 16px;
      }

      .status-item {
        display: flex;
        align-items: center;
        gap: 12px;
      }

      .status-indicator {
        width: 16px;
        height: 16px;
        border-radius: 50%;
      }

      .status-indicator.active {
        background: #10b981;
      }

      .status-indicator.inactive {
        background: #64748b;
      }

      .status-info {
        flex: 1;
        display: flex;
        justify-content: space-between;
        align-items: center;
      }

      .status-name {
        color: #e2e8f0;
        font-size: 14px;
      }

      .status-count {
        color: #94a3b8;
        font-size: 14px;
        font-weight: 600;
      }

      .status-percent {
        color: #60a5fa;
        font-size: 12px;
        font-weight: 600;
      }

      .insights-content {
        display: flex;
        flex-direction: column;
        gap: 12px;
      }

      .insight {
        display: flex;
        align-items: flex-start;
        gap: 12px;
        padding: 16px;
        border-radius: 8px;
        border-left: 4px solid;
        font-size: 14px;
        line-height: 1.5;
      }

      .insight.success {
        background: rgba(16, 185, 129, 0.1);
        border-left-color: #10b981;
        color: #10b981;
      }

      .insight.warning {
        background: rgba(245, 158, 11, 0.1);
        border-left-color: #f59e0b;
        color: #f59e0b;
      }

      .insight.critical {
        background: rgba(239, 68, 68, 0.1);
        border-left-color: #ef4444;
        color: #ef4444;
      }

      .insight.info {
        background: rgba(59, 130, 246, 0.1);
        border-left-color: #3b82f6;
        color: #3b82f6;
      }

      /* Export Section */
      .export-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
        gap: 24px;
        margin-bottom: 32px;
      }

      .export-card {
        padding: 24px;
        border-radius: 16px;
        cursor: pointer;
        transition: all 0.3s ease;
        display: flex;
        flex-direction: column;
        align-items: center;
        text-align: center;
        gap: 16px;
      }

      .export-card:hover {
        transform: translateY(-4px);
        background: rgba(30, 41, 59, 0.6);
        border-color: rgba(59, 130, 246, 0.5);
      }

      .export-card.bulk {
        grid-column: span 2;
      }

      .export-icon {
        width: 64px;
        height: 64px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 16px;
        background: rgba(51, 65, 85, 0.3);
        font-size: 24px;
      }

      .export-content h3 {
        margin: 0 0 8px 0;
        font-size: 20px;
        font-weight: 600;
        color: #e2e8f0;
      }

      .export-description {
        margin: 0 0 16px 0;
        color: #94a3b8;
        font-size: 14px;
        line-height: 1.5;
      }

      .export-features {
        display: flex;
        gap: 8px;
        flex-wrap: wrap;
        justify-content: center;
      }

      .feature-tag {
        padding: 4px 8px;
        background: rgba(51, 65, 85, 0.5);
        border-radius: 4px;
        font-size: 12px;
        color: #94a3b8;
        font-weight: 500;
      }

      .export-action {
        margin-top: auto;
        width: 40px;
        height: 40px;
        display: flex;
        align-items: center;
        justify-content: center;
        background: rgba(59, 130, 246, 0.1);
        border-radius: 50%;
        color: #60a5fa;
        font-size: 16px;
      }

      .export-status {
        padding: 16px;
        background: rgba(30, 41, 59, 0.8);
        border-radius: 8px;
        text-align: center;
      }

      .status-content {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 12px;
      }

      .status-text {
        color: #94a3b8;
        font-size: 14px;
      }
    </style>
    ''';
  }

