            </div>

            <!-- Pagination -->
            <div class="pagination">
                <div class="pagination-info">
                    Showing <span class="pagination-info-highlight">1-${result.keyUsages.length}</span> of <span class="pagination-info-highlight">${result.keyUsages.length}</span> keys
