  String _buildDuplicateKeysTable(ScanResult result) {
    final duplicateKeysList = result.keyUsages.entries
        .where((entry) => entry.value.locations.length > 1)
        .toList();

    if (duplicateKeysList.isEmpty) return '';

    return '''
        <div class="duplicate-keys-section glass-card">
            <div class="section-header">
                <i class="fa-solid fa-copy text-orange-400"></i>
                <h3>Duplicate Keys Analysis</h3>
                <span class="duplicate-count">${duplicateKeysList.length} keys with multiple references</span>
            </div>

            <div class="duplicate-keys-table-container">
                <table class="duplicate-keys-table">
                    <thead>
                        <tr>
                            <th>Key Name</th>
                            <th>References</th>
                            <th>Locations</th>
                            <th>Impact</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${duplicateKeysList.map((entry) => _buildDuplicateKeyRow(entry.key, entry.value)).join('')}
                    </tbody>
                </table>
            </div>
        </div>
    ''';
  }

  String _buildDuplicateKeyRow(String keyName, KeyUsage keyData) {
    final refCount = keyData.locations.length;
    final impact = refCount > 5
        ? 'High'
        : refCount > 3
            ? 'Medium'
            : 'Low';
    final impactClass = refCount > 5
        ? 'high'
        : refCount > 3
            ? 'medium'
            : 'low';

    return '''
        <tr class="duplicate-row" data-key="$keyName">
            <td>
                <div class="key-name-cell">
                    <span class="key-name">$keyName</span>
                    <span class="key-category">${_inferCategory(keyName, keyData.tags)}</span>
                </div>
            </td>
            <td>
                <span class="reference-count $impactClass">$refCount</span>
            </td>
            <td>
                <div class="locations-summary">
                    ${keyData.locations.take(2).map((loc) => '<div class="location-item">${loc.file}:${loc.line}</div>').join('')}
                    ${keyData.locations.length > 2 ? '<div class="more-locations">+${keyData.locations.length - 2} more</div>' : ''}
                </div>
            </td>
            <td>
                <span class="impact-badge $impactClass">$impact</span>
            </td>
            <td>
                <div class="duplicate-actions">
                    <button class="action-btn" title="View all locations" onclick="openLocationsModal('$keyName')">
                        <i class="fa-solid fa-map-pin"></i>
                    </button>
                    <button class="action-btn" title="Analyze duplicates" onclick="analyzeDuplicates('$keyName')">
                        <i class="fa-solid fa-magnifying-glass"></i>
                    </button>
                </div>
            </td>
        </tr>
    ''';
  }

  // Enhanced helper methods for advanced statistics
  String _getPerformanceTrend(int milliseconds) {
    if (milliseconds < 2000) return 'excellent';
    if (milliseconds < 5000) return 'good';
    if (milliseconds < 10000) return 'average';
    return 'poor';
  }

  String _getPerformanceTrendIcon(int milliseconds) {
    if (milliseconds < 2000) return 'fa-rocket';
    if (milliseconds < 5000) return 'fa-arrow-up';
    if (milliseconds < 10000) return 'fa-minus';
    return 'fa-arrow-down';
  }

  int _calculateEfficiency(ScanResult result) {
    final keysPerSecond =
        result.keyUsages.length / (result.duration.inMilliseconds / 1000.0);
    if (keysPerSecond > 20) return 95;
    if (keysPerSecond > 10) return 85;
    if (keysPerSecond > 5) return 75;
    return 60;
  }

  String _getEfficiencyTrend(ScanResult result) {
    final efficiency = _calculateEfficiency(result);
    if (efficiency > 90) return 'excellent';
    if (efficiency > 80) return 'good';
    if (efficiency > 70) return 'average';
    return 'poor';
  }

  String _getEfficiencyTrendIcon(ScanResult result) {
    final efficiency = _calculateEfficiency(result);
    if (efficiency > 90) return 'fa-star';
    if (efficiency > 80) return 'fa-arrow-up';
    if (efficiency > 70) return 'fa-minus';
    return 'fa-arrow-down';
  }

  int _calculateQualityScore(ScanResult result) {
    var score = 0;

    // Coverage score (40% of total)
    score += (result.metrics.fileCoverage * 0.4).round();

    // Key organization score (30% of total)
    final organizationScore = _calculateOrganization(result);
    score += (organizationScore * 0.3).round();

    // Consistency score (30% of total)
    final consistencyScore = _calculateConsistency(result);
    score += (consistencyScore * 0.3).round();

    return score.clamp(0, 100);
  }

  int _calculateConsistency(ScanResult result) {
    final keyNames = result.keyUsages.keys;
    var consistencyScore = 90;

    // Check naming conventions
    var hasUnderscore = false;
    var hasCamelCase = false;

    for (final name in keyNames) {
      if (name.contains('_')) hasUnderscore = true;
      if (RegExp(r'[a-z][A-Z]').hasMatch(name)) hasCamelCase = true;
    }

    if (hasUnderscore && hasCamelCase) {
      consistencyScore -= 20;
    }

    // Check for duplicate patterns
    final duplicates =
        result.keyUsages.values.where((k) => k.locations.length > 1).length;
    if (duplicates > result.keyUsages.length * 0.1) {
      consistencyScore -= 15;
    }

    return consistencyScore.clamp(0, 100);
  }

  int _calculateOrganization(ScanResult result) {
    final keyNames = result.keyUsages.keys;
    var organizationScore = 85;

    // Check for clear categorization
    final categories =
        keyNames.map((name) => _inferCategory(name, <String>{})).toSet();
    final categoryRatio = categories.length / keyNames.length;

    if (categoryRatio > 0.8) {
      organizationScore += 10; // Very diverse, good organization
    } else if (categoryRatio < 0.3) {
      organizationScore -= 10; // Too homogeneous, might lack structure
    }

    // Check for descriptive naming
    final descriptiveKeys = keyNames
        .where((name) => name.length > 3 && !name.startsWith('key'))
        .length;
    final descriptiveRatio = descriptiveKeys / keyNames.length;

    if (descriptiveRatio > 0.8) {
      organizationScore += 5;
    } else if (descriptiveRatio < 0.5) {
      organizationScore -= 10;
    }

    return organizationScore.clamp(0, 100);
  }

  String _buildDistributionLegend(ScanResult result) {
    final categories = <String, int>{};

    for (final keyName in result.keyUsages.keys) {
      final category = _inferCategory(keyName, <String>{});
      categories[category] = (categories[category] ?? 0) + 1;
    }

    final legendItems = categories.entries.map((entry) => '''
      <div class="legend-item">
        <div class="legend-color" style="background-color: ${_getCategoryColor(entry.key)}"></div>
        <span class="legend-label">${entry.key}</span>
        <span class="legend-count">${entry.value}</span>
      </div>
    ''').join('');

    return legendItems;
  }

  String _getCategoryColor(String category) {
    switch (category) {
      case 'Buttons':
        return '#3b82f6';
      case 'Input Fields':
        return '#10b981';
      case 'Navigation':
        return '#f59e0b';
      case 'Modals':
        return '#8b5cf6';
      case 'Lists':
        return '#ef4444';
      default:
        return '#6b7280';
    }
  }

  String _buildEnhancedInsights(ScanResult result) {
    final insights = <String>[];
    final coverage = result.metrics.fileCoverage;
    final totalKeys = result.keyUsages.length;
    final qualityScore = _calculateQualityScore(result);
    final duplicates =
        result.keyUsages.values.where((k) => k.locations.length > 1).length;

    // Priority insights with actionable recommendations
    if (coverage < 50) {
      insights.add('''
        <div class="insight critical">
          <i class="fa-solid fa-triangle-exclamation"></i>
          <div class="insight-content">
            <h4>Low Key Coverage</h4>
            <p>Only ${coverage.toStringAsFixed(1)}% of files have keys. Consider adding keys to critical UI components for better test automation.</p>
            <div class="action-items">
              <span class="action-item">• Focus on user interaction elements first</span>
              <span class="action-item">• Add keys to forms, buttons, and navigation elements</span>
              <span class="action-item">• Target 70%+ coverage for production apps</span>
            </div>
          </div>
        </div>
      ''');
    } else if (coverage > 90) {
      insights.add('''
        <div class="insight success">
          <i class="fa-solid fa-trophy"></i>
          <div class="insight-content">
            <h4>Outstanding Coverage!</h4>
            <p>${coverage.toStringAsFixed(1)}% file coverage indicates excellent test automation readiness.</p>
            <div class="action-items">
              <span class="action-item">✓ Maintain current coverage levels</span>
              <span class="action-item">✓ Document key naming conventions</span>
              <span class="action-item">✓ Consider implementing key usage guidelines</span>
            </div>
          </div>
        </div>
      ''');
    }

    if (qualityScore < 70) {
      insights.add('''
        <div class="insight warning">
          <i class="fa-solid fa-exclamation-triangle"></i>
          <div class="insight-content">
            <h4>Quality Improvement Needed</h4>
            <p>Quality score: $qualityScore%. Focus on consistency and organization.</p>
            <div class="action-items">
              <span class="action-item">• Establish consistent naming conventions</span>
              <span class="action-item">• Organize keys by feature or screen</span>
              <span class="action-item">• Review and eliminate duplicate keys</span>
            </div>
          </div>
        </div>
      ''');
    }

    if (duplicates > 5) {
      insights.add('''
        <div class="insight warning">
          <i class="fa-solid fa-copy"></i>
          <div class="insight-content">
            <h4>Duplicate Key Management</h4>
            <p>$duplicates keys have multiple references. Consider consolidating or documenting intentional duplicates.</p>
            <div class="action-items">
              <span class="action-item">• Review duplicate keys in Analysis section</span>
              <span class="action-item">• Consolidate unintentional duplicates</span>
              <span class="action-item">• Document legitimate duplicate usage</span>
            </div>
          </div>
        </div>
      ''');
    }

    if (totalKeys > 100) {
      insights.add('''
        <div class="insight info">
          <i class="fa-solid fa-layer-group"></i>
          <div class="insight-content">
            <h4>Large Scale Project</h4>
            <p>$totalKeys keys detected. Consider advanced organization strategies.</p>
            <div class="action-items">
              <span class="action-item">• Group keys by feature modules</span>
              <span class="action-item">• Implement key prefixing strategy</span>
              <span class="action-item">• Consider automated key generation tools</span>
            </div>
          </div>
        </div>
      ''');
    }

    // Performance insights
    final scanTimeSeconds = result.duration.inMilliseconds / 1000.0;
    if (scanTimeSeconds > 10) {
      insights.add('''
        <div class="insight warning">
          <i class="fa-solid fa-clock"></i>
          <div class="insight-content">
            <h4>Performance Optimization</h4>
            <p>Scan time: ${scanTimeSeconds.toStringAsFixed(2)}s. Consider performance optimizations.</p>
            <div class="action-items">
              <span class="action-item">• Exclude unnecessary directories from scanning</span>
              <span class="action-item">• Use .flutter_keycheck_ignore for large assets</span>
              <span class="action-item">• Consider incremental scanning for large projects</span>
            </div>
          </div>
        </div>
      ''');
    }

    if (insights.isEmpty) {
      insights.add('''
        <div class="insight success">
          <i class="fa-solid fa-star"></i>
          <div class="insight-content">
            <h4>Excellent Key Management</h4>
            <p>Your project demonstrates best practices in Flutter key usage.</p>
            <div class="action-items">
              <span class="action-item">✓ Continue monitoring key coverage</span>
              <span class="action-item">✓ Share best practices with your team</span>
              <span class="action-item">✓ Consider automated key validation in CI/CD</span>
            </div>
          </div>
        </div>
      ''');
    }

    return insights.join('\n');
  }
}

/// Text reporter for human-readable output
class TextReporter extends ReporterV3 {
  @override
  Future<void> generateScanReport(
    ScanResult result,
    File outputFile, {
    bool includeMetrics = true,
    bool includeLocations = false,
  }) async {
    final buffer = StringBuffer();

    buffer.writeln('Flutter KeyCheck Scan Report');
    buffer.writeln('=' * 40);
    buffer.writeln();
    buffer.writeln('Summary:');
    buffer.writeln('  Total Keys: ${result.keyUsages.length}');
    buffer.writeln(
        '  Files Scanned: ${result.metrics.scannedFiles}/${result.metrics.totalFiles}');
    buffer.writeln(
        '  Coverage: ${result.metrics.fileCoverage.toStringAsFixed(1)}%');
    buffer.writeln();

    if (result.keyUsages.isNotEmpty) {
      buffer.writeln('Keys Found:');
      for (final entry in result.keyUsages.entries.take(20)) {
        buffer.writeln(
            '  - ${entry.key} (${entry.value.locations.length} locations)');
      }
      if (result.keyUsages.length > 20) {
        buffer.writeln('  ... and ${result.keyUsages.length - 20} more');
      }
    }

    await outputFile.writeAsString(buffer.toString());
  }

  @override
  Future<void> generateValidationReport(
    ValidationResult result,
    File outputFile, {
    bool includeMetrics = true,
  }) async {
    final buffer = StringBuffer();

    buffer.writeln('Flutter KeyCheck Validation Report');
    buffer.writeln('=' * 40);
    buffer.writeln();
    buffer.writeln('Status: ${result.hasViolations ? 'FAILED' : 'PASSED'}');
    buffer.writeln();

    if (result.hasViolations) {
      buffer.writeln('Violations:');
      if (result.lostKeys.isNotEmpty) {
        buffer.writeln('  Lost Keys: ${result.lostKeys.length}');
      }
      if (result.renamedKeys.isNotEmpty) {
        buffer.writeln('  Renamed Keys: ${result.renamedKeys.length}');
      }
    }

    await outputFile.writeAsString(buffer.toString());
  }
}

/// CI/CD reporter with beautiful terminal output
class CIReporter extends ReporterV3 {
  static const String _reset = '\x1B[0m';
  static const String _bold = '\x1B[1m';
  static const String _dim = '\x1B[2m';
  static const String _red = '\x1B[31m';
  static const String _green = '\x1B[32m';
  static const String _yellow = '\x1B[33m';
  static const String _blue = '\x1B[34m';
  static const String _magenta = '\x1B[35m';
  static const String _cyan = '\x1B[36m';
  static const String _white = '\x1B[37m';
  static const String _boldValidation = '\x1B[1m🔍';
  static const String _boldBuild = '\x1B[1m🔨';

  final bool useColors;
  final bool isGitLabCI;

  CIReporter({this.useColors = true})
      : isGitLabCI = Platform.environment['GITLAB_CI'] == 'true';

  @override
  Future<void> generateScanReport(
    ScanResult result,
    File outputFile, {
    bool includeMetrics = true,
    bool includeLocations = false,
  }) async {
    final buffer = StringBuffer();

    // Header with beautiful CI branding
    buffer.writeln(_formatHeader());

    // Build status badge
    buffer.writeln(_formatStatus(result));

    // Key metrics in a clean table format
    buffer.writeln(_formatMetrics(result));

    // Quality gates status
    buffer.writeln(_formatQualityGates(result));

    // Summary for CI logs
    buffer.writeln(_formatSummary(result));

    // GitLab-specific collapsible sections
    if (isGitLabCI) {
      buffer.writeln(_formatGitLabSections(result));
    }

    await outputFile.writeAsString(buffer.toString());

    // Also output to stdout for CI visibility
    stdout.write(buffer.toString());
  }

  @override
  Future<void> generateValidationReport(
    ValidationResult result,
    File outputFile, {
    bool includeMetrics = true,
  }) async {
    final buffer = StringBuffer();

    buffer.writeln(_formatHeader());

    final hasViolations = result.hasViolations;
    final status = hasViolations ? 'FAILED' : 'PASSED';
    final color = hasViolations ? _red : _green;

    if (useColors) {
      buffer.writeln(
          '$_boldValidation Result:$_reset $color$_bold● $status$_reset');
    } else {
      buffer.writeln('Validation Result: $status');
    }

    if (hasViolations && result.violations.isNotEmpty) {
      buffer.writeln(
          '\n${useColors ? '$_red$_bold❌ Critical Issues$_reset' : 'Critical Issues:'}');

      for (final violation in result.violations.take(10)) {
        final type = violation.type;
        final key = violation.key?.id ?? 'unknown';
        if (useColors) {
          buffer.writeln(
              '$_red• $type: $_white$key$_reset $_dim- ${violation.message}$_reset');
        } else {
          buffer.writeln('• $type: $key - ${violation.message}');
        }
      }

      if (result.violations.length > 10) {
        buffer.writeln(
            '${useColors ? _dim : ''}... and ${result.violations.length - 10} more violations${useColors ? _reset : ''}');
      }
    }

    await outputFile.writeAsString(buffer.toString());
    stdout.write(buffer.toString());
  }

  String _formatHeader() {
    if (!useColors) return '=== Flutter KeyCheck CI Report ===\n';

    return '''
$_cyan╔═══════════════════════════════════════════════════════════╗
║$_bold$_white                 🔑 FLUTTER KEYCHECK                    $_reset$_cyan║
║$_dim                  CI/CD Analysis Report                   $_reset$_cyan║
╚═══════════════════════════════════════════════════════════╝$_reset
''';
  }

  String _formatStatus(ScanResult result) {
    final hasIssues = result.blindSpots.isNotEmpty;
    final status = hasIssues ? 'WARNING' : 'PASSED';
    final color = hasIssues ? _yellow : _green;

    if (!useColors) return 'Status: $status\n';

    return '''
$_boldBuild Status:$_reset $color$_bold● $status$_reset
''';
  }

  String _formatMetrics(ScanResult result) {
    if (!useColors) {
      return '''
Metrics:
  Keys Found: ${result.keyUsages.length}
  Files Scanned: ${result.metrics.scannedFiles}/${result.metrics.totalFiles}
  Coverage: ${result.metrics.fileCoverage.toStringAsFixed(1)}%
  Scan Time: ${result.metrics.totalScanTime.inMilliseconds}ms
''';
    }

    return '''
$_bold📊 Key Metrics$_reset
$_cyan┌─────────────────┬────────────────────────────────┐
│$_bold Metric          $_reset$_cyan│$_bold Value                          $_reset$_cyan│
├─────────────────┼────────────────────────────────┤
│ Keys Found      │$_green$_bold ${result.keyUsages.length.toString().padLeft(29)} $_reset$_cyan│
│ Files Scanned   │$_blue$_bold ${'${result.metrics.scannedFiles}/${result.metrics.totalFiles}'.padLeft(29)} $_reset$_cyan│
│ Coverage        │$_yellow$_bold ${'${result.metrics.fileCoverage.toStringAsFixed(1)}%'.padLeft(29)} $_reset$_cyan│
│ Scan Duration   │$_magenta$_bold ${'${result.metrics.totalScanTime.inMilliseconds}ms'.padLeft(29)} $_reset$_cyan│
└─────────────────┴────────────────────────────────┘$_reset
''';
  }

  String _formatQualityGates(ScanResult result) {
    final gates = _analyzeQualityGates(result);

    if (!useColors) {
      return '''
Quality Gates:
${gates.map((gate) => '  ${gate['status'] == 'PASS' ? '✓' : '✗'} ${gate['name']}: ${gate['status']}').join('\n')}
''';
    }

    final buffer = StringBuffer();
    buffer.writeln('$_bold🎯 Quality Gates$_reset');

    for (final gate in gates) {
      final icon = gate['status'] == 'PASS' ? '✓' : '✗';
      final color = gate['status'] == 'PASS' ? _green : _red;
      final status = gate['status'] == 'PASS' ? 'PASS' : 'FAIL';

      buffer.writeln(
          '$color$_bold$icon ${gate['name']}: $status$_reset $_dim- ${gate['description']}$_reset');
    }

    return buffer.toString();
  }

  List<Map<String, String>> _analyzeQualityGates(ScanResult result) {
    return [
      {
        'name': 'Coverage Gate',
        'status': result.metrics.fileCoverage >= 80.0 ? 'PASS' : 'FAIL',
        'description': 'Minimum 80% file coverage required'
      },
      {
        'name': 'Blind Spot Check',
        'status': result.blindSpots.length <= 5 ? 'PASS' : 'WARN',
        'description': 'Maximum 5 blind spots allowed'
      },
      {
        'name': 'Performance Gate',
        'status': result.metrics.totalScanTime.inSeconds < 30 ? 'PASS' : 'WARN',
        'description': 'Scan completed under 30 seconds'
      }
    ];
  }

  String _formatSummary(ScanResult result) {
    final hasWarnings = result.blindSpots.isNotEmpty;

    if (!hasWarnings) {
      return useColors
          ? '$_green$_bold🎉 All checks passed! Your Flutter app is ready for automation testing.$_reset\n'
          : '✓ All checks passed! Your Flutter app is ready for automation testing.\n';
    }

    final buffer = StringBuffer();
    if (useColors) buffer.writeln('$_yellow$_bold⚠️ Action Required$_reset');

    if (hasWarnings) {
      buffer.writeln(useColors
          ? '$_yellow• ${result.blindSpots.length} blind spots detected$_reset'
          : '• ${result.blindSpots.length} blind spots detected');
    }

    return buffer.toString();
  }

  String _formatGitLabSections(ScanResult result) {
    final buffer = StringBuffer();

    // Collapsible section for detailed results
    if (result.keyUsages.isNotEmpty) {
      buffer.writeln(
          '\ndetail<summary><b>📋 Key Details (${result.keyUsages.length} total)</b></summary>');

      final keysByCategory = <String, List<String>>{};
      for (final entry in result.keyUsages.entries) {
        final category = _categorizeKey(entry.key);
        keysByCategory.putIfAbsent(category, () => []).add(entry.key);
      }

      for (final entry in keysByCategory.entries) {
        buffer.writeln(
            '\n**${entry.key.toUpperCase()} (${entry.value.length})**');
        for (final key in entry.value) {
          buffer.writeln('- `$key`');
        }
      }

      buffer.writeln('detail');
    }

    // Collapsible section for blind spots
    if (result.blindSpots.isNotEmpty) {
      buffer.writeln(
          '\ndetail<summary><b>⚠️ Blind Spots (${result.blindSpots.length} found)</b></summary>');

      for (final spot in result.blindSpots) {
        buffer.writeln('- **${spot.location}**: ${spot.message}');
        buffer.writeln('  *Type: ${spot.type}* | *Severity: ${spot.severity}*');
      }

      buffer.writeln('detail');
    }

    return buffer.toString();
  }

  String _categorizeKey(String keyName) {
    final name = keyName.toLowerCase();
    if (name.contains('btn') || name.contains('button')) return 'Actions';
    if (name.contains('field') || name.contains('input')) return 'Forms';
    if (name.contains('nav') || name.contains('menu')) return 'Navigation';
    if (name.contains('text') || name.contains('label')) return 'Content';
    return 'Other';
  }

  String _buildKeyDistribution(ScanResult result) {
    final categories = <String, int>{};
    for (final usage in result.keyUsages.values) {
      final category = _categorizeKeyName(usage.id);
      categories[category] = (categories[category] ?? 0) + 1;
    }

    final buffer = StringBuffer();
    buffer.writeln('<div class="distribution-items">');

    for (final entry in categories.entries) {
      final percentage = (entry.value / result.keyUsages.length * 100).round();
      buffer.writeln('''
        <div class="distribution-item">
            <div class="category-info">
                <span class="category-name">${entry.key}</span>
                <span class="category-count">${entry.value} keys</span>
            </div>
            <div class="category-bar">
                <div class="bar-fill" style="width: $percentage%"></div>
            </div>
            <div class="category-percentage">$percentage%</div>
        </div>
      ''');
    }

    buffer.writeln('</div>');
    return buffer.toString();
  }

  String _categorizeKeyName(String keyName) {
    final name = keyName.toLowerCase();
    if (name.contains('button') || name.contains('btn')) return 'Buttons';
    if (name.contains('field') ||
        name.contains('input') ||
        name.contains('text')) {
      return 'Input Fields';
    }
    if (name.contains('menu') || name.contains('nav')) return 'Navigation';
    if (name.contains('modal') || name.contains('dialog')) return 'Modals';
    if (name.contains('list') || name.contains('item')) return 'Lists';
    return 'Other';
  }

  String _buildDuplicateKeysTable(ScanResult result) {
    final duplicateKeysList = result.keyUsages.entries
        .where((entry) => entry.value.locations.length > 1)
        .toList();

    if (duplicateKeysList.isEmpty) return '';

    return '''
        <div class="duplicate-keys-section glass-card">
            <div class="section-header">
                <i class="fa-solid fa-copy text-orange-400"></i>
                <h3>Duplicate Keys Analysis</h3>
                <span class="duplicate-count">${duplicateKeysList.length} keys with multiple references</span>
            </div>

            <div class="duplicate-keys-table-container">
                <table class="duplicate-keys-table">
                    <thead>
                        <tr>
                            <th>Key Name</th>
                            <th>References</th>
                            <th>Locations</th>
                            <th>Impact</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${duplicateKeysList.map((entry) => _buildDuplicateKeyRow(entry.key, entry.value)).join('')}
                    </tbody>
                </table>
            </div>
        </div>
    ''';
  }

  String _buildDuplicateKeyRow(String keyName, KeyUsage keyData) {
    final refCount = keyData.locations.length;
    final impact = refCount > 5
        ? 'High'
        : refCount > 3
            ? 'Medium'
            : 'Low';
    final impactClass = refCount > 5
        ? 'high'
        : refCount > 3
            ? 'medium'
            : 'low';

    return '''
        <tr class="duplicate-row" data-key="$keyName">
            <td>
                <div class="key-name-cell">
                    <span class="key-name">$keyName</span>
                    <span class="key-category">${_inferCategory(keyName, keyData.tags)}</span>
                </div>
            </td>
            <td>
                <span class="reference-count $impactClass">$refCount</span>
            </td>
            <td>
                <div class="locations-summary">
                    ${keyData.locations.take(2).map((loc) => '<div class="location-item">${loc.file}:${loc.line}</div>').join('')}
                    ${keyData.locations.length > 2 ? '<div class="more-locations">+${keyData.locations.length - 2} more</div>' : ''}
                </div>
            </td>
            <td>
                <span class="impact-badge $impactClass">$impact</span>
            </td>
            <td>
                <div class="duplicate-actions">
                    <button class="action-btn" title="View all locations" onclick="openLocationsModal('$keyName')">
                        <i class="fa-solid fa-map-pin"></i>
                    </button>
                    <button class="action-btn" title="Analyze duplicates" onclick="analyzeDuplicates('$keyName')">
                        <i class="fa-solid fa-magnifying-glass"></i>
                    </button>
                </div>
            </td>
        </tr>
    ''';
  }

  String _inferCategory(String keyName, Set<String> tags) {
    if (keyName.toLowerCase().contains('button') ||
        keyName.toLowerCase().contains('widget')) {
      return 'widget';
    }
    if (keyName.toLowerCase().contains('test')) return 'test';
    if (keyName.toLowerCase().contains('navigate') ||
        keyName.toLowerCase().contains('route')) {
      return 'navigation';
    }
    if (keyName.toLowerCase().contains('handle') ||
        keyName.toLowerCase().contains('on')) {
      return 'handler';
    }
    if (tags.contains('widget')) return 'widget';
    if (tags.contains('test')) return 'test';
    if (tags.contains('navigation')) return 'navigation';
    if (tags.contains('handler')) return 'handler';
    return 'widget'; // default
  }

  // Enhanced helper methods for advanced statistics
  String _getPerformanceTrend(int milliseconds) {
    if (milliseconds < 2000) return 'excellent';
    if (milliseconds < 5000) return 'good';
    if (milliseconds < 10000) return 'average';
    return 'poor';
  }

  String _getPerformanceTrendIcon(int milliseconds) {
    if (milliseconds < 2000) return 'fa-rocket';
    if (milliseconds < 5000) return 'fa-arrow-up';
    if (milliseconds < 10000) return 'fa-minus';
    return 'fa-arrow-down';
  }

  int _calculateEfficiency(ScanResult result) {
    final keysPerSecond =
        result.keyUsages.length / (result.duration.inMilliseconds / 1000.0);
    if (keysPerSecond > 20) return 95;
    if (keysPerSecond > 10) return 85;
    if (keysPerSecond > 5) return 75;
    return 60;
  }

  String _getEfficiencyTrend(ScanResult result) {
    final efficiency = _calculateEfficiency(result);
    if (efficiency > 90) return 'excellent';
    if (efficiency > 80) return 'good';
    if (efficiency > 70) return 'average';
    return 'poor';
  }

  String _getEfficiencyTrendIcon(ScanResult result) {
    final efficiency = _calculateEfficiency(result);
    if (efficiency > 90) return 'fa-star';
    if (efficiency > 80) return 'fa-arrow-up';
    if (efficiency > 70) return 'fa-minus';
    return 'fa-arrow-down';
  }

  int _calculateQualityScore(ScanResult result) {
    var score = 0;

    // Coverage score (40% of total)
    score += (result.metrics.fileCoverage * 0.4).round();

    // Key organization score (30% of total)
    final organizationScore = _calculateOrganization(result);
    score += (organizationScore * 0.3).round();

    // Consistency score (30% of total)
    final consistencyScore = _calculateConsistency(result);
    score += (consistencyScore * 0.3).round();

    return score.clamp(0, 100);
  }

  int _calculateConsistency(ScanResult result) {
    final keyNames = result.keyUsages.keys;
    var consistencyScore = 90;

    // Check naming conventions
    var hasUnderscore = false;
    var hasCamelCase = false;

    for (final name in keyNames) {
      if (name.contains('_')) hasUnderscore = true;
      if (RegExp(r'[a-z][A-Z]').hasMatch(name)) hasCamelCase = true;
    }

    if (hasUnderscore && hasCamelCase) {
      consistencyScore -= 20;
    }

    // Check for duplicate patterns
    final duplicates =
        result.keyUsages.values.where((k) => k.locations.length > 1).length;
    if (duplicates > result.keyUsages.length * 0.1) {
      consistencyScore -= 15;
    }

    return consistencyScore.clamp(0, 100);
  }

  int _calculateOrganization(ScanResult result) {
    final keyNames = result.keyUsages.keys;
    var organizationScore = 85;

    // Check for clear categorization
    final categories =
        keyNames.map((name) => _inferCategory(name, <String>{})).toSet();
    final categoryRatio = categories.length / keyNames.length;

    if (categoryRatio > 0.8) {
      organizationScore += 10; // Very diverse, good organization
    } else if (categoryRatio < 0.3) {
      organizationScore -= 10; // Too homogeneous, might lack structure
    }

    // Check for descriptive naming
    final descriptiveKeys = keyNames
        .where((name) => name.length > 3 && !name.startsWith('key'))
        .length;
    final descriptiveRatio = descriptiveKeys / keyNames.length;

    if (descriptiveRatio > 0.8) {
      organizationScore += 5;
    } else if (descriptiveRatio < 0.5) {
      organizationScore -= 10;
    }

    return organizationScore.clamp(0, 100);
  }

  String _buildDistributionLegend(ScanResult result) {
    final categories = <String, int>{};

    for (final keyName in result.keyUsages.keys) {
      final category = _inferCategory(keyName, <String>{});
      categories[category] = (categories[category] ?? 0) + 1;
    }

    final legendItems = categories.entries.map((entry) => '''
      <div class="legend-item">
        <div class="legend-color" style="background-color: ${_getCategoryColor(entry.key)}"></div>
        <span class="legend-label">${entry.key}</span>
        <span class="legend-count">${entry.value}</span>
      </div>
    ''').join('');

    return legendItems;
  }

  String _getCategoryColor(String category) {
    switch (category) {
      case 'Buttons':
        return '#3b82f6';
      case 'Input Fields':
        return '#10b981';
      case 'Navigation':
        return '#f59e0b';
      case 'Modals':
        return '#8b5cf6';
      case 'Lists':
        return '#ef4444';
      default:
        return '#6b7280';
    }
  }

  String _buildEnhancedInsights(ScanResult result) {
    final insights = <String>[];
    final coverage = result.metrics.fileCoverage;
    final totalKeys = result.keyUsages.length;
    final qualityScore = _calculateQualityScore(result);
    final duplicates =
        result.keyUsages.values.where((k) => k.locations.length > 1).length;

    // Priority insights with actionable recommendations
    if (coverage < 50) {
      insights.add('''
        <div class="insight critical">
          <i class="fa-solid fa-triangle-exclamation"></i>
          <div class="insight-content">
            <h4>Low Key Coverage</h4>
            <p>Only ${coverage.toStringAsFixed(1)}% of files have keys. Consider adding keys to critical UI components for better test automation.</p>
            <div class="action-items">
              <span class="action-item">• Focus on user interaction elements first</span>
              <span class="action-item">• Add keys to forms, buttons, and navigation elements</span>
              <span class="action-item">• Target 70%+ coverage for production apps</span>
            </div>
          </div>
        </div>
      ''');
    } else if (coverage > 90) {
      insights.add('''
        <div class="insight success">
          <i class="fa-solid fa-trophy"></i>
          <div class="insight-content">
            <h4>Outstanding Coverage!</h4>
            <p>${coverage.toStringAsFixed(1)}% file coverage indicates excellent test automation readiness.</p>
            <div class="action-items">
              <span class="action-item">✓ Maintain current coverage levels</span>
              <span class="action-item">✓ Document key naming conventions</span>
              <span class="action-item">✓ Consider implementing key usage guidelines</span>
            </div>
          </div>
        </div>
      ''');
    }

    if (qualityScore < 70) {
      insights.add('''
        <div class="insight warning">
          <i class="fa-solid fa-exclamation-triangle"></i>
          <div class="insight-content">
            <h4>Quality Improvement Needed</h4>
            <p>Quality score: $qualityScore%. Focus on consistency and organization.</p>
            <div class="action-items">
              <span class="action-item">• Establish consistent naming conventions</span>
              <span class="action-item">• Organize keys by feature or screen</span>
              <span class="action-item">• Review and eliminate duplicate keys</span>
            </div>
          </div>
        </div>
      ''');
    }

    if (duplicates > 5) {
      insights.add('''
        <div class="insight warning">
          <i class="fa-solid fa-copy"></i>
          <div class="insight-content">
            <h4>Duplicate Key Management</h4>
            <p>$duplicates keys have multiple references. Consider consolidating or documenting intentional duplicates.</p>
            <div class="action-items">
              <span class="action-item">• Review duplicate keys in Analysis section</span>
              <span class="action-item">• Consolidate unintentional duplicates</span>
              <span class="action-item">• Document legitimate duplicate usage</span>
            </div>
          </div>
        </div>
      ''');
    }

    if (totalKeys > 100) {
      insights.add('''
        <div class="insight info">
          <i class="fa-solid fa-layer-group"></i>
          <div class="insight-content">
            <h4>Large Scale Project</h4>
            <p>$totalKeys keys detected. Consider advanced organization strategies.</p>
            <div class="action-items">
              <span class="action-item">• Group keys by feature modules</span>
              <span class="action-item">• Implement key prefixing strategy</span>
              <span class="action-item">• Consider automated key generation tools</span>
            </div>
          </div>
        </div>
      ''');
    }

    // Performance insights
    final scanTimeSeconds = result.duration.inMilliseconds / 1000.0;
    if (scanTimeSeconds > 10) {
      insights.add('''
        <div class="insight warning">
          <i class="fa-solid fa-clock"></i>
          <div class="insight-content">
            <h4>Performance Optimization</h4>
            <p>Scan time: ${scanTimeSeconds.toStringAsFixed(2)}s. Consider performance optimizations.</p>
            <div class="action-items">
              <span class="action-item">• Exclude unnecessary directories from scanning</span>
              <span class="action-item">• Use .flutter_keycheck_ignore for large assets</span>
              <span class="action-item">• Consider incremental scanning for large projects</span>
            </div>
          </div>
        </div>
      ''');
    }

    if (insights.isEmpty) {
      insights.add('''
        <div class="insight success">
          <i class="fa-solid fa-star"></i>
          <div class="insight-content">
            <h4>Excellent Key Management</h4>
            <p>Your project demonstrates best practices in Flutter key usage.</p>
            <div class="action-items">
              <span class="action-item">✓ Continue monitoring key coverage</span>
              <span class="action-item">✓ Share best practices with your team</span>
              <span class="action-item">✓ Consider automated key validation in CI/CD</span>
            </div>
          </div>
        </div>
      ''');
    }

    return insights.join('\n');
  }
}

import '../reporter/reporter_v3.dart' show ReporterV3;
export '../reporter/reporter_v3.dart' show ReporterV3;

typedef Reporter = ReporterV3;

import 'dart:io';
import 'dart:convert';
import 'package:analyzer/dart/analysis/analysis_context_collection.dart';
import 'package:analyzer/dart/analysis/results.dart';
import 'package:analyzer/dart/ast/ast.dart';
import 'package:analyzer/dart/ast/visitor.dart';
import 'package:flutter_keycheck/src/config/config_v3.dart';
import 'package:flutter_keycheck/src/models/scan_result.dart';
import 'package:flutter_keycheck/src/scanner/key_detectors_v3.dart';
import 'package:flutter_keycheck/src/cache/dependency_cache.dart';
import 'package:path/path.dart' as path;

/// Package scanning scope
enum ScanScope {
  workspaceOnly('workspace-only'),
  depsOnly('deps-only'),
  all('all');

  final String value;
  const ScanScope(this.value);

  static ScanScope fromString(String value) {
    return ScanScope.values.firstWhere(
      (s) => s.value == value,
      orElse: () => ScanScope.workspaceOnly,
    );
  }
}

/// Text-based heuristics for widget and handler detection
class _Heuristics {
  final int widgetHits;
  final List<String> handlers;

  _Heuristics({required this.widgetHits, required this.handlers});
}

/// File information with source tracking
class FileInfo {
  final String path;
  final String source; // 'workspace' or 'package'
  final String? packageInfo; // 'name@version' for dependencies

  FileInfo({
    required this.path,
    this.source = 'workspace',
    this.packageInfo,
  });
}

/// Enhanced AST scanner with provable coverage
class AstScannerV3 {
  final String projectPath;
  final bool includeTests;
  final bool includeGenerated;
  final bool includeExamples;
  final String? gitDiffBase;
  final ScanScope scope;
  final String? packageFilter;
  final ConfigV3 config;

  // Built-in detectors
  late final List<KeyDetector> detectors;

  // Metrics
  final ScanMetrics metrics = ScanMetrics();
  final Map<String, FileAnalysis> fileAnalyses = {};
  final Map<String, KeyUsage> keyUsages = {};

  AstScannerV3({
    required this.projectPath,
    this.includeTests = false,
    this.includeGenerated = false,
    this.includeExamples = true,
    this.gitDiffBase,
    this.scope = ScanScope.workspaceOnly,
    this.packageFilter,
    required this.config,
  }) {
    // Initialize built-in detectors
    detectors = [
      ValueKeyDetector(),
      BasicKeyDetector(),
      ConstKeyDetector(),
      SemanticKeyDetector(),
      TestKeyDetector(),
      MaterialKeyDetector(),
      CupertinoKeyDetector(),
      IntegrationTestKeyDetector(),
      PatrolFinderDetector(),
      StringLiteralKeyDetector(),
    ];
  }

  /// Perform full AST scan with metrics
  Future<ScanResult> scan() async {
    final startTime = DateTime.now();

    // Ensure cache directory exists
    final cacheDir =
        Directory(path.join(projectPath, DependencyCache.cacheDir));
    if (!await cacheDir.exists()) {
      await cacheDir.create(recursive: true);
    }

    // Get files to scan
    final filesWithInfo = await _getFilesToScanWithInfo();
    metrics.totalFiles = filesWithInfo.length;

    // Create analysis context
    final collection = AnalysisContextCollection(
      includedPaths: [projectPath],
      excludedPaths: _getExcludedPaths(),
    );

    // Scan each file
    for (final fileInfo in filesWithInfo) {
      await _scanFile(
        fileInfo.path,
        collection,
        source: fileInfo.source,
        packageInfo: fileInfo.packageInfo,
      );
    }

    // Calculate coverage metrics
    _calculateCoverageMetrics();

    // Detect blind spots
    final blindSpots = _detectBlindSpots();

    final duration = DateTime.now().difference(startTime);

    return ScanResult(
      metrics: metrics,
      fileAnalyses: fileAnalyses,
      keyUsages: keyUsages,
      blindSpots: blindSpots,
      duration: duration,
    );
  }

  /// Get files to scan with source information
  Future<List<FileInfo>> _getFilesToScanWithInfo() async {
    if (gitDiffBase != null) {
      // Incremental scan
      final result = await Process.run(
        'git',
        ['diff', '--name-only', gitDiffBase!, '--', '*.dart'],
        workingDirectory: projectPath,
      );

      if (result.exitCode == 0) {
        final files = result.stdout
            .toString()
            .split('\n')
            .where((f) => f.isNotEmpty && f.endsWith('.dart'))
            .map((f) => FileInfo(
                  path: path.join(projectPath, f),
                  source: 'workspace',
                ))
            .toList();

        metrics.incrementalScan = true;
        metrics.incrementalBase = gitDiffBase!;
        return files;
      }
    }

    // Full scan based on scope
    switch (scope) {
      case ScanScope.depsOnly:
        return await _getDependencyFilesWithInfo();
      case ScanScope.all:
        final workspace = _getWorkspaceFilesWithInfo();
        final deps = await _getDependencyFilesWithInfo();
        return [...workspace, ...deps];
      case ScanScope.workspaceOnly:
        return _getWorkspaceFilesWithInfo();
    }
  }

  /// Get workspace files with info
  List<FileInfo> _getWorkspaceFilesWithInfo() {
    final files = <FileInfo>[];

    // Check if this is a package root (has pubspec.yaml)
    final pubspec = File(path.join(projectPath, 'pubspec.yaml'));

    // Determine which directories to scan
    final dirsToScan = <Directory>[];

    if (!pubspec.existsSync()) {
      // Not a package root - check if has local lib/
      final localLib = Directory(path.join(projectPath, 'lib'));
      if (localLib.existsSync()) {
        dirsToScan.add(localLib);
      }
    } else {
      // Standard package - scan lib/ and bin/
      final libDir = Directory(path.join(projectPath, 'lib'));
      if (libDir.existsSync()) {
        dirsToScan.add(libDir);
      }

      final binDir = Directory(path.join(projectPath, 'bin'));
      if (binDir.existsSync()) {
        dirsToScan.add(binDir);
      }

      // If includeTests is true, also scan test/
      if (includeTests) {
        final testDir = Directory(path.join(projectPath, 'test'));
        if (testDir.existsSync()) {
          dirsToScan.add(testDir);
        }
      }

      // Include example/ and examples/ directories if enabled
      if (includeExamples) {
        final exampleDir = Directory(path.join(projectPath, 'example'));
        if (exampleDir.existsSync()) {
          // Scan Flutter apps in example/
          for (final entity in exampleDir.listSync()) {
            if (entity is Directory) {
              final exampleLibDir = Directory(path.join(entity.path, 'lib'));
              if (exampleLibDir.existsSync()) {
                dirsToScan.add(exampleLibDir);
              }
              final exampleBinDir = Directory(path.join(entity.path, 'bin'));
              if (exampleBinDir.existsSync()) {
                dirsToScan.add(exampleBinDir);
              }
            }
          }
        }

        // Also check examples/ (plural)
        final examplesDir = Directory(path.join(projectPath, 'examples'));
        if (examplesDir.existsSync()) {
          for (final entity in examplesDir.listSync()) {
            if (entity is Directory) {
              final exampleLibDir = Directory(path.join(entity.path, 'lib'));
              if (exampleLibDir.existsSync()) {
                dirsToScan.add(exampleLibDir);
              }
              final exampleBinDir = Directory(path.join(entity.path, 'bin'));
              if (exampleBinDir.existsSync()) {
                dirsToScan.add(exampleBinDir);
              }
            }
          }
        }
      }
    }

    // Scan the determined directories
    for (final dir in dirsToScan) {
      for (final entity in dir.listSync(recursive: true)) {
        if (entity is File && entity.path.endsWith('.dart')) {
          final relativePath = path.relative(entity.path, from: projectPath);

          // Skip excluded directories
          if (_isExcludedPath(entity.path)) continue;

          // Apply filters
          if (!_shouldIncludeFile(relativePath)) continue;

          // Apply package filter if set
          if (packageFilter != null) {
            final pattern = RegExp(packageFilter!);
            if (!pattern.hasMatch(relativePath)) continue;
          }

          files.add(FileInfo(
            path: entity.path,
            source: 'workspace',
          ));
        }
      }
    }

    return files;
  }

  /// Check if path should be excluded
  bool _isExcludedPath(String filePath) {
    // Exclude common directories that should never be scanned
    final excludePatterns = RegExp(r'/(\.dart_tool|build|\.git)/');
    return excludePatterns.hasMatch(filePath);
  }

  /// Get dependency files with info
  Future<List<FileInfo>> _getDependencyFilesWithInfo() async {
    final files = <FileInfo>[];

    // Read package_config.json to get dependency locations
    final packageConfigFile =
        File(path.join(projectPath, '.dart_tool', 'package_config.json'));
    if (!packageConfigFile.existsSync()) {
      // Try running pub get first
      await _pubDepsJson();
      if (!packageConfigFile.existsSync()) {
        return files; // No dependencies available
      }
    }

    try {
      final packageConfig = json.decode(packageConfigFile.readAsStringSync());
      final packages = packageConfig['packages'] as List;

      for (final package in packages) {
        final packageName = package['name'] as String;
        final packageUri = package['rootUri'] as String;

        // Skip the current project itself
        if (packageUri == '../' || packageUri == '..') continue;

        // Get the actual package path
        String packagePath;
        if (packageUri.startsWith('file://')) {
          packagePath = Uri.parse(packageUri).toFilePath();
        } else if (packageUri.startsWith('../')) {
          packagePath =
              path.normalize(path.join(projectPath, '.dart_tool', packageUri));
        } else {
          packagePath = path.join(projectPath, '.dart_tool', packageUri);
        }

        // Scan lib folder of the package
        final libPath = path.join(packagePath, 'lib');
        if (Directory(libPath).existsSync()) {
          // Get package version from pubspec or use default
          final packageVersion =
              await _getPackageVersion(packagePath) ?? '0.0.0';
          final packageFullName = '$packageName@$packageVersion';

          for (final entity in Directory(libPath).listSync(recursive: true)) {
            if (entity is File && entity.path.endsWith('.dart')) {
              files.add(FileInfo(
                path: entity.path,
                source: 'package',
                packageInfo: packageFullName,
              ));
            }
          }
        }
      }
    } catch (e) {
      // If we can't parse package config, fallback to pub deps
      await _pubDepsJson();
    }

    return files;
  }

  /// Get package version from pubspec.yaml
  Future<String?> _getPackageVersion(String packagePath) async {
    try {
      final pubspecFile = File(path.join(packagePath, 'pubspec.yaml'));
      if (pubspecFile.existsSync()) {
        final content = pubspecFile.readAsStringSync();
        final versionMatch =
            RegExp(r'^version:\s*(.+)$', multiLine: true).firstMatch(content);
        if (versionMatch != null) {
          return versionMatch.group(1)?.trim();
        }
      }
    } catch (_) {}
    return null;
  }

  /// Run pub deps to get dependency information (with caching)
  Future<void> _pubDepsJson() async {
    // Check if deps cache exists and is fresh (24h TTL)
    final cacheKey =
        'deps_json_${DateTime.now().toIso8601String().substring(0, 10)}';
    final cachedResult = await DependencyCache.loadCache(projectPath, cacheKey);

    if (cachedResult != null) {
      // Cache hit - deps already fetched within 24h
      return;
    }

    try {
      // Try flutter pub deps first, fallback to dart pub deps
      ProcessResult result;
      try {
        result = await Process.run(
          'flutter',
          ['pub', 'get'],
          workingDirectory: projectPath,
        );
      } on ProcessException {
        // Flutter not available, try dart
        result = await Process.run(
          'dart',
          ['pub', 'get'],
          workingDirectory: projectPath,
        );
      }

      // Cache the result if successful
      if (result.exitCode == 0) {
        await DependencyCache.saveCache(projectPath, cacheKey, {
          'timestamp': DateTime.now().toIso8601String(),
          'command': 'pub_get',
          'exitCode': result.exitCode,
        });
      }
    } catch (e) {
      // Ignore errors - we'll work with what we have
    }
  }

  /// Check if file should be included
  bool _shouldIncludeFile(String relativePath) {
    if (!includeTests && relativePath.contains('test/')) return false;
    if (!includeGenerated && relativePath.endsWith('.g.dart')) return false;
    if (!includeGenerated && relativePath.endsWith('.freezed.dart')) {
      return false;
    }

    // Check exclude patterns from config
    for (final pattern in config.scan.excludePatterns) {
      if (_matchesPattern(relativePath, pattern)) return false;
    }

    return true;
  }

  /// Match glob pattern
  bool _matchesPattern(String path, String pattern) {
    // Simplified glob matching
    final regex = pattern
        .replaceAll('**/', '.*')
        .replaceAll('*', '[^/]*')
        .replaceAll('?', '.');
    return RegExp(regex).hasMatch(path);
  }

  /// Scan single file with AST
  Future<void> _scanFile(String filePath, AnalysisContextCollection collection,
      {String source = 'workspace', String? packageInfo}) async {
    // Try to use cache for package dependencies
    if (source == 'package' && packageInfo != null) {
      final cached = await _tryLoadFromCache(filePath, packageInfo);
      if (cached) {
        return; // Successfully loaded from cache
      }
    }

    try {
      final context = collection.contextFor(filePath);
      final result = await context.currentSession.getResolvedUnit(filePath);

      if (result is ResolvedUnitResult) {
        final analysis = FileAnalysis(
          path: filePath,
          relativePath: path.relative(filePath, from: projectPath),
        );

        // Create visitor with all detectors
        final visitor = KeyVisitorV3(
          detectors: detectors,
          analysis: analysis,
          keyUsages: keyUsages,
          filePath: filePath,
          source: source,
          packageInfo: packageInfo,
        );

        // Visit AST - use accept to properly traverse the entire tree
        result.unit.accept(visitor);

        // Store analysis
        fileAnalyses[filePath] = analysis;
        metrics.scannedFiles++;
        metrics.totalLines += _countLines(File(filePath));
        metrics.analyzedNodes += analysis.nodesAnalyzed;

        // Update detector metrics
        for (final detector in detectors) {
          metrics.detectorHits[detector.name] =
              (metrics.detectorHits[detector.name] ?? 0) +
                  (analysis.detectorHits[detector.name] ?? 0);
        }

        // Save to cache if it's a package dependency
        if (source == 'package' && packageInfo != null) {
          // Extract only the keys from this file
          final fileKeys = <String, KeyUsage>{};
          for (final entry in visitor.keyUsages.entries) {
            // Check if this key has locations in this file
            if (entry.value.locations.any((loc) => loc.file == filePath)) {
              fileKeys[entry.key] = entry.value;
            }
          }
          await _saveToCache(filePath, packageInfo, analysis, fileKeys);
        }
      }
    } catch (e) {
      // Try text-based heuristics as fallback
      try {
        final file = File(filePath);
        if (file.existsSync()) {
          final content = file.readAsStringSync();
          final heuristics = _scanTextHeuristics(content);

          // Create basic analysis with heuristics
          final analysis = FileAnalysis(
            path: filePath,
            relativePath: path.relative(filePath, from: projectPath),
          );

          // Use heuristics for metrics
          analysis.widgetCount = heuristics.widgetHits;
          if (heuristics.widgetHits > 0) {
            analysis.widgetsWithKeys = 1; // Conservative estimate
          }

          // ENHANCED: Add regex-based key detection as fallback
          _extractKeysFromText(content, analysis);

          // Store basic metrics
          fileAnalyses[filePath] = analysis;
          metrics.scannedFiles++;
          metrics.totalLines += _countLines(file);

          // Handler information is captured in heuristics but not stored in metrics
        }
      } catch (_) {
        // If even text scanning fails, record error
        metrics.errors.add(ScanError(
          file: filePath,
          error: e.toString(),
          type: 'ast_parse',
        ));
      }
    }
  }

  /// Calculate coverage metrics
  void _calculateCoverageMetrics() {
    // File coverage
    metrics.fileCoverage = metrics.totalFiles > 0
        ? (metrics.scannedFiles / metrics.totalFiles * 100)
        : 0;

    // Widget coverage
    int totalWidgets = 0;
    int widgetsWithKeys = 0;

    for (final analysis in fileAnalyses.values) {
      totalWidgets += analysis.widgetCount;
      widgetsWithKeys += analysis.widgetsWithKeys;
    }

    metrics.widgetCoverage =
        totalWidgets > 0 ? (widgetsWithKeys / totalWidgets * 100) : 0;

    // Handler coverage
    int totalHandlers = 0;
    int handlersWithKeys = 0;

    for (final usage in keyUsages.values) {
      if (usage.handlers.isNotEmpty) {
        handlersWithKeys++;
      }
      totalHandlers++;
    }

    metrics.handlerCoverage =
        totalHandlers > 0 ? (handlersWithKeys / totalHandlers * 100) : 0;
  }

  /// Detect blind spots
  List<BlindSpot> _detectBlindSpots() {
    final blindSpots = <BlindSpot>[];

    // Check for files with no keys
    for (final entry in fileAnalyses.entries) {
      if (entry.value.keysFound.isEmpty && entry.value.widgetCount > 5) {
        blindSpots.add(BlindSpot(
          type: 'no_keys_in_ui_heavy_file',
          location: entry.key,
          severity: 'warning',
          message: 'File has ${entry.value.widgetCount} widgets but no keys',
        ));
      }
    }

    // Check detector effectiveness
    for (final entry in metrics.detectorHits.entries) {
      if (entry.value == 0) {
        blindSpots.add(BlindSpot(
          type: 'ineffective_detector',
          location: 'detector:${entry.key}',
          severity: 'info',
          message: 'Detector "${entry.key}" found no matches',
        ));
      }
    }

    return blindSpots;
  }

  List<String> _getExcludedPaths() {
    final excluded = <String>[];
    if (!includeTests) {
      final testPath = path.join(projectPath, 'test');
      if (Directory(testPath).existsSync()) {
        excluded.add(testPath);
      }
    }
    // Note: AnalysisContextCollection doesn't support glob patterns in excludedPaths
    // We'll filter generated files in _shouldIncludeFile instead
    return excluded;
  }

  int _countLines(File file) {
    try {
      return file.readAsLinesSync().length;
    } catch (_) {
      return 0;
    }
  }

  /// Extract keys from text using regex patterns (fallback when AST parsing fails)
  void _extractKeysFromText(String content, FileAnalysis analysis) {
    // Regex patterns for various key formats
    final patterns = [
      RegExp(r"const\s+ValueKey\s*\(\s*'([^']+)'"), // const ValueKey('key')
      RegExp(
          r"key:\s*const\s+ValueKey\s*\(\s*'([^']+)'"), // key: const ValueKey('key')
      RegExp(
          r"=\s*const\s+ValueKey\s*\(\s*'([^']+)'"), // = const ValueKey('key')
      RegExp(r"ValueKey\s*\(\s*'([^']+)'"), // ValueKey('key')
      RegExp(r"Key\s*\(\s*'([^']+)'"), // Key('key')
    ];

    for (final pattern in patterns) {
      final matches = pattern.allMatches(content);
      for (final match in matches) {
        final keyValue = match.group(1);
        if (keyValue != null && keyValue.isNotEmpty) {
          analysis.keysFound.add(keyValue);
          analysis.detectorHits['StringLiteral'] =
              (analysis.detectorHits['StringLiteral'] ?? 0) + 1;

          // Create a key usage for tracking
          final usage = keyUsages.putIfAbsent(
            keyValue,
            () => KeyUsage(
              id: keyValue,
              source: 'workspace',
            ),
          );

          // Add location info (approximate)
          final lineNumber =
              content.substring(0, match.start).split('\n').length;

          // Extract code context around the found key
          final lines = content.split('\n');
          final currentLineIndex = lineNumber - 1;
          final startLine = (currentLineIndex - 2).clamp(0, lines.length - 1);
          final endLine = (currentLineIndex + 2).clamp(0, lines.length - 1);

          final contextLines = <String>[];
          for (int i = startLine; i <= endLine; i++) {
            if (i < lines.length) {
              contextLines.add(lines[i]);
            }
          }
          final codeContext = contextLines.join('\n');

          usage.locations.add(KeyLocation(
            file: analysis.path,
            line: lineNumber,
            column: match.start - content.lastIndexOf('\n', match.start),
            detector: 'StringLiteral',
            context: codeContext,
          ));
        }
      }
    }
  }

  /// Scan text heuristics for metrics when AST parsing fails
  _Heuristics _scanTextHeuristics(String content) {
    final widgetHits = RegExp(
            r'\b(StatefulWidget|StatelessWidget|Widget|MaterialApp|CupertinoApp|Scaffold|AppBar|Container|Column|Row|ListView|GridView|Stack|Card|Button|TextField|Text|Image)\b')
        .allMatches(content)
        .length;

    final handlerNames = <String>{
      'onPressed',
      'onTap',
      'onChanged',
      'onLongPress',
      'onSubmitted',
      'onSave',
      'onSelect',
      'onDoubleTap',
      'onPanUpdate',
      'onHorizontalDragEnd',
      'onVerticalDragEnd',
      'onScaleEnd',
      'onEditingComplete',
      'onFieldSubmitted'
    };

    final handlers = <String>[];
    for (final h in handlerNames) {
      if (content.contains(h)) {
        handlers.add(h);
      }
    }

    return _Heuristics(widgetHits: widgetHits, handlers: handlers);
  }

  /// Try to load scan results from cache
  Future<bool> _tryLoadFromCache(String filePath, String packageInfo) async {
    try {
      final parts = packageInfo.split('@');
      if (parts.length != 2) return false;

      final packageName = parts[0];
      final packageVersion = parts[1];

      final cacheKey = DependencyCache.getCacheKey(
        packageName: packageName,
        packageVersion: packageVersion,
        detectorHash: DependencyCache.getDetectorHash(),
        sdkVersion: DependencyCache.getSdkVersion(),
      );

      final cached = await DependencyCache.loadCache(projectPath, cacheKey);
      if (cached == null) return false;

      // Check if this file is in the cache
      final fileKey = path.relative(filePath, from: projectPath);
      final fileData = cached[fileKey] as Map<String, dynamic>?;
      if (fileData == null) return false;

      // Restore analysis
      final analysis = FileAnalysis(
        path: filePath,
        relativePath: path.relative(filePath, from: projectPath),
      );

      // Restore metrics from cache
      analysis.widgetCount = fileData['widgetCount'] ?? 0;
      analysis.widgetsWithKeys = fileData['widgetsWithKeys'] ?? 0;
      analysis.nodesAnalyzed = fileData['nodesAnalyzed'] ?? 0;

      // Restore keys found
      final keysFound = fileData['keysFound'] as List?;
      if (keysFound != null) {
        for (final key in keysFound) {
          analysis.keysFound.add(key as String);
        }
      }

      // Store analysis
      fileAnalyses[filePath] = analysis;
      metrics.scannedFiles++;
      metrics.totalLines += (fileData['totalLines'] ?? 0) as int;
      metrics.analyzedNodes += analysis.nodesAnalyzed;

      // Restore key usages
      final usages = fileData['keyUsages'] as Map<String, dynamic>?;
      if (usages != null) {
        for (final entry in usages.entries) {
          final usageData = entry.value as Map<String, dynamic>;
          final usage = keyUsages.putIfAbsent(
            entry.key,
            () => KeyUsage(
              id: entry.key,
              source: usageData['source'] ?? 'package',
              package: packageInfo,
            ),
          );

          // Restore locations
          final locations = usageData['locations'] as List?;
          if (locations != null) {
            for (final locData in locations) {
              usage.locations
                  .add(KeyLocation.fromMap(locData as Map<String, dynamic>));
            }
          }

          // Restore handlers
          final handlers = usageData['handlers'] as List?;
          if (handlers != null) {
            for (final handlerData in handlers) {
              usage.handlers.add(
                  HandlerInfo.fromMap(handlerData as Map<String, dynamic>));
            }
          }

          // Restore tags
          final tags = usageData['tags'] as List?;
          if (tags != null) {
            usage.tags.addAll(tags.cast<String>());
          }
        }
      }

      return true;
    } catch (e) {
      // Cache load failed, continue with normal scan
      return false;
    }
  }

  /// Save scan results to cache
  Future<void> _saveToCache(
    String filePath,
    String packageInfo,
    FileAnalysis analysis,
    Map<String, KeyUsage> fileKeyUsages,
  ) async {
    try {
      final parts = packageInfo.split('@');
      if (parts.length != 2) return;

      final packageName = parts[0];
      final packageVersion = parts[1];

      final cacheKey = DependencyCache.getCacheKey(
        packageName: packageName,
        packageVersion: packageVersion,
        detectorHash: DependencyCache.getDetectorHash(),
        sdkVersion: DependencyCache.getSdkVersion(),
      );

      // Load existing cache or create new
      final existing =
          await DependencyCache.loadCache(projectPath, cacheKey) ?? {};

      // Add this file's data
      final fileKey = path.relative(filePath, from: projectPath);
      existing[fileKey] = {
        'widgetCount': analysis.widgetCount,
        'widgetsWithKeys': analysis.widgetsWithKeys,
        'nodesAnalyzed': analysis.nodesAnalyzed,
        'keysFound': analysis.keysFound.toList(),
        'totalLines': _countLines(File(filePath)),
        'keyUsages': fileKeyUsages.map((key, usage) => MapEntry(key, {
              'locations': usage.locations.map((loc) => loc.toMap()).toList(),
              'handlers': usage.handlers.map((h) => h.toMap()).toList(),
              'tags': usage.tags.toList(),
              'source': usage.source,
              'status': usage.status,
              'notes': usage.notes,
            })),
      };

      // Save cache
      await DependencyCache.saveCache(projectPath, cacheKey, existing);
    } catch (e) {
      // Cache save failed, ignore silently
    }
  }
}

/// Enhanced AST visitor for v3
class KeyVisitorV3 extends RecursiveAstVisitor<void> {
  final List<KeyDetector> detectors;
  final FileAnalysis analysis;
  final Map<String, KeyUsage> keyUsages;
  final String filePath;
  final String source;
  final String? packageInfo;

  KeyVisitorV3({
    required this.detectors,
    required this.analysis,
    required this.keyUsages,
    required this.filePath,
    this.source = 'workspace',
    this.packageInfo,
  });

  @override
  void visitClassDeclaration(ClassDeclaration node) {
    // Make sure we visit the class body
    super.visitClassDeclaration(node);
  }

  @override
  void visitMethodDeclaration(MethodDeclaration node) {
    // Make sure we visit the method body
    super.visitMethodDeclaration(node);
  }

  @override
  void visitFunctionDeclaration(FunctionDeclaration node) {
    // Also handle top-level functions
    super.visitFunctionDeclaration(node);
  }

  @override
  void visitMethodInvocation(MethodInvocation node) {
    analysis.nodesAnalyzed++;

    // Check if this might be a widget constructor (when Flutter types aren't resolved)
    final methodName = node.methodName.name;

    // Special handling for Semantics widget
    if (methodName == 'Semantics' && node.target == null) {
      analysis.widgetCount++;
      analysis.widgetTypes.add(methodName);

      // Semantics uses 'identifier' parameter instead of 'key'
      for (final arg in node.argumentList.arguments) {
        if (arg is NamedExpression && arg.name.label.name == 'identifier') {
          final value = arg.expression;
          if (value is StringLiteral) {
            final result = DetectionResult(
              key: value.stringValue ?? '',
              detector: 'Semantics',
              tags: ['semantic', 'accessibility'],
            );
            _recordKey(result.key, node,
                detectors.firstWhere((d) => d.name == 'Semantics'), result);
            analysis.widgetsWithKeys++;
          }
        }
      }
    } else if (_isWidget(methodName) && node.target == null) {
      // This is likely a widget constructor being parsed as a method
      analysis.widgetCount++;
      analysis.widgetTypes.add(methodName);

      // Check for key parameter
      NamedExpression? keyArg;
      try {
        keyArg = node.argumentList.arguments
            .whereType<NamedExpression>()
            .firstWhere((arg) => arg.name.label.name == 'key');
      } catch (_) {
        keyArg = null;
      }

      if (keyArg != null) {
        analysis.widgetsWithKeys++;

        // Extract key value using detectors
        for (final detector in detectors) {
          final result = detector.detectExpression(keyArg.expression);
          if (result != null) {
            _recordKey(result.key, node, detector, result);
            break;
          }
        }

        // Check for handlers in this widget
        _checkMethodInvocationHandlers(node);
      } else {
        analysis.uncoveredWidgetTypes.add(methodName);
      }
    }

    // Check each detector for regular method invocations (like ValueKey)
    for (final detector in detectors) {
      final result = detector.detect(node);
      if (result != null) {
        _recordKey(result.key, node, detector, result);
      }
    }

    // Check for action handlers
    _checkActionHandler(node);

    // Call super to continue visiting
    super.visitMethodInvocation(node);
  }

  @override
  void visitInstanceCreationExpression(InstanceCreationExpression node) {
    analysis.nodesAnalyzed++;

    // Track widget creation
    final typeName = node.constructorName.type.toString();

    if (_isWidget(typeName)) {
      analysis.widgetCount++;
      analysis.widgetTypes.add(typeName);

      // Check for key parameter
      final keyArgs = node.argumentList.arguments
          .whereType<NamedExpression>()
          .where((arg) => arg.name.label.name == 'key')
          .toList();
      final keyArg = keyArgs.isNotEmpty ? keyArgs.first : null;

      if (keyArg != null) {
        analysis.widgetsWithKeys++;

        // Extract key value using detectors
        for (final detector in detectors) {
          final result = detector.detectExpression(keyArg.expression);
          if (result != null) {
            _recordKey(result.key, node, detector, result);
            break; // Found a key, stop checking other detectors
          }
        }
      } else {
        analysis.uncoveredWidgetTypes.add(typeName);
      }

      // Check for handlers in this widget
      _checkWidgetHandlers(node);
    }

    // Also check for Semantics widget specifically
    if (typeName == 'Semantics') {
      _checkSemanticsWidget(node);
    }

    // Also check for ValueKey/Key creation independently of widget context
    if (typeName == 'ValueKey' || typeName == 'Key') {
      for (final detector in detectors) {
        final result = detector.detectExpression(node);
        if (result != null) {
          _recordKey(result.key, node, detector, result);
          break;
        }
      }
    }

    // Call super to continue visiting children
    super.visitInstanceCreationExpression(node);
  }

  @override
  void visitVariableDeclaration(VariableDeclaration node) {
    analysis.nodesAnalyzed++;

    // Check if variable is initialized with a widget that has keys
    final initializer = node.initializer;
    if (initializer is InstanceCreationExpression) {
      final typeName = initializer.constructorName.type.toString();

      if (_isWidget(typeName)) {
        analysis.widgetCount++;
        analysis.widgetTypes.add(typeName);

        // Check for key parameter
        final keyArgs = initializer.argumentList.arguments
            .whereType<NamedExpression>()
            .where((arg) => arg.name.label.name == 'key')
            .toList();
        final keyArg = keyArgs.isNotEmpty ? keyArgs.first : null;

        if (keyArg != null) {
          analysis.widgetsWithKeys++;

          // Extract key value using detectors
          for (final detector in detectors) {
            final result = detector.detectExpression(keyArg.expression);
            if (result != null) {
              _recordKey(result.key, initializer, detector, result);
              break;
            }
          }
        } else {
          analysis.uncoveredWidgetTypes.add(typeName);
        }
      }
      // ENHANCED: Check for direct Key/ValueKey assignments like "final Key? key = const ValueKey('...')"
      else if (typeName == 'ValueKey' || typeName == 'Key') {
        // Check if this variable is named 'key'
        if (node.name.lexeme == 'key') {
          // Extract key value using detectors
          for (final detector in detectors) {
            final result = detector.detectExpression(initializer);
            if (result != null) {
              _recordKey(result.key, initializer, detector, result);
              break;
            }
          }
        }
      }
    }

    super.visitVariableDeclaration(node);
  }

  void _recordKey(
      String key, AstNode node, KeyDetector detector, DetectionResult result) {
    // Record in file analysis
    analysis.keysFound.add(key);
    analysis.detectorHits[detector.name] =
        (analysis.detectorHits[detector.name] ?? 0) + 1;

    // Get location info
    final lineInfo = (node.root as CompilationUnit).lineInfo;
    final location = lineInfo.getLocation(node.offset);

    // Create or update key usage
    final usage = keyUsages.putIfAbsent(
      key,
      () => KeyUsage(
        id: key,
        source: source,
        package: packageInfo,
      ),
    );

    usage.locations.add(KeyLocation(
      file: filePath,
      line: location.lineNumber,
      column: location.columnNumber,
      detector: detector.name,
      context: _getContext(node),
    ));

    // Add tags from detector
    if (result.tags != null) {
      usage.tags.addAll(result.tags!);
    }
  }

  void _checkActionHandler(MethodInvocation node) {
    final methodName = node.methodName.name;
    final actionPatterns = ['onPressed', 'onTap', 'onSubmit', 'onChanged'];

    if (actionPatterns.contains(methodName)) {
      // Find associated key in parent widget
      AstNode? current = node.parent;
      while (current != null) {
        if (current is InstanceCreationExpression) {
          final keyArgs = current.argumentList.arguments
              .whereType<NamedExpression>()
              .where((arg) => arg.name.label.name == 'key')
              .toList();
          final keyArg = keyArgs.isNotEmpty ? keyArgs.first : null;

          if (keyArg != null) {
            for (final detector in detectors) {
              final result = detector.detectExpression(keyArg.expression);
              if (result != null) {
                final usage = keyUsages[result.key];
                if (usage != null) {
                  usage.handlers.add(HandlerInfo(
                    type: methodName,
                    method: _extractHandlerMethod(node),
                    file: filePath,
                    line: node.offset,
                  ));
                }
                break;
              }
            }
          }
          break;
        }
        current = current.parent;
      }
    }
  }

  void _checkMethodInvocationHandlers(MethodInvocation node) {
    // Check for handlers in named arguments (for widgets parsed as methods)
    final handlerPatterns = [
      'onPressed',
      'onTap',
      'onSubmitted',
      'onChanged',
      'onLongPress',
      'onSaved',
      'onSelected',
      'onDoubleTap'
    ];

    String? widgetKey;
    // First, find if this widget has a key
    NamedExpression? keyArg;
    try {
      keyArg = node.argumentList.arguments
          .whereType<NamedExpression>()
          .firstWhere((arg) => arg.name.label.name == 'key');
    } catch (_) {
      keyArg = null;
    }

    if (keyArg != null) {
      for (final detector in detectors) {
        final result = detector.detectExpression(keyArg.expression);
        if (result != null) {
          widgetKey = result.key;
          break;
        }
      }
    }

    // If widget has a key, check for handlers
    if (widgetKey != null) {
      for (final arg in node.argumentList.arguments) {
        if (arg is NamedExpression) {
          final name = arg.name.label.name;
          if (handlerPatterns.contains(name)) {
            final usage = keyUsages[widgetKey];
            if (usage != null) {
              usage.handlers.add(HandlerInfo(
                type: name,
                method: _extractHandlerFromExpression(arg.expression),
                file: filePath,
                line: arg.offset,
              ));
            }
          }
        }
      }
    }
  }

  void _checkWidgetHandlers(InstanceCreationExpression node) {
    // Check for handlers in named arguments
    final handlerPatterns = [
      'onPressed',
      'onTap',
      'onSubmitted',
      'onChanged',
      'onLongPress',
      'onSaved',
      'onSelected',
      'onDoubleTap'
    ];

    String? widgetKey;
    // First, find if this widget has a key
    final keyArgs = node.argumentList.arguments
        .whereType<NamedExpression>()
        .where((arg) => arg.name.label.name == 'key')
        .toList();
    final keyArg = keyArgs.isNotEmpty ? keyArgs.first : null;

    if (keyArg != null) {
      for (final detector in detectors) {
        final result = detector.detectExpression(keyArg.expression);
        if (result != null) {
          widgetKey = result.key;
          break;
        }
      }
    }

    // If widget has a key, check for handlers
    if (widgetKey != null) {
      for (final arg in node.argumentList.arguments) {
        if (arg is NamedExpression) {
          final name = arg.name.label.name;
          if (handlerPatterns.contains(name)) {
            final usage = keyUsages[widgetKey];
            if (usage != null) {
              usage.handlers.add(HandlerInfo(
                type: name,
                method: _extractHandlerFromExpression(arg.expression),
                file: filePath,
                line: arg.offset,
              ));
            }
          }
        }
      }
    }
  }

  void _checkSemanticsWidget(InstanceCreationExpression node) {
    // Check for Semantics widget with identifier
    for (final arg in node.argumentList.arguments) {
      if (arg is NamedExpression && arg.name.label.name == 'identifier') {
        final value = arg.expression;
        if (value is StringLiteral) {
          final result = DetectionResult(
            key: value.stringValue ?? '',
            detector: 'Semantics',
            tags: ['semantic', 'accessibility'],
          );
          _recordKey(result.key, node,
              detectors.firstWhere((d) => d.name == 'Semantics'), result);
        }
      }
    }
  }

  String? _extractHandlerFromExpression(Expression expression) {
    if (expression is SimpleIdentifier) {
      return expression.name;
    }
    if (expression is FunctionExpression) {
      return '<anonymous>';
    }
    if (expression is MethodInvocation) {
      return expression.methodName.name;
    }
    return null;
  }

  String _getContext(AstNode node) {
    AstNode? current = node.parent;
    while (current != null) {
      if (current is MethodDeclaration) {
        return 'method:${current.name.lexeme}';
      }
      if (current is FunctionDeclaration) {
        return 'function:${current.name.lexeme}';
      }
      if (current is ClassDeclaration) {
        return 'class:${current.name.lexeme}';
      }
      current = current.parent;
    }
    return 'global';
  }

  String? _extractHandlerMethod(MethodInvocation node) {
    final args = node.argumentList.arguments ?? [];
    final arg = args.isNotEmpty ? args.first : null;
    if (arg is SimpleIdentifier) {
      return arg.name;
    }
    if (arg is FunctionExpression) {
      return '<anonymous>';
    }
    return null;
  }

  bool _isWidget(String typeName) {
    return typeName.endsWith('Widget') ||
        typeName.endsWith('Button') ||
        typeName.endsWith('Field') ||
        typeName.endsWith('View') ||
        typeName.endsWith('Screen') ||
        typeName.endsWith('Page') ||
        typeName.endsWith('Dialog') ||
        typeName.endsWith('Card') ||
        [
          'Column',
          'Row',
          'Stack',
          'Scaffold',
          'AppBar',
          'Center',
          'Padding',
          'Expanded',
          'ListView',
          'GridView',
          'Container',
          'Text',
          'Image',
          'Icon',
          'MaterialApp',
          'CupertinoApp',
          'Semantics',
          'ElevatedButton',
          'TextButton',
          'IconButton',
          'OutlinedButton'
        ].contains(typeName);
  }
}

import 'dart:io';
import 'package:analyzer/dart/analysis/analysis_context_collection.dart';
import 'package:analyzer/dart/analysis/results.dart';
import 'package:analyzer/dart/ast/ast.dart';
import 'package:analyzer/dart/ast/visitor.dart';
import 'package:analyzer/dart/element/element.dart';
import 'package:path/path.dart' as path;

/// AST-based scanner with full coverage metrics
class AstScanner {
  final String projectPath;
  final List<KeyDetector> detectors;
  final bool includeTests;
  final bool includeGenerated;
  final String? gitDiffBase;

  // Metrics
  final ScanMetrics metrics = ScanMetrics();
  final Map<String, FileAnalysis> fileAnalyses = {};
  final Map<String, KeyUsage> keyUsages = {};

  AstScanner({
    required this.projectPath,
    required this.detectors,
    this.includeTests = false,
    this.includeGenerated = false,
    this.gitDiffBase,
  });

  /// Perform full AST scan with metrics
  Future<ScanResult> scan() async {
    final startTime = DateTime.now();

    // Get files to scan (incremental if git-diff provided)
    final files = await _getFilesToScan();
    metrics.totalFiles = files.length;

    // Create analysis context
    final collection = AnalysisContextCollection(
      includedPaths: [projectPath],
      excludedPaths: _getExcludedPaths(),
    );

    // Scan each file
    for (final filePath in files) {
      await _scanFile(filePath, collection);
    }

    // Calculate coverage metrics
    _calculateCoverageMetrics();

    // Detect blind spots
    final blindSpots = _detectBlindSpots();

    final duration = DateTime.now().difference(startTime);

    return ScanResult(
      metrics: metrics,
      fileAnalyses: fileAnalyses,
      keyUsages: keyUsages,
      blindSpots: blindSpots,
      duration: duration,
    );
  }

  /// Get files to scan (with incremental support)
  Future<List<String>> _getFilesToScan() async {
    if (gitDiffBase != null) {
      // Incremental scan based on git diff
      final result = await Process.run(
        'git',
        ['diff', '--name-only', gitDiffBase!, '--', '*.dart'],
        workingDirectory: projectPath,
      );

      if (result.exitCode == 0) {
        final files = result.stdout
            .toString()
            .split('\n')
            .where((f) => f.isNotEmpty && f.endsWith('.dart'))
            .map((f) => path.join(projectPath, f))
            .toList();

        metrics.incrementalScan = true;
        metrics.incrementalBase = gitDiffBase!;
        return files;
      }
    }

    // Full scan
    return _getAllDartFiles();
  }

  /// Get all Dart files in project
  List<String> _getAllDartFiles() {
    final files = <String>[];
    final dir = Directory(projectPath);

    for (final entity in dir.listSync(recursive: true)) {
      if (entity is File && entity.path.endsWith('.dart')) {
        final relativePath = path.relative(entity.path, from: projectPath);

        // Apply filters
        if (!includeTests && relativePath.contains('test/')) continue;
        if (!includeGenerated && relativePath.endsWith('.g.dart')) continue;
        if (!includeGenerated && relativePath.endsWith('.freezed.dart')) {
          continue;
        }

        files.add(entity.path);
      }
    }

    return files;
  }

  /// Scan single file with AST
  Future<void> _scanFile(
      String filePath, AnalysisContextCollection collection) async {
    try {
      final context = collection.contextFor(filePath);
      final result = await context.currentSession.getResolvedUnit(filePath);

      if (result is ResolvedUnitResult) {
        final analysis = FileAnalysis(
          path: filePath,
          relativePath: path.relative(filePath, from: projectPath),
        );

        // Create visitor with all detectors
        final visitor = KeyVisitor(
          detectors: detectors,
          analysis: analysis,
          keyUsages: keyUsages,
          filePath: filePath,
        );

        // Visit AST
        result.unit.accept(visitor);

        // Store analysis
        fileAnalyses[filePath] = analysis;
        metrics.scannedFiles++;
        metrics.totalLines += _countLines(File(filePath));
        metrics.analyzedNodes += analysis.nodesAnalyzed;

        // Update detector metrics
        for (final detector in detectors) {
          metrics.detectorHits[detector.name] =
              (metrics.detectorHits[detector.name] ?? 0) +
                  analysis.detectorHits[detector.name]!;
        }
      }
    } catch (e) {
      metrics.errors.add(ScanError(
        file: filePath,
        error: e.toString(),
        type: 'ast_parse',
      ));
    }
  }

  /// Calculate coverage metrics
  void _calculateCoverageMetrics() {
    // File coverage
    metrics.fileCoverage = (metrics.scannedFiles / metrics.totalFiles * 100);

    // Widget coverage
    int totalWidgets = 0;
    int widgetsWithKeys = 0;

    for (final analysis in fileAnalyses.values) {
      totalWidgets += analysis.widgetCount;
      widgetsWithKeys += analysis.widgetsWithKeys;
    }

    metrics.widgetCoverage =
        totalWidgets > 0 ? (widgetsWithKeys / totalWidgets * 100) : 0;

    // Action handler coverage
    int totalHandlers = 0;
    int handlersWithKeys = 0;

    for (final usage in keyUsages.values) {
      if (usage.handlers.isNotEmpty) {
        handlersWithKeys++;
      }
      totalHandlers++;
    }

    metrics.handlerCoverage =
        totalHandlers > 0 ? (handlersWithKeys / totalHandlers * 100) : 0;
  }

  /// Detect blind spots in scanning
  List<BlindSpot> _detectBlindSpots() {
    final blindSpots = <BlindSpot>[];

    // Check for files with no keys detected
    for (final entry in fileAnalyses.entries) {
      if (entry.value.keysFound.isEmpty && entry.value.widgetCount > 5) {
        blindSpots.add(BlindSpot(
          type: 'no_keys_in_ui_heavy_file',
          location: entry.key,
          severity: 'warning',
          message: 'File has ${entry.value.widgetCount} widgets but no keys',
        ));
      }
    }

    // Check for uncovered widget types
    final uncoveredWidgets = <String>{};
    for (final analysis in fileAnalyses.values) {
      uncoveredWidgets.addAll(analysis.uncoveredWidgetTypes);
    }

    if (uncoveredWidgets.isNotEmpty) {
      blindSpots.add(BlindSpot(
        type: 'uncovered_widget_types',
        location: 'global',
        severity: 'info',
        message:
            'Widget types without key detection: ${uncoveredWidgets.join(', ')}',
      ));
    }

    // Check for detector effectiveness
    for (final entry in metrics.detectorHits.entries) {
      if (entry.value == 0) {
        blindSpots.add(BlindSpot(
          type: 'ineffective_detector',
          location: 'detector:${entry.key}',
          severity: 'warning',
          message: 'Detector "${entry.key}" found no matches',
        ));
      }
    }

    return blindSpots;
  }

  List<String> _getExcludedPaths() {
    final excluded = <String>[];
    if (!includeTests) excluded.add('test/');
    if (!includeGenerated) {
      excluded.add('**.g.dart');
      excluded.add('**.freezed.dart');
    }
    return excluded;
  }

  int _countLines(File file) {
    return file.readAsLinesSync().length;
  }
}

/// AST visitor for finding keys
class KeyVisitor extends RecursiveAstVisitor<void> {
  final List<KeyDetector> detectors;
  final FileAnalysis analysis;
  final Map<String, KeyUsage> keyUsages;
  final String filePath;

  KeyVisitor({
    required this.detectors,
    required this.analysis,
    required this.keyUsages,
    required this.filePath,
  });

  @override
  void visitMethodInvocation(MethodInvocation node) {
    analysis.nodesAnalyzed++;

    // Check each detector
    for (final detector in detectors) {
      if (detector.matches(node)) {
        final key = detector.extractKey(node);
        if (key != null) {
          _recordKey(key, node, detector);
        }
      }
    }

    // Check for action handlers
    _checkActionHandler(node);

    super.visitMethodInvocation(node);
  }

  @override
  void visitInstanceCreationExpression(InstanceCreationExpression node) {
    analysis.nodesAnalyzed++;

    // Track widget creation
    final typeName = node.constructorName.type.name;
    if (typeName is PrefixedIdentifier) {
      analysis.widgetTypes.add(typeName.identifier.name);
    } else if (typeName is SimpleIdentifier) {
      analysis.widgetTypes.add(typeName.name);

      // Check if it's a widget
      if (_isWidget(typeName.name)) {
        analysis.widgetCount++;

        // Check for key parameter
        final keyArgs = node.argumentList.arguments.whereType<NamedExpression>()
            .where((arg) => arg.name.label.name == 'key').toList();
        final keyArg = keyArgs.isNotEmpty ? keyArgs.first : null;

        if (keyArg != null) {
          analysis.widgetsWithKeys++;

          // Extract key value
          for (final detector in detectors) {
            if (detector.matchesExpression(keyArg.expression)) {
              final key = detector.extractFromExpression(keyArg.expression);
              if (key != null) {
                _recordKey(key, node, detector);
                break;
              }
            }
          }
        }
      }
    }

    super.visitInstanceCreationExpression(node);
  }

  @override
  void visitFunctionDeclaration(FunctionDeclaration node) {
    analysis.nodesAnalyzed++;
    analysis.functions.add(node.name.lexeme);
    super.visitFunctionDeclaration(node);
  }

  @override
  void visitMethodDeclaration(MethodDeclaration node) {
    analysis.nodesAnalyzed++;
    analysis.methods.add(node.name.lexeme);
    super.visitMethodDeclaration(node);
  }

  void _recordKey(String key, AstNode node, KeyDetector detector) {
    // Record in file analysis
    analysis.keysFound.add(key);
    analysis.detectorHits[detector.name] =
        (analysis.detectorHits[detector.name] ?? 0) + 1;

    // Get location info
    final lineInfo = (node.root as CompilationUnit?)?.lineInfo;
    final location = lineInfo?.getLocation(node.offset);

    // Create or update key usage
    final usage = keyUsages.putIfAbsent(
      key,
      () => KeyUsage(id: key),
    );

    usage.locations.add(KeyLocation(
      file: filePath,
      line: location?.lineNumber ?? 0,
      column: location?.columnNumber ?? 0,
      detector: detector.name,
      context: _getContext(node),
    ));
  }

  void _checkActionHandler(MethodInvocation node) {
    // Check for common action patterns
    final methodName = node.methodName.name;
    final actionPatterns = ['onPressed', 'onTap', 'onSubmit', 'onChanged'];

    if (actionPatterns.contains(methodName)) {
      // Find associated key
      final parent = node.parent;
      if (parent is ArgumentList) {
        final widget = parent.parent;
        if (widget is InstanceCreationExpression) {
          // Look for key in same widget
          final keyArgs = widget.argumentList.arguments
              .whereType<NamedExpression>()
              .where((arg) => arg.name.label.name == 'key')
              .toList();
          final keyArg = keyArgs.isNotEmpty ? keyArgs.first : null;

          if (keyArg != null) {
            // Extract key and link to handler
            for (final detector in detectors) {
              if (detector.matchesExpression(keyArg.expression)) {
                final key = detector.extractFromExpression(keyArg.expression);
                if (key != null) {
                  final usage = keyUsages[key];
                  if (usage != null) {
                    usage.handlers.add(HandlerInfo(
                      type: methodName,
                      method: _extractHandlerMethod(node),
                      file: filePath,
                      line: node.offset,
                    ));
                  }
                  break;
                }
              }
            }
          }
        }
      }
    }
  }

  String _getContext(AstNode node) {
    // Get surrounding context (widget name, method, etc.)
    AstNode? current = node.parent;
    while (current != null) {
      if (current is MethodDeclaration) {
        return 'method:${current.name.lexeme}';
      }
      if (current is FunctionDeclaration) {
        return 'function:${current.name.lexeme}';
      }
      if (current is ClassDeclaration) {
        return 'class:${current.name.lexeme}';
      }
      current = current.parent;
    }
    return 'global';
  }

  String? _extractHandlerMethod(MethodInvocation node) {
    // Extract the handler method name
    final args = node.argumentList.arguments ?? [];
    final arg = args.isNotEmpty ? args.first : null;
    if (arg is SimpleIdentifier) {
      return arg.name;
    }
    if (arg is FunctionExpression) {
      return '<anonymous>';
    }
    return null;
  }

  bool _isWidget(String typeName) {
    // Common Flutter widget suffixes and names
    return typeName.endsWith('Widget') ||
        typeName.endsWith('Button') ||
        typeName.endsWith('Field') ||
        typeName.endsWith('View') ||
        typeName.endsWith('Screen') ||
        typeName.endsWith('Page') ||
        typeName.endsWith('Dialog') ||
        typeName.endsWith('Card') ||
        typeName.endsWith('List') ||
        typeName.endsWith('Grid') ||
        typeName.endsWith('Container') ||
        typeName.endsWith('Box') ||
        typeName.endsWith('Text') ||
        typeName.endsWith('Image') ||
        typeName.endsWith('Icon') ||
        [
          'Column',
          'Row',
          'Stack',
          'Scaffold',
          'AppBar',
          'Center',
          'Padding',
          'Expanded',
          'Flexible',
          'ListView',
          'GridView'
        ].contains(typeName);
  }
}

/// Models for scan results
