                key: keyArg.stringValue ?? '',
                detector: name,
                tags: ['test', 'e2e'],
              );
            }
          }
        }
      }
    }
    return null;
  }

  @override
  DetectionResult? detectExpression(Expression expression) {
    if (expression is MethodInvocation) {
      return detect(expression);
    }
    return null;
  }
}

