    return null;
  }

  @override
  DetectionResult? detectExpression(Expression expression) {
    if (expression is InstanceCreationExpression) {
      final typeName = expression.constructorName.type.toString();
      if (typeName == 'ValueKey' || typeName == 'Key') {
        final arg = expression.argumentList.arguments.isNotEmpty
            ? expression.argumentList.arguments.first
            : null;
        if (arg is StringLiteral) {
          return DetectionResult(
            key: arg.stringValue ?? '',
            detector: name,
            tags: expression.isConst ? ['const'] : null,
          );
        }
      }
    }
    return null;
  }
}

import 'package:analyzer/dart/ast/ast.dart';
import 'package:yaml/yaml.dart';

/// Base class for key detectors
abstract class KeyDetector {
  final String name;
  final String description;
  final int priority;
  final Map<String, dynamic> config;

  // Metrics
  int matchCount = 0;
  int extractCount = 0;
  final List<String> matchedPatterns = [];

  KeyDetector({
    required this.name,
    required this.description,
    this.priority = 0,
    this.config = const {},
  });

  /// Check if AST node matches this detector
  bool matches(AstNode node);

  /// Extract key value from matched node
  String? extractKey(AstNode node);

  /// Check if expression matches
  bool matchesExpression(Expression expr);

  /// Extract from expression
  String? extractFromExpression(Expression expr);

  /// Get detector metrics
  Map<String, dynamic> getMetrics() => {
        'name': name,
        'matches': matchCount,
        'extracted': extractCount,
        'patterns': matchedPatterns.toSet().toList(),
      };
}

/// Detector for ValueKey patterns
class ValueKeyDetector extends KeyDetector {
  ValueKeyDetector({Map<String, dynamic>? config})
      : super(
          name: 'ValueKey',
          description: 'Detects ValueKey(...) patterns',
          priority: 10,
          config: config ?? {},
        );

  @override
  bool matches(AstNode node) {
    if (node is InstanceCreationExpression) {
      final typeName = node.constructorName.type.toString();
      if (typeName == 'ValueKey' || typeName.endsWith('.ValueKey')) {
        matchCount++;
        return true;
      }
    }
    return false;
  }

  @override
  String? extractKey(AstNode node) {
    if (node is InstanceCreationExpression) {
      final args = node.argumentList.arguments;
      if (args.isNotEmpty) {
        final key = _extractStringValue(args.first);
        if (key != null) {
          extractCount++;
          matchedPatterns.add('ValueKey("$key")');
        }
        return key;
      }
    }
    return null;
  }

  @override
  bool matchesExpression(Expression expr) {
    if (expr is InstanceCreationExpression) {
      return matches(expr);
    }
    return false;
  }

  @override
  String? extractFromExpression(Expression expr) {
    if (expr is InstanceCreationExpression) {
      return extractKey(expr);
    }
    return null;
  }

  String? _extractStringValue(Expression expr) {
    if (expr is SimpleStringLiteral) {
      return expr.value;
    }
    if (expr is StringInterpolation) {
      // Handle string interpolation
      final buffer = StringBuffer();
      for (final element in expr.elements) {
        if (element is InterpolationString) {
          buffer.write(element.value);
        } else if (element is InterpolationExpression) {
          buffer.write('\${...}');
        }
      }
      return buffer.toString();
    }
    if (expr is PrefixedIdentifier) {
      // Handle constants like KeyConstants.loginButton
      return '${expr.prefix}.${expr.identifier}';
    }
    if (expr is PropertyAccess) {
      // Handle property access
      return expr.toString();
    }
    return null;
  }
}

/// Detector for Key patterns
class BasicKeyDetector extends KeyDetector {
  BasicKeyDetector({Map<String, dynamic>? config})
      : super(
          name: 'Key',
          description: 'Detects Key(...) patterns',
          priority: 9,
          config: config ?? {},
        );

  @override
  bool matches(AstNode node) {
    if (node is InstanceCreationExpression) {
      final typeName = node.constructorName.type.toString();
      if (typeName == 'Key' || typeName.endsWith('.Key')) {
        matchCount++;
        return true;
      }
    }
    return false;
  }

  @override
  String? extractKey(AstNode node) {
    if (node is InstanceCreationExpression) {
      final args = node.argumentList.arguments;
      if (args.isNotEmpty) {
        final key = _extractStringValue(args.first);
        if (key != null) {
          extractCount++;
          matchedPatterns.add('Key("$key")');
        }
        return key;
      }
    }
    return null;
  }

  @override
  bool matchesExpression(Expression expr) => matches(expr);

  @override
  String? extractFromExpression(Expression expr) => extractKey(expr);

  String? _extractStringValue(Expression expr) {
    // Same implementation as ValueKeyDetector
    if (expr is SimpleStringLiteral) {
      return expr.value;
    }
    // ... other cases
    return null;
  }
}

/// Detector for find.byKey patterns in tests
class FindByKeyDetector extends KeyDetector {
  FindByKeyDetector({Map<String, dynamic>? config})
      : super(
          name: 'FindByKey',
          description: 'Detects find.byKey(...) patterns in tests',
          priority: 8,
          config: config ?? {},
        );

  @override
  bool matches(AstNode node) {
    if (node is MethodInvocation) {
      final target = node.target?.toString();
      final method = node.methodName.name;
      if (target == 'find' && (method == 'byKey' || method == 'byValueKey')) {
        matchCount++;
        return true;
      }
    }
    return false;
  }

  @override
  String? extractKey(AstNode node) {
    if (node is MethodInvocation) {
      final args = node.argumentList.arguments;
      if (args.isNotEmpty) {
        final firstArg = args.first;

        // Handle direct string
        if (firstArg is SimpleStringLiteral) {
          extractCount++;
          final key = firstArg.value;
          matchedPatterns.add('find.byKey("$key")');
          return key;
        }

        // Handle Key/ValueKey creation
        if (firstArg is InstanceCreationExpression) {
          final innerArgs = firstArg.argumentList.arguments;
          if (innerArgs.isNotEmpty && innerArgs.first is StringLiteral) {
            extractCount++;
            final key = (innerArgs.first as StringLiteral).value;
            matchedPatterns.add('find.byKey(Key("$key"))');
            return key;
          }
        }
      }
    }
    return null;
  }

  @override
  bool matchesExpression(Expression expr) => false;

  @override
  String? extractFromExpression(Expression expr) => null;
}

/// Detector for custom key patterns
class CustomPatternDetector extends KeyDetector {
  final String pattern;
  final String extraction;
  final RegExp? regex;

  CustomPatternDetector({
    required super.name,
    required this.pattern,
    required this.extraction,
    Map<String, dynamic>? config,
  })  : regex = RegExp(pattern),
        super(
          description: 'Custom pattern: $pattern',
          priority: 5,
          config: config ?? {},
        );

  @override
  bool matches(AstNode node) {
    final nodeString = node.toString();
    if (regex != null && regex!.hasMatch(nodeString)) {
      matchCount++;
      return true;
    }
    return false;
  }

  @override
  String? extractKey(AstNode node) {
    final nodeString = node.toString();
    if (regex != null) {
      final match = regex!.firstMatch(nodeString);
      if (match != null) {
        // Use extraction pattern to get key
        if (extraction == 'group1' && match.groupCount >= 1) {
          extractCount++;
          final key = match.group(1);
          matchedPatterns.add(key ?? '');
          return key;
        }
      }
    }
    return null;
  }

  @override
  bool matchesExpression(Expression expr) => matches(expr);

  @override
  String? extractFromExpression(Expression expr) => extractKey(expr);
}

/// Detector for Semantics labels (accessibility)
class SemanticsDetector extends KeyDetector {
  SemanticsDetector({Map<String, dynamic>? config})
      : super(
          name: 'Semantics',
          description: 'Detects Semantics labels for accessibility',
          priority: 7,
          config: config ?? {},
        );

  @override
  bool matches(AstNode node) {
    if (node is InstanceCreationExpression) {
      final typeName = node.constructorName.type.toString();
      if (typeName == 'Semantics' || typeName.endsWith('.Semantics')) {
        // Check for label parameter
        final hasLabel = node.argumentList.arguments
            .whereType<NamedExpression>()
            .any((arg) => arg.name.label.name == 'label');
        if (hasLabel) {
          matchCount++;
          return true;
        }
      }
    }
    return false;
  }

  @override
  String? extractKey(AstNode node) {
    if (node is InstanceCreationExpression) {
      final labelArgs = node.argumentList.arguments
          .whereType<NamedExpression>()
          .where((arg) => arg.name.label.name == 'label')
          .toList();
      final labelArg = labelArgs.isNotEmpty ? labelArgs.first : null;

      if (labelArg?.expression is StringLiteral) {
        extractCount++;
        final label = (labelArg!.expression as StringLiteral).value;
        matchedPatterns.add('Semantics(label: "$label")');
        return 'semantics:$label';
      }
    }
    return null;
  }

  @override
  bool matchesExpression(Expression expr) => false;

  @override
  String? extractFromExpression(Expression expr) => null;
}

/// Factory for creating detectors from configuration
class DetectorFactory {
  static List<KeyDetector> createFromConfig(YamlMap? config) {
    final detectors = <KeyDetector>[];

    // Always include built-in detectors
    detectors.add(ValueKeyDetector());
    detectors.add(BasicKeyDetector());
    detectors.add(FindByKeyDetector());
    detectors.add(SemanticsDetector());

    // Add custom detectors from config
    if (config != null && config['custom_detectors'] != null) {
      final customList = config['custom_detectors'] as YamlList;
      for (final custom in customList) {
        if (custom is YamlMap) {
          detectors.add(CustomPatternDetector(
            name: custom['name'] as String,
            pattern: custom['pattern'] as String,
            extraction: custom['extraction'] as String? ?? 'group1',
            config: custom['config'] as Map<String, dynamic>? ?? {},
          ));
        }
      }
    }

    // Sort by priority
    detectors.sort((a, b) => b.priority.compareTo(a.priority));

    return detectors;
  }

  /// Create detectors for specific testing frameworks
  static List<KeyDetector> createTestDetectors() {
    return [
      FindByKeyDetector(),
      CustomPatternDetector(
        name: 'PatrolFinder',
        pattern: r'''\$\((["'])(.*?)\1\)''',
        extraction: 'group2',
      ),
      CustomPatternDetector(
        name: 'IntegrationTestKey',
        pattern: r'''key:\s*["']([^"']+)["']''',
        extraction: 'group1',
      ),
    ];
  }

  /// Create detectors for specific UI frameworks
  static List<KeyDetector> createFrameworkDetectors(String framework) {
    switch (framework) {
      case 'material':
        return [
          CustomPatternDetector(
            name: 'MaterialKey',
            pattern: r'''key:\s*MaterialKey\s*\(\s*["']([^"']+)["']\s*\)''',
            extraction: 'group1',
          ),
        ];
      case 'cupertino':
        return [
          CustomPatternDetector(
            name: 'CupertinoKey',
            pattern: r'''key:\s*CupertinoKey\s*\(\s*["']([^"']+)["']\s*\)''',
            extraction: 'group1',
          ),
        ];
      default:
        return [];
    }
  }
}

import 'dart:convert';
import 'dart:io';
import 'package:crypto/crypto.dart';
import 'package:path/path.dart' as path;

/// Cache system for scan results
class ScanCache {
  final String projectPath;
  final String cacheDir;
  final Duration maxAge;
  final bool enabled;

  late final File _indexFile;
  late final Directory _cacheDirectory;
  final Map<String, CacheEntry> _memoryCache = {};

  ScanCache({
    required this.projectPath,
    String? cacheDir,
    this.maxAge = const Duration(hours: 24),
    this.enabled = true,
  }) : cacheDir =
            cacheDir ?? path.join(projectPath, '.flutter_keycheck', 'cache') {
    _cacheDirectory = Directory(this.cacheDir);
    _indexFile = File(path.join(this.cacheDir, 'cache_index.json'));

    if (enabled) {
      _initializeCache();
    }
  }

  /// Initialize cache directory and load index
  void _initializeCache() {
    if (!_cacheDirectory.existsSync()) {
      _cacheDirectory.createSync(recursive: true);
    }

    if (_indexFile.existsSync()) {
      _loadIndex();
    }
  }

  /// Load cache index from disk
  void _loadIndex() {
    try {
      final content = _indexFile.readAsStringSync();
      final index = jsonDecode(content) as Map<String, dynamic>;

      for (final entry in index.entries) {
        final cacheEntry =
            CacheEntry.fromJson(entry.value as Map<String, dynamic>);

        // Check if entry is still valid
        if (!_isExpired(cacheEntry)) {
          _memoryCache[entry.key] = cacheEntry;
        }
      }
    } catch (e) {
      // Invalid cache index, start fresh
      _memoryCache.clear();
    }
  }

  /// Save cache index to disk
  void _saveIndex() {
    if (!enabled) return;

    final index = <String, dynamic>{};
    for (final entry in _memoryCache.entries) {
      index[entry.key] = entry.value.toJson();
    }

    _indexFile.writeAsStringSync(
      const JsonEncoder.withIndent('  ').convert(index),
    );
  }

  /// Get cached file analysis
  FileAnalysisCache? getFileAnalysis(String filePath) {
    if (!enabled) return null;

    final key = _getFileKey(filePath);
    final entry = _memoryCache[key];

    if (entry == null || _isExpired(entry)) {
      return null;
    }

    // Check if file has been modified
    final file = File(filePath);
    if (!file.existsSync()) {
      _memoryCache.remove(key);
      return null;
    }

    final currentHash = _getFileHash(file);
    if (currentHash != entry.fileHash) {
      _memoryCache.remove(key);
      return null;
    }

    // Load cached data
    final cacheFile = File(path.join(cacheDir, entry.cacheFile));
    if (!cacheFile.existsSync()) {
      _memoryCache.remove(key);
      return null;
    }

    try {
      final content = cacheFile.readAsStringSync();
      final data = jsonDecode(content) as Map<String, dynamic>;

      // Update hit count
      entry.hits++;
      entry.lastAccessed = DateTime.now();
      _saveIndex();

      return FileAnalysisCache.fromJson(data);
    } catch (e) {
      _memoryCache.remove(key);
      return null;
    }
  }

  /// Cache file analysis
  void cacheFileAnalysis(String filePath, FileAnalysisCache analysis) {
    if (!enabled) return;

    final key = _getFileKey(filePath);
    final file = File(filePath);

    if (!file.existsSync()) return;

    final fileHash = _getFileHash(file);
    final cacheFileName = '${_sanitizeFileName(filePath)}_$fileHash.json';
    final cacheFile = File(path.join(cacheDir, cacheFileName));

    // Save analysis data
    cacheFile.writeAsStringSync(
      jsonEncode(analysis.toJson()),
    );

    // Update index
    _memoryCache[key] = CacheEntry(
      filePath: filePath,
      fileHash: fileHash,
      cacheFile: cacheFileName,
      created: DateTime.now(),
      lastAccessed: DateTime.now(),
      size: file.lengthSync(),
      hits: 0,
    );

    _saveIndex();
  }

  /// Get cache statistics
  CacheStats getStats() {
    final stats = CacheStats();

    if (!enabled) {
      stats.enabled = false;
      return stats;
    }

    stats.enabled = true;
    stats.entries = _memoryCache.length;

    // Calculate size
    for (final entry in _memoryCache.values) {
      final cacheFile = File(path.join(cacheDir, entry.cacheFile));
      if (cacheFile.existsSync()) {
        stats.totalSize += cacheFile.lengthSync();
      }
      stats.totalHits += entry.hits;
    }

    // Find hot entries
    final sortedByHits = _memoryCache.values.toList()
      ..sort((a, b) => b.hits.compareTo(a.hits));

    stats.hotEntries = sortedByHits
        .take(10)
        .map((e) => HotEntry(
              file: e.filePath,
              hits: e.hits,
              lastAccessed: e.lastAccessed,
            ))
        .toList();

    // Calculate hit rate
    if (stats.totalHits > 0 || _memoryCache.isNotEmpty) {
      stats.hitRate =
          stats.totalHits / (stats.totalHits + _memoryCache.length).toDouble();
    }

    return stats;
  }

  /// Clear expired entries
  void cleanExpired() {
    if (!enabled) return;

    final expired = <String>[];

    for (final entry in _memoryCache.entries) {
      if (_isExpired(entry.value)) {
        expired.add(entry.key);

        // Delete cache file
        final cacheFile = File(path.join(cacheDir, entry.value.cacheFile));
        if (cacheFile.existsSync()) {
          cacheFile.deleteSync();
        }
      }
    }

    for (final key in expired) {
      _memoryCache.remove(key);
    }

    if (expired.isNotEmpty) {
      _saveIndex();
    }
  }

  /// Clear all cache
  void clear() {
    if (!enabled) return;

    _memoryCache.clear();

    // Delete all cache files
    if (_cacheDirectory.existsSync()) {
      _cacheDirectory.deleteSync(recursive: true);
      _cacheDirectory.createSync(recursive: true);
    }

    _saveIndex();
  }

  /// Warm cache by pre-scanning files
  Future<void> warmCache(List<String> files) async {
    if (!enabled) return;

    for (final filePath in files) {
      // Check if already cached
      if (getFileAnalysis(filePath) != null) {
        continue;
      }

      // File has changed, cache entry is invalid
      // This would require integration with AST scanner
    }
  }

  /// Get cache key for file
  String _getFileKey(String filePath) {
    return path.relative(filePath, from: projectPath);
  }

  /// Get file content hash
  String _getFileHash(File file) {
    final bytes = file.readAsBytesSync();
    final digest = sha256.convert(bytes);
    return digest.toString().substring(0, 16);
  }

  /// Sanitize file name for cache storage
  String _sanitizeFileName(String filePath) {
    return path
        .relative(filePath, from: projectPath)
        .replaceAll(path.separator, '_')
        .replaceAll('.', '_');
  }

  /// Check if cache entry is expired
  bool _isExpired(CacheEntry entry) {
    final age = DateTime.now().difference(entry.created);
    return age > maxAge;
  }
}

/// Cache entry metadata
class CacheEntry {
  final String filePath;
  final String fileHash;
  final String cacheFile;
  final DateTime created;
  DateTime lastAccessed;
  final int size;
  int hits;

  CacheEntry({
    required this.filePath,
    required this.fileHash,
    required this.cacheFile,
    required this.created,
    required this.lastAccessed,
    required this.size,
    this.hits = 0,
  });

  factory CacheEntry.fromJson(Map<String, dynamic> json) {
    return CacheEntry(
      filePath: json['file_path'] as String,
      fileHash: json['file_hash'] as String,
      cacheFile: json['cache_file'] as String,
      created: DateTime.parse(json['created'] as String),
      lastAccessed: DateTime.parse(json['last_accessed'] as String),
      size: json['size'] as int,
      hits: json['hits'] as int? ?? 0,
    );
  }

  Map<String, dynamic> toJson() => {
        'file_path': filePath,
        'file_hash': fileHash,
        'cache_file': cacheFile,
        'created': created.toIso8601String(),
        'last_accessed': lastAccessed.toIso8601String(),
        'size': size,
        'hits': hits,
      };
}

/// Cached file analysis data
class FileAnalysisCache {
  final String path;
  final List<String> keys;
  final List<String> widgets;
  final Map<String, int> detectorHits;
  final int nodeCount;
  final int widgetCount;
  final int widgetsWithKeys;

  FileAnalysisCache({
    required this.path,
    required this.keys,
    required this.widgets,
    required this.detectorHits,
    required this.nodeCount,
    required this.widgetCount,
    required this.widgetsWithKeys,
  });

  factory FileAnalysisCache.fromJson(Map<String, dynamic> json) {
    return FileAnalysisCache(
      path: json['path'] as String,
      keys: (json['keys'] as List).cast<String>(),
      widgets: (json['widgets'] as List).cast<String>(),
      detectorHits: (json['detector_hits'] as Map).cast<String, int>(),
      nodeCount: json['node_count'] as int,
      widgetCount: json['widget_count'] as int,
      widgetsWithKeys: json['widgets_with_keys'] as int,
    );
  }

  Map<String, dynamic> toJson() => {
        'path': path,
        'keys': keys,
        'widgets': widgets,
        'detector_hits': detectorHits,
        'node_count': nodeCount,
        'widget_count': widgetCount,
        'widgets_with_keys': widgetsWithKeys,
      };
}

/// Cache statistics
class CacheStats {
  bool enabled = true;
  int entries = 0;
  int totalSize = 0;
  int totalHits = 0;
  double hitRate = 0;
  List<HotEntry> hotEntries = [];

  Map<String, dynamic> toJson() => {
        'enabled': enabled,
        'entries': entries,
        'total_size': totalSize,
        'total_size_mb': (totalSize / 1024 / 1024).toStringAsFixed(2),
        'total_hits': totalHits,
        'hit_rate': hitRate,
        'hot_entries': hotEntries.map((e) => e.toJson()).toList(),
      };
}

/// Hot cache entry
class HotEntry {
  final String file;
  final int hits;
  final DateTime lastAccessed;

  HotEntry({
    required this.file,
    required this.hits,
    required this.lastAccessed,
  });

  Map<String, dynamic> toJson() => {
        'file': file,
        'hits': hits,
        'last_accessed': lastAccessed.toIso8601String(),
      };
}

import '../scanner/ast_scanner_v3.dart' show AstScannerV3;
export '../scanner/ast_scanner_v3.dart' show AstScannerV3;

typedef WorkspaceScanner = AstScannerV3;

/// Statistics calculation engine for Flutter KeyCheck
/// 
/// Provides comprehensive statistical analysis including file coverage,
/// key distribution, performance trends, and efficiency scoring.
library;

import 'dart:math' as math;

/// Comprehensive statistics for key analysis
class KeyStatistics {
  final Map<String, dynamic> coverage;
  final Map<String, dynamic> distribution;
  final Map<String, dynamic> usage;
  final Map<String, dynamic> performance;
  final Map<String, dynamic> quality;
  final Map<String, dynamic> trends;

  const KeyStatistics({
    required this.coverage,
    required this.distribution,
    required this.usage,
    required this.performance,
    required this.quality,
    required this.trends,
  });

  /// Convert to JSON for serialization
  Map<String, dynamic> toJson() => {
        'coverage': coverage,
        'distribution': distribution,
        'usage': usage,
        'performance': performance,
        'quality': quality,
        'trends': trends,
      };

  /// Get summary metrics for dashboards
  Map<String, dynamic> get summary => {
        'coveragePercentage': coverage['percentage'],
        'totalKeys': distribution['totalKeys'],
        'filesScanned': coverage['filesScanned'],
        'avgKeysPerFile': distribution['avgKeysPerFile'],
        'performanceScore': performance['score'],
        'qualityScore': quality['score'],
      };
}

/// File coverage analysis result
class FileCoverageResult {
  final String filePath;
  final int keyCount;
  final List<String> keys;
  final double coverageScore;
  final bool isTestFile;
  final bool hasKeyConstants;

  const FileCoverageResult({
    required this.filePath,
    required this.keyCount,
    required this.keys,
    required this.coverageScore,
    required this.isTestFile,
    required this.hasKeyConstants,
  });

  Map<String, dynamic> toJson() => {
        'filePath': filePath,
        'keyCount': keyCount,
        'keys': keys,
        'coverageScore': coverageScore,
        'isTestFile': isTestFile,
        'hasKeyConstants': hasKeyConstants,
      };
}

/// Key distribution analysis
class KeyDistribution {
  final Map<String, int> byFile;
  final Map<String, int> byCategory;
  final Map<String, double> categoryPercentages;
  final List<String> hotspots;
  final List<String> coldSpots;

  const KeyDistribution({
    required this.byFile,
    required this.byCategory,
    required this.categoryPercentages,
    required this.hotspots,
    required this.coldSpots,
  });

  Map<String, dynamic> toJson() => {
        'byFile': byFile,
        'byCategory': byCategory,
        'categoryPercentages': categoryPercentages,
        'hotspots': hotspots,
        'coldSpots': coldSpots,
      };
}

/// Performance metrics and trends
class PerformanceMetrics {
  final Duration scanTime;
  final int keysPerSecond;
  final double memoryUsage;
  final Map<String, int> operationCounts;
  final List<String> bottlenecks;

  const PerformanceMetrics({
    required this.scanTime,
    required this.keysPerSecond,
    required this.memoryUsage,
    required this.operationCounts,
    required this.bottlenecks,
  });

  Map<String, dynamic> toJson() => {
        'scanTimeMs': scanTime.inMilliseconds,
        'keysPerSecond': keysPerSecond,
        'memoryUsageMB': memoryUsage,
        'operationCounts': operationCounts,
        'bottlenecks': bottlenecks,
      };
}

/// Main statistics calculation engine
class StatsCalculator {
  /// Calculate comprehensive statistics
  static KeyStatistics calculateStatistics({
    required Set<String> expectedKeys,
    required Set<String> foundKeys,
    required Set<String> missingKeys,
    required Set<String> extraKeys,
    Map<String, int>? keyUsageCounts,
    Map<String, List<dynamic>>? keyLocations,
    List<String>? scannedFiles,
    Duration? scanDuration,
    Map<String, dynamic>? additionalMetrics,
  }) {
    // Calculate coverage statistics
    final coverage = _calculateCoverageStats(
      expectedKeys, foundKeys, missingKeys, scannedFiles, keyLocations);

    // Calculate distribution statistics  
    final distribution = _calculateDistributionStats(
      foundKeys, extraKeys, keyLocations, scannedFiles);

    // Calculate usage statistics
    final usage = _calculateUsageStats(
      foundKeys, keyUsageCounts, keyLocations);

    // Calculate performance statistics
    final performance = _calculatePerformanceStats(
      foundKeys, scannedFiles, scanDuration, additionalMetrics);

    // Calculate quality statistics
    final quality = _calculateQualityStats(
      expectedKeys, foundKeys, missingKeys, extraKeys, keyUsageCounts);

    // Calculate trend analysis
    final trends = _calculateTrendStats(
      expectedKeys, foundKeys, keyUsageCounts, additionalMetrics);

    return KeyStatistics(
      coverage: coverage,
      distribution: distribution,
      usage: usage,
      performance: performance,
      quality: quality,
      trends: trends,
    );
  }

  /// Analyze file coverage in detail
  static List<FileCoverageResult> analyzeFileCoverage({
    required Map<String, List<dynamic>>? keyLocations,
    required List<String>? scannedFiles,
    required Set<String> foundKeys,
  }) {
    if (keyLocations == null || scannedFiles == null) {
      return [];
    }

    final fileResults = <FileCoverageResult>[];
    final keysByFile = <String, List<String>>{};

    // Group keys by file
    for (final entry in keyLocations.entries) {
      final key = entry.key;
      final locations = entry.value;

      for (final location in locations) {
        if (location is Map && location['file'] != null) {
          final file = location['file'] as String;
          keysByFile.putIfAbsent(file, () => []).add(key);
        }
      }
    }

    // Analyze each file
    for (final file in scannedFiles) {
      final keysInFile = keysByFile[file] ?? [];
      final coverage = _calculateFileCoverageScore(keysInFile, foundKeys);

      fileResults.add(FileCoverageResult(
        filePath: file,
        keyCount: keysInFile.length,
        keys: keysInFile,
        coverageScore: coverage,
        isTestFile: _isTestFile(file),
        hasKeyConstants: _hasKeyConstants(file, keysInFile),
      ));
    }

    // Sort by coverage score (descending)
    fileResults.sort((a, b) => b.coverageScore.compareTo(a.coverageScore));

    return fileResults;
  }

  /// Analyze key distribution patterns
  static KeyDistribution analyzeKeyDistribution({
    required Set<String> foundKeys,
    required Map<String, List<dynamic>>? keyLocations,
  }) {
    final byFile = <String, int>{};
    final byCategory = <String, int>{};

    if (keyLocations != null) {
      // Count keys by file
      for (final locations in keyLocations.values) {
        for (final location in locations) {
          if (location is Map && location['file'] != null) {
            final file = location['file'] as String;
            byFile[file] = (byFile[file] ?? 0) + 1;
          }
        }
      }
    }

    // Categorize keys by type/pattern
    for (final key in foundKeys) {
      final category = _categorizeKey(key);
      byCategory[category] = (byCategory[category] ?? 0) + 1;
    }

    // Calculate percentages
    final total = foundKeys.length;
    final categoryPercentages = byCategory.map((category, count) =>
        MapEntry(category, total > 0 ? (count / total) * 100 : 0.0));

    // Identify hotspots and cold spots
    final sortedFiles = byFile.entries.toList()
      ..sort((a, b) => b.value.compareTo(a.value));

    final hotspots = sortedFiles.take(5).map((e) => e.key).toList();
    final coldSpots = sortedFiles.reversed.take(5).map((e) => e.key).toList();

    return KeyDistribution(
      byFile: byFile,
      byCategory: byCategory,
      categoryPercentages: categoryPercentages,
      hotspots: hotspots,
      coldSpots: coldSpots,
    );
  }

  /// Calculate coverage statistics
  static Map<String, dynamic> _calculateCoverageStats(
      Set<String> expectedKeys, Set<String> foundKeys, Set<String> missingKeys,
      List<String>? scannedFiles, Map<String, List<dynamic>>? keyLocations) {

    final totalExpected = expectedKeys.length;
    final totalFound = foundKeys.length;
    final totalMissing = missingKeys.length;

    final percentage = totalExpected > 0 ? 
        ((totalExpected - totalMissing) / totalExpected) * 100 : 100.0;

    // Calculate file coverage
    int filesWithKeys = 0;
    if (keyLocations != null && scannedFiles != null) {
      final filesWithKeysSet = keyLocations.values
          .expand((locations) => locations)
          .where((loc) => loc is Map && loc['file'] != null)
          .map((loc) => loc['file'] as String)
          .toSet();
      filesWithKeys = filesWithKeysSet.length;
    }

    return {
      'percentage': percentage,
      'expectedKeys': totalExpected,
      'foundKeys': totalFound,
      'missingKeys': totalMissing,
      'filesScanned': scannedFiles?.length ?? 0,
      'filesWithKeys': filesWithKeys,
      'fileCoverage': scannedFiles != null && scannedFiles.isNotEmpty ?
          (filesWithKeys / scannedFiles.length) * 100 : 0.0,
    };
  }

  /// Calculate distribution statistics
  static Map<String, dynamic> _calculateDistributionStats(
      Set<String> foundKeys, Set<String> extraKeys,
      Map<String, List<dynamic>>? keyLocations, List<String>? scannedFiles) {

    final totalKeys = foundKeys.length + extraKeys.length;

    // Calculate keys per file
    final keysByFile = <String, int>{};
    if (keyLocations != null) {
      for (final locations in keyLocations.values) {
        for (final location in locations) {
          if (location is Map && location['file'] != null) {
            final file = location['file'] as String;
            keysByFile[file] = (keysByFile[file] ?? 0) + 1;
          }
        }
      }
    }

    final avgKeysPerFile = keysByFile.isNotEmpty ?
        keysByFile.values.reduce((a, b) => a + b) / keysByFile.length : 0.0;

    final maxKeysPerFile = keysByFile.isNotEmpty ?
        keysByFile.values.reduce(math.max) : 0;

    final minKeysPerFile = keysByFile.isNotEmpty ?
        keysByFile.values.reduce(math.min) : 0;

    // Calculate distribution variance
    final variance = keysByFile.isNotEmpty ?
        _calculateVariance(keysByFile.values.toList()) : 0.0;

    return {
      'totalKeys': totalKeys,
      'avgKeysPerFile': avgKeysPerFile,
      'maxKeysPerFile': maxKeysPerFile,
      'minKeysPerFile': minKeysPerFile,
      'distributionVariance': variance,
      'extraKeysRatio': totalKeys > 0 ? (extraKeys.length / totalKeys) * 100 : 0.0,
    };
  }

  /// Calculate usage statistics
  static Map<String, dynamic> _calculateUsageStats(
      Set<String> foundKeys, Map<String, int>? keyUsageCounts,
      Map<String, List<dynamic>>? keyLocations) {

    if (keyUsageCounts == null || keyUsageCounts.isEmpty) {
      return {
        'averageUsage': 0.0,
        'maxUsage': 0,
        'minUsage': 0,
        'duplicateKeys': 0,
        'uniqueKeys': foundKeys.length,
        'usageVariance': 0.0,
      };
    }

    final usages = keyUsageCounts.values.toList();
    final averageUsage = usages.reduce((a, b) => a + b) / usages.length;
    final maxUsage = usages.reduce(math.max);
    final minUsage = usages.reduce(math.min);
    final duplicateKeys = usages.where((usage) => usage > 1).length;
    final uniqueKeys = usages.where((usage) => usage == 1).length;
    final usageVariance = _calculateVariance(usages);

    return {
      'averageUsage': averageUsage,
      'maxUsage': maxUsage,
      'minUsage': minUsage,
      'duplicateKeys': duplicateKeys,
      'uniqueKeys': uniqueKeys,
      'usageVariance': usageVariance,
      'efficiencyScore': _calculateUsageEfficiency(usages),
    };
  }

  /// Calculate performance statistics
  static Map<String, dynamic> _calculatePerformanceStats(
      Set<String> foundKeys, List<String>? scannedFiles, Duration? scanDuration,
      Map<String, dynamic>? additionalMetrics) {

    final keysPerSecond = scanDuration != null && scanDuration.inMilliseconds > 0 ?
        (foundKeys.length * 1000) / scanDuration.inMilliseconds : 0.0;

    final filesPerSecond = scanDuration != null && scanDuration.inMilliseconds > 0 && scannedFiles != null ?
        (scannedFiles.length * 1000) / scanDuration.inMilliseconds : 0.0;

    // Performance score based on scanning efficiency
    double performanceScore = 70.0; // Base score

    if (keysPerSecond > 1000) {
      performanceScore += 20.0;
    } else if (keysPerSecond > 500) performanceScore += 15.0;
    else if (keysPerSecond > 100) performanceScore += 10.0;
    else if (keysPerSecond > 50) performanceScore += 5.0;

    if (filesPerSecond > 10) {
      performanceScore += 10.0;
    } else if (filesPerSecond > 5) performanceScore += 5.0;

    return {
      'scanTimeMs': scanDuration?.inMilliseconds ?? 0,
      'keysPerSecond': keysPerSecond,
      'filesPerSecond': filesPerSecond,
      'score': math.min(performanceScore, 100.0),
      'memoryEstimateMB': _estimateMemoryUsage(foundKeys, scannedFiles),
    };
  }

  /// Calculate quality statistics
  static Map<String, dynamic> _calculateQualityStats(
      Set<String> expectedKeys, Set<String> foundKeys, Set<String> missingKeys,
      Set<String> extraKeys, Map<String, int>? keyUsageCounts) {

    // Base quality score
    double qualityScore = 50.0;

    // Coverage component (40%)
    final coverage = expectedKeys.isEmpty ? 100.0 :
        ((expectedKeys.length - missingKeys.length) / expectedKeys.length) * 100;
    qualityScore += (coverage * 0.4);

    // Consistency component (30%)
    final consistencyScore = _calculateConsistencyScore(foundKeys, keyUsageCounts);
    qualityScore += (consistencyScore * 0.3);

    // Organization component (30%)
    final organizationScore = _calculateOrganizationScore(foundKeys, extraKeys);
    qualityScore += (organizationScore * 0.3);

    return {
      'score': math.min(qualityScore, 100.0),
      'coverage': coverage,
      'consistency': consistencyScore,
      'organization': organizationScore,
      'reliability': _calculateReliabilityScore(expectedKeys, foundKeys, missingKeys),
    };
  }

  /// Calculate trend statistics
  static Map<String, dynamic> _calculateTrendStats(
      Set<String> expectedKeys, Set<String> foundKeys,
      Map<String, int>? keyUsageCounts, Map<String, dynamic>? additionalMetrics) {

    // Placeholder for trend analysis - would need historical data
    return {
      'growthRate': 0.0,
      'improvementTrend': 'stable',
      'keyTurnover': 0.0,
      'stabilityScore': 85.0,
      'predictedCoverage': expectedKeys.isEmpty ? 100.0 :
          ((expectedKeys.length - (foundKeys.length - expectedKeys.intersection(foundKeys).length)) / expectedKeys.length) * 100,
    };
  }

  /// Calculate file coverage score for individual file
  static double _calculateFileCoverageScore(List<String> keysInFile, Set<String> allFoundKeys) {
    if (keysInFile.isEmpty) return 0.0;
    if (allFoundKeys.isEmpty) return 0.0;

    final validKeys = keysInFile.where((key) => allFoundKeys.contains(key)).length;
    return (validKeys / keysInFile.length) * 100;
  }

  /// Check if file is a test file
  static bool _isTestFile(String filePath) {
    return filePath.contains('/test/') || 
           filePath.contains('_test.dart') ||
           filePath.contains('/integration_test/');
  }

  /// Check if file uses KeyConstants pattern
  static bool _hasKeyConstants(String filePath, List<String> keys) {
    return keys.any((key) => key.contains('KeyConstants')) ||
           filePath.contains('key_constants.dart') ||
           filePath.contains('keys.dart');
  }

  /// Categorize key by naming pattern
  static String _categorizeKey(String key) {
    if (key.toLowerCase().contains('button')) return 'Buttons';
    if (key.toLowerCase().contains('field') || key.toLowerCase().contains('input')) return 'Input Fields';
    if (key.toLowerCase().contains('text') || key.toLowerCase().contains('label')) return 'Text Elements';
    if (key.toLowerCase().contains('screen') || key.toLowerCase().contains('page')) return 'Screens';
    if (key.toLowerCase().contains('dialog') || key.toLowerCase().contains('modal')) return 'Dialogs';
    if (key.toLowerCase().contains('menu') || key.toLowerCase().contains('nav')) return 'Navigation';
    if (key.toLowerCase().contains('icon')) return 'Icons';
    if (key.toLowerCase().contains('form')) return 'Forms';
    if (key.toLowerCase().contains('list') || key.toLowerCase().contains('item')) return 'Lists';
    return 'Other';
  }

  /// Calculate variance for a list of numbers
  static double _calculateVariance(List<int> values) {
    if (values.isEmpty) return 0.0;

    final mean = values.reduce((a, b) => a + b) / values.length;
    final squaredDiffs = values.map((value) => math.pow(value - mean, 2));
    return squaredDiffs.reduce((a, b) => a + b) / values.length;
  }

  /// Calculate usage efficiency score
  static double _calculateUsageEfficiency(List<int> usages) {
    if (usages.isEmpty) return 0.0;

    final singleUse = usages.where((u) => u == 1).length;
    final multiUse = usages.where((u) => u > 1).length;
    final total = usages.length;

    // Ideal scenario: most keys used once (clean automation)
    final efficiency = total > 0 ? (singleUse / total) * 100 : 0.0;

    // Penalize excessive duplication
    if (multiUse > total * 0.3) return efficiency * 0.7;
    if (multiUse > total * 0.2) return efficiency * 0.85;

    return efficiency;
  }

  /// Calculate consistency score based on naming patterns
  static double _calculateConsistencyScore(Set<String> foundKeys, Map<String, int>? keyUsageCounts) {
    if (foundKeys.isEmpty) return 0.0;

    double score = 50.0; // Base score

    // Check naming pattern consistency
    final camelCase = foundKeys.where((k) => k.contains(RegExp(r'[a-z][A-Z]'))).length;
    final snakeCase = foundKeys.where((k) => k.contains('_')).length;
    final total = foundKeys.length;

    final dominantPattern = math.max(camelCase, snakeCase);
    final consistency = dominantPattern / total;

    score += consistency * 30.0; // Up to 30 points for consistency

    // Check usage pattern consistency
    if (keyUsageCounts != null) {
      final duplicates = keyUsageCounts.values.where((v) => v > 1).length;
      final duplicateRatio = duplicates / keyUsageCounts.length;

      if (duplicateRatio < 0.1) {
        score += 20.0;
      } else if (duplicateRatio < 0.2) score += 10.0;
      else score += 5.0;
    }

    return math.min(score, 100.0);
  }

  /// Calculate organization score
  static double _calculateOrganizationScore(Set<String> foundKeys, Set<String> extraKeys) {
    if (foundKeys.isEmpty) return 0.0;

    double score = 60.0; // Base score

    // Penalize extra keys (noise)
    final total = foundKeys.length + extraKeys.length;
    if (total > 0) {
      final extraRatio = extraKeys.length / total;
      if (extraRatio < 0.05) {
        score += 20.0;
      } else if (extraRatio < 0.1) score += 15.0;
      else if (extraRatio < 0.2) score += 10.0;
      else score -= 10.0;
    }

    // Check for semantic organization
    final categories = foundKeys.map(_categorizeKey).toSet();
    if (categories.length > 3) {
      score += 20.0; // Good categorization
    } else if (categories.length > 1) score += 10.0;

    return math.min(score, 100.0);
  }

  /// Calculate reliability score
  static double _calculateReliabilityScore(
      Set<String> expectedKeys, Set<String> foundKeys, Set<String> missingKeys) {

    if (expectedKeys.isEmpty) return 100.0;

    final coverage = ((expectedKeys.length - missingKeys.length) / expectedKeys.length) * 100;

    // High reliability requires high coverage
    if (coverage >= 95.0) return 95.0;
    if (coverage >= 90.0) return 85.0;
    if (coverage >= 80.0) return 75.0;
    if (coverage >= 70.0) return 65.0;

    return coverage * 0.6; // Scale down for low coverage
  }

  /// Estimate memory usage
  static double _estimateMemoryUsage(Set<String> foundKeys, List<String>? scannedFiles) {
    // Rough estimation based on key count and file count
    final keyMemory = foundKeys.length * 0.1; // ~0.1KB per key
    final fileMemory = (scannedFiles?.length ?? 0) * 0.5; // ~0.5KB per file processed
    return (keyMemory + fileMemory) / 1024; // Convert to MB
  }
}

/// Safe type casting utilities
Map<String, dynamic> asMap(dynamic value) {
  if (value == null) return <String, dynamic>{};
  if (value is Map<String, dynamic>) return value;
  if (value is Map) {
    return Map<String, dynamic>.from(value);
  }
  return <String, dynamic>{};
}

int asInt(dynamic value) {
  if (value == null) return 0;
  if (value is int) return value;
  if (value is double) return value.toInt();
  if (value is num) return value.toInt();
  if (value is String) {
    final parsed = int.tryParse(value);
    if (parsed != null) return parsed;
  }
  return 0;
}

double asDouble(dynamic value) {
  if (value == null) return 0.0;
  if (value is double) return value;
  if (value is int) return value.toDouble();
  if (value is num) return value.toDouble();
  if (value is String) {
    final parsed = double.tryParse(value);
    if (parsed != null) return parsed;
  }
  return 0.0;
}

String asString(dynamic value) {
  if (value == null) return '';
  if (value is String) return value;
  return value.toString();
}

List<dynamic> asList(dynamic value) {
  if (value == null) return [];
  if (value is List) return value;
  return [];
}

bool asBool(dynamic value) {
  if (value == null) return false;
  if (value is bool) return value;
  if (value is String) {
    return value.toLowerCase() == 'true';
  }
  return false;
}

