{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://raw.githubusercontent.com/1nk1/flutter_keycheck/main/schemas/scan-coverage.v1.json",
  "title": "Flutter Keycheck Scan Coverage Schema",
  "version": "1.0.0",
  "description": "Schema for flutter_keycheck scan coverage metrics",
  "type": "object",
  "required": ["metrics", "detectors", "timestamp", "version"],
  "properties": {
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$",
      "description": "Schema version"
    },
    "timestamp": {
      "type": "string",
      "format": "date-time",
      "description": "ISO 8601 timestamp of scan"
    },
    "metrics": {
      "type": "object",
      "required": [
        "files_total",
        "files_scanned",
        "parse_success_rate",
        "widgets_total",
        "widgets_with_keys",
        "handlers_total",
        "handlers_linked"
      ],
      "properties": {
        "files_total": {
          "type": "integer",
          "minimum": 0,
          "description": "Total number of Dart files found"
        },
        "files_scanned": {
          "type": "integer",
          "minimum": 0,
          "description": "Number of files successfully scanned"
        },
        "parse_success_rate": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "Fraction of files parsed successfully (0.0 to 1.0)"
        },
        "widgets_total": {
          "type": "integer",
          "minimum": 0,
          "description": "Total number of widget instances found"
        },
        "widgets_with_keys": {
          "type": "integer",
          "minimum": 0,
          "description": "Number of widgets that have keys"
        },
        "handlers_total": {
          "type": "integer",
          "minimum": 0,
          "description": "Total number of event handlers found"
        },
        "handlers_linked": {
          "type": "integer",
          "minimum": 0,
          "description": "Number of handlers linked to keyed widgets"
        }
      }
    },
    "detectors": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name", "hits", "keys_found", "effectiveness"],
        "properties": {
          "name": {
            "type": "string",
            "description": "Detector name"
          },
          "hits": {
            "type": "integer",
            "minimum": 0,
            "description": "Number of times detector matched"
          },
          "keys_found": {
            "type": "integer",
            "minimum": 0,
            "description": "Number of unique keys found by this detector"
          },
          "effectiveness": {
            "type": "number",
            "minimum": 0,
            "maximum": 100,
            "description": "Detector effectiveness percentage"
          }
        }
      }
    }
  }
}

#!/bin/bash
set -e

echo "Testing Flutter KeyCheck CLI"
echo "============================"

# Create a simple test directory
mkdir -p test_workspace
cd test_workspace

# Create a simple Dart file with keys
cat > main.dart << 'EOF'
// Test file with keys
class TestWidget {
  final key = const ValueKey('test_key');
  final button = ElevatedButton(
    key: const ValueKey('button_key'),
  );
}

// Mock classes
class ValueKey {
  const ValueKey(this.value);
  final String value;
}

class ElevatedButton {
  const ElevatedButton({this.key});
  final ValueKey? key;
}
EOF

# Test commands
echo "Testing scan command..."
dart ../bin/flutter_keycheck.dart scan --report json

echo "Testing baseline command..."
dart ../bin/flutter_keycheck.dart baseline create

echo "Testing validate command..."
# Create threshold file first
cat > coverage-thresholds.yaml << 'EOF'
version: 1
thresholds:
  file_coverage: 0.8
  widget_coverage: 0.7
EOF
dart ../bin/flutter_keycheck.dart validate || true

echo "Testing diff command..."
dart ../bin/flutter_keycheck.dart diff

echo "Testing report command..."
dart ../bin/flutter_keycheck.dart report --format json

echo "Testing version..."
dart ../bin/flutter_keycheck.dart --version

echo "Testing help..."
dart ../bin/flutter_keycheck.dart --help

# Cleanup
cd ..
rm -rf test_workspace

echo "============================"
echo "CLI tests completed!"

import 'package:flutter_keycheck/src/ast_scanner.dart';
import 'package:test/test.dart';
import 'dart:io';
import 'package:path/path.dart' as path;

void main() {
  group('AstScanner', () {
    late Directory tempDir;
    late String projectPath;

    setUp(() {
      tempDir = Directory.systemTemp.createTempSync('ast_scanner_test_');
      projectPath = tempDir.path;
    });

    tearDown(() {
      if (tempDir.existsSync()) {
        tempDir.deleteSync(recursive: true);
      }
    });

    test('should detect basic Key() usage', () async {
      // Create a test file with keys
      final libDir = Directory(path.join(projectPath, 'lib'))..createSync();
      final testFile = File(path.join(libDir.path, 'test_widget.dart'));
      testFile.writeAsStringSync('''
import 'package:flutter/material.dart';

class TestWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Container(key: Key('container_key')),
        Text('Test', key: ValueKey('text_key')),
        ElevatedButton(
          key: Key('button_key'),
          onPressed: () {},
          child: Text('Button'),
        ),
      ],
    );
  }
}
''');

      final scanner = AstScanner(
        projectPath: projectPath,
        verbose: false,
      );

      final result = await scanner.scan();

      expect(result.foundKeys, contains('container_key'));
      expect(result.foundKeys, contains('text_key'));
      expect(result.foundKeys, contains('button_key'));
      expect(result.foundKeys.length, equals(3));
    });

    test('should respect include/exclude filters', () async {
      // Create test files
      final libDir = Directory(path.join(projectPath, 'lib'))..createSync();

      File(path.join(libDir.path, 'included.dart')).writeAsStringSync('''
import 'package:flutter/material.dart';
Widget test() => Container(key: Key('included_key'));
''');

      File(path.join(libDir.path, 'excluded.dart')).writeAsStringSync('''
import 'package:flutter/material.dart';
Widget test() => Container(key: Key('excluded_key'));
''');

      final scanner = AstScanner(
        projectPath: projectPath,
        exclude: ['.*excluded.*'],
        verbose: false,
      );

      final result = await scanner.scan();

      expect(result.foundKeys, contains('included_key'));
      expect(result.foundKeys, isNot(contains('excluded_key')));
    });

    test('should track key locations', () async {
      final libDir = Directory(path.join(projectPath, 'lib'))..createSync();
      final testFile = File(path.join(libDir.path, 'test.dart'));
      testFile.writeAsStringSync('''
import 'package:flutter/material.dart';
Widget test() => Container(key: Key('test_key'));
''');

      final scanner = AstScanner(
        projectPath: projectPath,
        verbose: false,
      );

      final result = await scanner.scan();

      expect(result.keyLocations['test_key'], isNotNull);
      expect(result.keyLocations['test_key']!.length, equals(1));

      final location = result.keyLocations['test_key']!.first;
      expect(location.line, equals(2));
      expect(location.filePath, endsWith('test.dart'));
    });

    test('should count key usage', () async {
      final libDir = Directory(path.join(projectPath, 'lib'))..createSync();
      final testFile = File(path.join(libDir.path, 'test.dart'));
      testFile.writeAsStringSync('''
import 'package:flutter/material.dart';
class Test extends StatelessWidget {
  Widget build(context) => Column(children: [
    Container(key: Key('repeated_key')),
    Container(key: Key('repeated_key')),
    Container(key: Key('unique_key')),
  ]);
}
''');

      final scanner = AstScanner(
        projectPath: projectPath,
        verbose: false,
      );

      final result = await scanner.scan();

      expect(result.keyUsageCounts['repeated_key'], equals(2));
      expect(result.keyUsageCounts['unique_key'], equals(1));
    });
  });
}

import 'package:flutter_keycheck/src/config.dart';
import 'package:test/test.dart';
import 'dart:io';
import 'package:path/path.dart' as path;

void main() {
  group('FlutterKeycheckConfig v3 Features', () {
    late Directory tempDir;

    setUp(() {
      tempDir = Directory.systemTemp.createTempSync('config_test_');
    });

    tearDown(() {
      if (tempDir.existsSync()) {
        tempDir.deleteSync(recursive: true);
      }
    });

    test('should have v3 configuration defaults', () {
      final config = FlutterKeycheckConfig.defaults();

      // v2 defaults should still work
      expect(config.keys, equals('keys/expected_keys.yaml'));
      expect(config.projectPath, equals('.'));
      expect(config.report, equals('human'));

      // v3 defaults
      expect(config.useAstScanning, equals(false)); // Backward compatibility
      expect(config.includeTestsInAst, equals(false));
      expect(config.cacheDir, equals('.flutter_keycheck_cache'));
      expect(config.enableMetrics, equals(false));
      expect(config.exportPath, isNull);
      expect(config.qualityThresholds, isNull);
    });

    test('should load v3 configuration from YAML', () {
      final configFile = File(path.join(tempDir.path, '.flutter_keycheck.yaml'));
      configFile.writeAsStringSync('''
keys: keys/expected.yaml
path: ./src
report: json
export_path: reports/output.json
use_ast_scanning: true
include_tests_in_ast: true
cache_dir: .cache
enable_metrics: true
quality_thresholds:
  coverage: 80
  max_missing: 5
''');

      final config = FlutterKeycheckConfig.loadFromFile(configFile.path);

      expect(config, isNotNull);
      expect(config!.keys, equals('keys/expected.yaml'));
      expect(config.projectPath, equals('./src'));
      expect(config.report, equals('json'));
      expect(config.exportPath, equals('reports/output.json'));
      expect(config.useAstScanning, equals(true));
      expect(config.includeTestsInAst, equals(true));
      expect(config.cacheDir, equals('.cache'));
      expect(config.enableMetrics, equals(true));
      expect(config.qualityThresholds, isNotNull);
      expect(config.qualityThresholds!['coverage'], equals(80));
      expect(config.qualityThresholds!['max_missing'], equals(5));
    });

    test('should merge v3 CLI arguments with config', () {
      final baseConfig = FlutterKeycheckConfig(
        keys: 'base.yaml',
        useAstScanning: false,
        enableMetrics: false,
      );

      final merged = baseConfig.mergeWith(
        keys: 'override.yaml',
        useAstScanning: true,
        enableMetrics: true,
        exportPath: 'report.html',
      );

      expect(merged.keys, equals('override.yaml'));
      expect(merged.useAstScanning, equals(true));
      expect(merged.enableMetrics, equals(true));
      expect(merged.exportPath, equals('report.html'));
    });

    test('should provide v3 getter methods', () {
      final config = FlutterKeycheckConfig(
        useAstScanning: true,
        includeTestsInAst: true,
        cacheDir: 'custom_cache',
        enableMetrics: true,
        exportPath: 'output.json',
        qualityThresholds: {'coverage': 90},
      );

      expect(config.isAstScanningEnabled(), equals(true));
      expect(config.shouldIncludeTestsInAst(), equals(true));
      expect(config.getCacheDir(), equals('custom_cache'));
      expect(config.areMetricsEnabled(), equals(true));
      expect(config.getExportPath(), equals('output.json'));
      expect(config.getQualityThresholds()['coverage'], equals(90));
    });

    test('should maintain backward compatibility', () {
      // Test that v2 configuration still works
      final configFile = File(path.join(tempDir.path, '.flutter_keycheck.yaml'));
      configFile.writeAsStringSync('''
keys: keys/expected.yaml
path: ./
strict: true
verbose: true
fail_on_extra: true
include_only:
  - lib/
exclude:
  - test/
tracked_keys:
  - key1
  - key2
report: json
''');

      final config = FlutterKeycheckConfig.loadFromFile(configFile.path);

      expect(config, isNotNull);
      // All v2 fields should work
      expect(config!.keys, equals('keys/expected.yaml'));
      expect(config.projectPath, equals('./'));
      expect(config.strict, equals(true));
      expect(config.verbose, equals(true));
      expect(config.failOnExtra, equals(true));
      expect(config.includeOnly, equals(['lib/']));
      expect(config.exclude, equals(['test/']));
      expect(config.trackedKeys, equals(['key1', 'key2']));
      expect(config.report, equals('json'));

      // v3 fields should have defaults
      expect(config.useAstScanning, isNull);
      expect(config.isAstScanningEnabled(), equals(false));
    });
  });
}

