      test('should complete statistics calculation within reasonable time', () {
        final stopwatch = Stopwatch()..start();

        StatsCalculator.calculateStatistics(
          expectedKeys: testData.expectedKeys,
          foundKeys: testData.foundKeys,
          missingKeys: testData.missingKeys,
          extraKeys: testData.extraKeys,
          keyUsageCounts: testData.keyUsageCounts,
          keyLocations: testData.keyLocations,
          scannedFiles: testData.scannedFiles,
          scanDuration: testData.scanDuration,
        );

        stopwatch.stop();
        expect(stopwatch.elapsedMilliseconds, lessThan(50), 
               reason: 'Statistics calculation should complete quickly');
      });

      test('should generate HTML report within reasonable time', () {
        final stopwatch = Stopwatch()..start();
        final reporter = HtmlReporter();

        reporter.generate(testData);

        stopwatch.stop();
        expect(stopwatch.elapsedMilliseconds, lessThan(200), 
               reason: 'HTML report generation should complete quickly');
      });

      test('should generate CI report within reasonable time', () {
        final stopwatch = Stopwatch()..start();
        final reporter = CIReporter.autoDetect(verbose: true);

        reporter.generate(testData);

        stopwatch.stop();
        expect(stopwatch.elapsedMilliseconds, lessThan(100), 
               reason: 'CI report generation should complete quickly');
      });
    });
  });
}

import 'package:flutter_keycheck/src/reporter/base_reporter.dart';
import 'package:test/test.dart';
import 'dart:io';
import 'dart:convert';
import 'package:path/path.dart' as path;

void main() {
  group('ReporterFactory', () {
    test('should create correct reporter types', () {
      expect(ReporterFactory.create('human'), isA<HumanReporter>());
      expect(ReporterFactory.create('json'), isA<JsonReporter>());
      expect(ReporterFactory.create('html'), isA<HtmlReporter>());
      expect(ReporterFactory.create('markdown'), isA<MarkdownReporter>());
      expect(ReporterFactory.create('junit'), isA<JUnitReporter>());
      expect(ReporterFactory.create('unknown'), isA<HumanReporter>()); // Default
    });

    test('should list available formats', () {
      final formats = ReporterFactory.availableFormats;
      expect(formats, contains('human'));
      expect(formats, contains('json'));
      expect(formats, contains('html'));
      expect(formats, contains('markdown'));
      expect(formats, contains('junit'));
    });
  });

  group('ReportData', () {
    test('should calculate coverage correctly', () {
      final data = ReportData(
        expectedKeys: {'key1', 'key2', 'key3'},
        foundKeys: {'key1', 'key2'},
        missingKeys: {'key3'},
        extraKeys: {'key4'},
        projectPath: '/test',
      );

      expect(data.coverage, equals(66.66666666666667));
      expect(data.passed, equals(false));
    });

    test('should pass when no missing keys', () {
      final data = ReportData(
        expectedKeys: {'key1', 'key2'},
        foundKeys: {'key1', 'key2', 'key3'},
        missingKeys: {},
        extraKeys: {'key3'},
        projectPath: '/test',
      );

      expect(data.coverage, equals(100.0));
      expect(data.passed, equals(true));
    });

    test('should provide summary statistics', () {
      final data = ReportData(
        expectedKeys: {'key1', 'key2', 'key3'},
        foundKeys: {'key1', 'key2', 'key4'},
        missingKeys: {'key3'},
        extraKeys: {'key4'},
        projectPath: '/test',
      );

      final summary = data.summary;
      expect(summary['expected'], equals(3));
      expect(summary['found'], equals(3));
      expect(summary['missing'], equals(1));
      expect(summary['extra'], equals(1));
      expect(summary['passed'], equals(false));
    });
  });

  group('HumanReporter', () {
    test('should generate human-readable report', () {
      final reporter = HumanReporter();
      final data = ReportData(
        expectedKeys: {'key1', 'key2', 'key3'},
        foundKeys: {'key1', 'key2'},
        missingKeys: {'key3'},
        extraKeys: {'key4'},
        projectPath: '/test/project',
        scanDuration: Duration(milliseconds: 123),
        scannedFiles: ['file1.dart', 'file2.dart'],
      );

      final report = reporter.generate(data);

      expect(report, contains('Flutter KeyCheck Report'));
      expect(report, contains('Project: /test/project'));
      expect(report, contains('Scan Duration: 123ms'));
      expect(report, contains('Files Scanned: 2'));
      expect(report, contains('Expected Keys: 3'));
      expect(report, contains('Missing Keys: 1'));
      expect(report, contains('❌ FAILED'));
      expect(report, contains('❌ key3'));
      expect(report, contains('⚠️ key4'));
    });

    test('should show passed status when appropriate', () {
      final reporter = HumanReporter();
      final data = ReportData(
        expectedKeys: {'key1', 'key2'},
        foundKeys: {'key1', 'key2'},
        missingKeys: {},
        extraKeys: {},
        projectPath: '/test',
      );

      final report = reporter.generate(data);
      expect(report, contains('✅ PASSED'));
    });
  });

  group('JsonReporter', () {
    test('should generate valid JSON report', () {
      final reporter = JsonReporter();
      final data = ReportData(
        expectedKeys: {'key1', 'key2'},
        foundKeys: {'key1'},
        missingKeys: {'key2'},
        extraKeys: {'key3'},
        projectPath: '/test',
        keyUsageCounts: {'key1': 2, 'key3': 1},
      );

      final jsonString = reporter.generate(data);
      final json = jsonDecode(jsonString);

      expect(json['projectPath'], equals('/test'));
      expect(json['summary']['expected'], equals(2));
      expect(json['summary']['missing'], equals(1));
      expect(json['missingKeys'], contains('key2'));
      expect(json['extraKeys'], contains('key3'));
      expect(json['keyUsageCounts']['key1'], equals(2));
    });

    test('should format JSON with indentation', () {
      final reporter = JsonReporter();
      final data = ReportData(
        expectedKeys: {'key1'},
        foundKeys: {'key1'},
        missingKeys: {},
        extraKeys: {},
        projectPath: '/test',
      );

      final jsonString = reporter.generate(data);
      expect(jsonString, contains('\n  ')); // Check for indentation
    });
  });

  group('HtmlReporter', () {
    test('should generate valid HTML report', () {
      final reporter = HtmlReporter();
      final data = ReportData(
        expectedKeys: {'key1', 'key2'},
        foundKeys: {'key1'},
        missingKeys: {'key2'},
        extraKeys: {'key3'},
        projectPath: '/test',
      );

      final html = reporter.generate(data);

      expect(html, contains('<!DOCTYPE html>'));
      expect(html, contains('<title>Flutter KeyCheck Report</title>'));
      expect(html, contains('Project: /test'));
      expect(html, contains('❌ FAILED'));
      expect(html, contains('❌ key2'));
      expect(html, contains('⚠️ key3'));
    });
  });

  group('MarkdownReporter', () {
    test('should generate valid Markdown report', () {
      final reporter = MarkdownReporter();
      final data = ReportData(
        expectedKeys: {'key1', 'key2'},
        foundKeys: {'key1'},
        missingKeys: {'key2'},
        extraKeys: {'key3'},
        projectPath: '/test',
      );

      final markdown = reporter.generate(data);

      expect(markdown, contains('# Flutter KeyCheck Report'));
      expect(markdown, contains('**Project:** `/test`'));
      expect(markdown, contains('| Expected Keys | 2 |'));
      expect(markdown, contains('## Missing Keys'));
      expect(markdown, contains('- ❌ `key2`'));
      expect(markdown, contains('## Extra Keys'));
      expect(markdown, contains('- ⚠️ `key3`'));
    });
  });

  group('JUnitReporter', () {
    test('should generate valid JUnit XML report', () {
      final reporter = JUnitReporter();
      final data = ReportData(
        expectedKeys: {'key1', 'key2'},
        foundKeys: {'key1'},
        missingKeys: {'key2'},
        extraKeys: {},
        projectPath: '/test',
        scanDuration: Duration(milliseconds: 500),
      );

      final xml = reporter.generate(data);

      expect(xml, contains('<?xml version="1.0" encoding="UTF-8"?>'));
      expect(xml, contains('<testsuites name="Flutter KeyCheck" tests="2" failures="1">'));
      expect(xml, contains('<testsuite name="Key Validation" tests="2" failures="1" time="0.5">'));
      expect(xml, contains('<testcase name="key1" classname="KeyValidation">'));
      expect(xml, contains('<testcase name="key2" classname="KeyValidation">'));
      expect(xml, contains('<failure message="Key not found in project">Missing key: key2</failure>'));
    });
  });

  group('Reporter file writing', () {
    late Directory tempDir;

    setUp(() {
      tempDir = Directory.systemTemp.createTempSync('reporter_test_');
    });

    tearDown(() {
      if (tempDir.existsSync()) {
        tempDir.deleteSync(recursive: true);
      }
    });

    test('should write report to file', () async {
      final reporter = JsonReporter();
      final data = ReportData(
        expectedKeys: {'key1'},
        foundKeys: {'key1'},
        missingKeys: {},
        extraKeys: {},
        projectPath: '/test',
      );

      final outputPath = path.join(tempDir.path, 'report.json');
      await reporter.writeToFile(data, outputPath);

      final file = File(outputPath);
      expect(file.existsSync(), isTrue);

      final content = file.readAsStringSync();
      final json = jsonDecode(content);
      expect(json['projectPath'], equals('/test'));
    });

    test('should create parent directories if needed', () async {
      final reporter = HumanReporter();
      final data = ReportData(
        expectedKeys: {'key1'},
        foundKeys: {'key1'},
        missingKeys: {},
        extraKeys: {},
        projectPath: '/test',
      );

      final outputPath = path.join(tempDir.path, 'nested', 'dir', 'report.txt');
      await reporter.writeToFile(data, outputPath);

      final file = File(outputPath);
      expect(file.existsSync(), isTrue);
    });
  });
}

import 'dart:convert';
import 'dart:io';

import 'package:test/test.dart';
import 'package:path/path.dart' as path;

void main() {
  late Directory tempDir;
  late String projectRoot;

  setUp(() async {
    tempDir = await Directory.systemTemp.createTemp('baseline_test_');
    projectRoot = tempDir.path;

    // Create a simple Flutter project structure
    final libDir = Directory(path.join(projectRoot, 'lib'));
    await libDir.create(recursive: true);

    // Create a sample Flutter file with keys
    final mainFile = File(path.join(libDir.path, 'main.dart'));
    await mainFile.writeAsString('''
import 'package:flutter/material.dart';

class MyWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        ElevatedButton(
          key: Key('login_button'),
          onPressed: () {},
          child: Text('Login'),
        ),
        TextField(
          key: ValueKey('email_field'),
        ),
        Container(
          key: Key('profile_container'),
          child: Text('Profile'),
        ),
      ],
    );
  }
}
''');

    // Create a config file
    final configFile = File(path.join(projectRoot, '.flutter_keycheck.yaml'));
    await configFile.writeAsString('''
version: 3
''');
  });

  tearDown(() async {
    if (await tempDir.exists()) {
      await tempDir.delete(recursive: true);
    }
  });

  group('Baseline Generation', () {
    test('creates baseline with correct structure', () async {
      final result = await Process.run(
        'dart',
        [
          'run',
          'bin/flutter_keycheck.dart',
          'baseline',
          'create',
          '--project-root',
          projectRoot,
          '--output',
          path.join(tempDir.path, 'baseline.json'),
        ],
        workingDirectory: Directory.current.path,
      );

      expect(result.exitCode, equals(0));

      // Check baseline file was created
      final baselineFile = File(path.join(tempDir.path, 'baseline.json'));
      expect(await baselineFile.exists(), isTrue);

      // Parse and validate baseline structure
      final baselineContent = await baselineFile.readAsString();
      final baseline = jsonDecode(baselineContent) as Map<String, dynamic>;

      expect(baseline, contains('metadata'));
      expect(baseline, contains('keys'));

      // Validate metadata
      final metadata = baseline['metadata'] as Map<String, dynamic>;
      expect(metadata, contains('created_at'));
      expect(metadata, contains('project_root'));
      expect(metadata, contains('total_keys'));
      expect(metadata, contains('dependencies_scanned'));
      expect(metadata, contains('schema_version'));

      // Validate keys array
      final keys = baseline['keys'] as List<dynamic>;
      expect(keys.length, greaterThan(0));

      // Check key structure
      for (final key in keys) {
        expect(key, contains('key'));
        expect(key, contains('type'));
        expect(key, contains('file'));
        expect(key, contains('line'));
        expect(key, contains('package'));
        expect(key, contains('dependency_level'));
      }

      // Verify specific keys are found
      final keyNames = keys.map((k) => k['key']).toSet();
      expect(keyNames, contains('login_button'));
      expect(keyNames, contains('email_field'));
      expect(keyNames, contains('profile_container'));
    });

    test('excludes dependencies when flag is set', () async {
      final result = await Process.run(
        'dart',
        [
          'run',
          'bin/flutter_keycheck.dart',
          'baseline',
          'create',
          '--project-root',
          projectRoot,
          '--exclude-deps',
          '--output',
          path.join(tempDir.path, 'baseline-no-deps.json'),
        ],
        workingDirectory: Directory.current.path,
      );

      expect(result.exitCode, equals(0));

      final baselineFile =
          File(path.join(tempDir.path, 'baseline-no-deps.json'));
      final baseline =
          jsonDecode(await baselineFile.readAsString()) as Map<String, dynamic>;
      final keys = baseline['keys'] as List<dynamic>;

      // All keys should be from direct dependencies only
      for (final key in keys) {
        expect(key['dependency_level'], equals('direct'));
      }
    });
  });

  group('Diff Reports', () {
    test('generates diff report in multiple formats', () async {
      // Create first baseline
      final baseline1File = File(path.join(tempDir.path, 'baseline1.json'));
      await baseline1File.writeAsString(jsonEncode({
        'metadata': {
          'created_at': DateTime.now().toIso8601String(),
          'project_root': projectRoot,
          'total_keys': 3,
          'dependencies_scanned': 0,
        },
        'keys': [
          {
            'key': 'login_button',
            'type': 'Key',
            'file': 'lib/main.dart',
            'line': 10,
            'package': 'my_app',
            'dependency_level': 'direct',
          },
          {
            'key': 'old_key',
            'type': 'Key',
            'file': 'lib/old.dart',
            'line': 5,
            'package': 'my_app',
            'dependency_level': 'direct',
          },
        ],
      }));

      // Create second baseline with changes
      final baseline2File = File(path.join(tempDir.path, 'baseline2.json'));
      await baseline2File.writeAsString(jsonEncode({
        'metadata': {
          'created_at': DateTime.now().toIso8601String(),
          'project_root': projectRoot,
          'total_keys': 3,
          'dependencies_scanned': 0,
        },
        'keys': [
          {
            'key': 'login_button',
            'type': 'Key',
            'file': 'lib/main.dart',
            'line': 10,
            'package': 'my_app',
            'dependency_level': 'direct',
          },
          {
            'key': 'new_key',
            'type': 'ValueKey',
            'file': 'lib/new.dart',
            'line': 15,
            'package': 'my_app',
            'dependency_level': 'direct',
          },
        ],
      }));

      // Run diff command with multiple report formats
      final result = await Process.run(
        'dart',
        [
          'run',
          'bin/flutter_keycheck.dart',
          'diff',
          '--baseline-old',
          baseline1File.path,
          '--baseline-new',
          baseline2File.path,
          '--report',
          'json',
          '--report',
          'markdown',
          '--report',
          'html',
        ],
        workingDirectory: Directory.current.path,
      );

      expect(result.exitCode, equals(1)); // Exit 1 when changes detected
      expect(result.stdout, contains('Added: 1'));
      expect(result.stdout, contains('Removed: 1'));

      // Check JSON report was created
      final jsonReport =
          File(path.join(projectRoot, 'reports', 'diff-report.json'));
      if (await jsonReport.exists()) {
        final report =
            jsonDecode(await jsonReport.readAsString()) as Map<String, dynamic>;
        expect(report['summary']['added'], equals(1));
        expect(report['summary']['removed'], equals(1));
        expect(report['changes']['added'], contains('new_key'));
        expect(report['changes']['removed'], contains('old_key'));
      }

      // Check Markdown report was created
      final mdReport =
          File(path.join(projectRoot, 'reports', 'diff-report.md'));
      if (await mdReport.exists()) {
        final content = await mdReport.readAsString();
        expect(content, contains('## 🔑 Flutter Keys Report'));
        expect(content, contains('| Added | +1 |'));
        expect(content, contains('| Removed | -1 |'));
      }

      // Check HTML report was created
      final htmlReport =
          File(path.join(projectRoot, 'reports', 'diff-report.html'));
      if (await htmlReport.exists()) {
        final content = await htmlReport.readAsString();
        expect(content, contains('<h1>🔑 Flutter KeyCheck Diff Report</h1>'));
        expect(content, contains('Added Keys'));
        expect(content, contains('Removed Keys'));
      }
    });

    test('detects no changes correctly', () async {
      // Create identical baselines
      final baselineContent = jsonEncode({
        'metadata': {
          'created_at': DateTime.now().toIso8601String(),
          'project_root': projectRoot,
          'total_keys': 2,
          'dependencies_scanned': 0,
        },
        'keys': [
          {
            'key': 'key1',
            'type': 'Key',
            'file': 'lib/main.dart',
            'line': 10,
            'package': 'my_app',
            'dependency_level': 'direct',
          },
          {
            'key': 'key2',
            'type': 'ValueKey',
            'file': 'lib/main.dart',
            'line': 20,
            'package': 'my_app',
            'dependency_level': 'direct',
          },
        ],
      });

      final baseline1File = File(path.join(tempDir.path, 'baseline1.json'));
      await baseline1File.writeAsString(baselineContent);

      final baseline2File = File(path.join(tempDir.path, 'baseline2.json'));
      await baseline2File.writeAsString(baselineContent);

      final result = await Process.run(
        'dart',
        [
          'run',
          'bin/flutter_keycheck.dart',
          'diff',
          '--baseline-old',
          baseline1File.path,
          '--baseline-new',
          baseline2File.path,
        ],
        workingDirectory: Directory.current.path,
      );

      expect(result.exitCode, equals(0)); // Exit 0 when no changes
      expect(result.stdout, contains('No changes detected'));
    });
  });

  group('Validation Against Baseline', () {
    test('validates current state against baseline', () async {
      // Create a baseline file
      final baselineFile = File(path.join(tempDir.path, 'baseline.json'));
      await baselineFile.writeAsString(jsonEncode({
        'metadata': {
          'created_at': DateTime.now().toIso8601String(),
          'project_root': projectRoot,
          'total_keys': 3,
          'dependencies_scanned': 0,
        },
        'keys': [
          {
            'key': 'login_button',
            'type': 'Key',
            'file': 'lib/main.dart',
            'line': 10,
            'package': 'my_app',
            'dependency_level': 'direct',
          },
          {
            'key': 'email_field',
            'type': 'ValueKey',
            'file': 'lib/main.dart',
            'line': 14,
            'package': 'my_app',
            'dependency_level': 'direct',
          },
          {
            'key': 'profile_container',
            'type': 'Key',
            'file': 'lib/main.dart',
            'line': 17,
            'package': 'my_app',
            'dependency_level': 'direct',
          },
        ],
      }));

      final result = await Process.run(
        'dart',
        [
          'run',
          'bin/flutter_keycheck.dart',
          'validate',
          '--project-root',
          projectRoot,
          '--baseline',
          baselineFile.path,
          '--report',
          'json',
          '--report',
          'junit',
        ],
        workingDirectory: Directory.current.path,
      );

      // Should pass if current state matches baseline
      if (result.stdout.contains('All validation checks passed')) {
        expect(result.exitCode, equals(0));
      }

      // Check reports were generated
      final jsonReport =
          File(path.join(projectRoot, 'reports', 'validation-report.json'));
      if (await jsonReport.exists()) {
        final report =
            jsonDecode(await jsonReport.readAsString()) as Map<String, dynamic>;
        expect(report, contains('summary'));
        expect(report, contains('violations'));
      }

      final junitReport =
          File(path.join(projectRoot, 'reports', 'validation-report.xml'));
      if (await junitReport.exists()) {
        final content = await junitReport.readAsString();
        expect(content, contains('<?xml version="1.0"'));
        expect(content, contains('<testsuites'));
      }
    });
  });
}

@Tags(['nonblocking'])
library;

import 'dart:io';
import 'dart:convert';
import 'package:test/test.dart';
import 'package:flutter_keycheck/src/cache/dependency_cache.dart';
import 'package:path/path.dart' as path;

void main() {
  group('Dependency Cache Smoke Tests', () {
    late Directory tempDir;
    late String originalDir;

    setUp(() async {
      tempDir = await Directory.systemTemp.createTemp('cache_test_');
      originalDir = Directory.current.path;
      Directory.current = tempDir;
    });

    tearDown(() async {
      Directory.current = Directory(originalDir);
      if (await tempDir.exists()) {
        await tempDir.delete(recursive: true);
      }
    });

    test('cache directory is created when saving cache', () async {
      final cacheKey = DependencyCache.getCacheKey(
        packageName: 'test_package',
        packageVersion: '1.0.0',
        detectorHash: 'v3.0.0',
        sdkVersion: '3.0.0',
      );

      final testData = {
        'test_file.dart': {
          'widgetCount': 5,
          'widgetsWithKeys': 3,
          'keysFound': ['key1', 'key2'],
        },
      };

      await DependencyCache.saveCache(tempDir.path, cacheKey, testData);

      // Verify cache directory was created
      final cacheDir = Directory(
          path.join(tempDir.path, '.dart_tool/flutter_keycheck/cache'));
      expect(await cacheDir.exists(), isTrue,
          reason: 'Cache directory should be created at ${cacheDir.path}');

      // Verify cache file was created
      final cacheFile = DependencyCache.getCacheFile(tempDir.path, cacheKey);
      expect(await cacheFile.exists(), isTrue,
          reason: 'Cache file should exist at ${cacheFile.path}');
    });

    test('cache can be loaded after saving', () async {
      final cacheKey = DependencyCache.getCacheKey(
        packageName: 'test_package',
        packageVersion: '1.0.0',
        detectorHash: 'v3.0.0',
        sdkVersion: '3.0.0',
      );

      final testData = {
        'test_file.dart': {
          'widgetCount': 5,
          'widgetsWithKeys': 3,
          'keysFound': ['key1', 'key2'],
        },
      };

      // Save cache
      await DependencyCache.saveCache(tempDir.path, cacheKey, testData);

      // Load cache
      final loaded = await DependencyCache.loadCache(tempDir.path, cacheKey);

      expect(loaded, isNotNull);
      expect(loaded!['test_file.dart'], isNotNull);
      expect(loaded['test_file.dart']['widgetCount'], equals(5));
      expect(loaded['test_file.dart']['keysFound'], contains('key1'));
      expect(loaded['test_file.dart']['keysFound'], contains('key2'));
    });

    test('cache expires after 24 hours', () async {
      final cacheKey = DependencyCache.getCacheKey(
        packageName: 'test_package',
        packageVersion: '1.0.0',
        detectorHash: 'v3.0.0',
        sdkVersion: '3.0.0',
      );

      final testData = {'test': 'data'};

      // Create cache file manually with old timestamp
      final cacheFile = DependencyCache.getCacheFile(tempDir.path, cacheKey);
      await cacheFile.parent.create(recursive: true);

      final oldTimestamp = DateTime.now().subtract(const Duration(hours: 25));
      final cacheContent = {
        'cache_key': cacheKey,
        'cached_at': oldTimestamp.toIso8601String(),
        'result': testData,
      };

      await cacheFile.writeAsString(json.encode(cacheContent));

      // Try to load expired cache
      final loaded = await DependencyCache.loadCache(tempDir.path, cacheKey);

      expect(loaded, isNull, reason: 'Expired cache should return null');
      expect(await cacheFile.exists(), isFalse,
          reason: 'Expired cache file should be deleted');
    });

    test('cache handles invalid JSON gracefully', () async {
      final cacheKey = DependencyCache.getCacheKey(
        packageName: 'test_package',
        packageVersion: '1.0.0',
        detectorHash: 'v3.0.0',
        sdkVersion: '3.0.0',
      );

      // Create cache file with invalid JSON
      final cacheFile = DependencyCache.getCacheFile(tempDir.path, cacheKey);
      await cacheFile.parent.create(recursive: true);
      await cacheFile.writeAsString('invalid json content');

      // Try to load invalid cache
      final loaded = await DependencyCache.loadCache(tempDir.path, cacheKey);

      expect(loaded, isNull, reason: 'Invalid cache should return null');
    });

    test('cache key generation is consistent', () {
      final key1 = DependencyCache.getCacheKey(
        packageName: 'package',
        packageVersion: '1.0.0',
        detectorHash: 'hash',
        sdkVersion: 'sdk',
      );

      final key2 = DependencyCache.getCacheKey(
        packageName: 'package',
        packageVersion: '1.0.0',
        detectorHash: 'hash',
        sdkVersion: 'sdk',
      );

      expect(key1, equals(key2));
      expect(key1, equals('package@1.0.0|hash|sdk'));
    });

    test('clear cache removes all cached files', () async {
      // Create multiple cache entries
      for (int i = 0; i < 3; i++) {
        final cacheKey = DependencyCache.getCacheKey(
          packageName: 'package_$i',
          packageVersion: '1.0.0',
          detectorHash: 'v3.0.0',
          sdkVersion: '3.0.0',
        );

        await DependencyCache.saveCache(tempDir.path, cacheKey, {'test': i});
      }

      // Verify cache directory exists
      final cacheDir = Directory(
          path.join(tempDir.path, '.dart_tool/flutter_keycheck/cache'));
      expect(await cacheDir.exists(), isTrue);

      // Clear cache
      await DependencyCache.clearCache(tempDir.path);

      // Verify cache directory is removed
      expect(await cacheDir.exists(), isFalse,
          reason: 'Cache directory should be removed after clearing');
    });

    test('cache directory structure is correct', () async {
      final cacheKey = DependencyCache.getCacheKey(
        packageName: 'test_package',
        packageVersion: '1.0.0',
        detectorHash: 'v3.0.0',
        sdkVersion: '3.0.0',
      );

      await DependencyCache.saveCache(tempDir.path, cacheKey, {'test': 'data'});

      // Check directory structure
      final dartToolDir = Directory(path.join(tempDir.path, '.dart_tool'));
      final keyCheckDir =
          Directory(path.join(dartToolDir.path, 'flutter_keycheck'));
      final cacheDir = Directory(path.join(keyCheckDir.path, 'cache'));

      expect(await dartToolDir.exists(), isTrue,
          reason: '.dart_tool directory should exist');
      expect(await keyCheckDir.exists(), isTrue,
          reason: 'flutter_keycheck directory should exist');
      expect(await cacheDir.exists(), isTrue,
          reason: 'cache directory should exist');
    });
  });
}

import 'dart:io';
import 'package:test/test.dart';
import 'package:path/path.dart' as path;
import '../helpers/cli.dart';

void main() {
  // Use the golden workspace for tests to avoid scanning the entire project
  final testWorkspace = path.absolute('test', 'golden_workspace');

  group('CLI Scope Flag Tests', () {
    test('scan command includes --scope flag in help', () async {
      final result = await runCli([
        'scan',
        '--help',
      ]);

      // On Windows, help might return 0 or 255 due to memory issues
      expect(result.exitCode, anyOf([0, 255]),
          reason: 'Help command should complete');

      final output = '${result.stdout}${result.stderr}';

      // Check that help includes scope flag information
      expect(output, contains('--scope'),
          reason: 'Help should include --scope flag');
      expect(output, contains('workspace-only'),
          reason: 'Help should show workspace-only option');
      expect(output, contains('deps-only'),
          reason: 'Help should show deps-only option');
      expect(output, contains('all'), reason: 'Help should show all option');
    }, timeout: const Timeout(Duration(seconds: 30)));

    test('scan command accepts --scope flag', () async {
      final result = await runCli([
        'scan',
        '--scope',
        'workspace-only',
      ], projectRoot: testWorkspace);

      // Should not fail with "Could not find an option named --scope"
      expect(result.stderr, isNot(contains('Could not find an option named')),
          reason: 'Should accept --scope flag');

      // Should complete successfully or with expected error (not flag parsing error)
      // On Windows, might also return 255 due to memory issues
      expect(result.exitCode, anyOf([0, 2, 3, 4, 255]),
          reason:
              'Should not fail with invalid flag error (exit code 64 or 254)');
    }, timeout: const Timeout(Duration(seconds: 30)));

    test('scan command rejects invalid scope values', () async {
      final result = await runCli([
        'scan',
        '--scope',
        'invalid-value',
      ], projectRoot: testWorkspace);

      expect(result.exitCode, isNot(equals(0)),
          reason: 'Should fail with invalid scope value');
      final errorOutput = result.stderr.toString();

      // On Windows, might get memory error instead of proper error message
      if (!errorOutput.contains('Out of memory')) {
        expect(errorOutput, contains('"invalid-value" is not an allowed value'),
            reason: 'Should report invalid scope value');
      }
    }, timeout: const Timeout(Duration(seconds: 30)));

    test('scan command defaults to workspace-only scope', () async {
      final result = await runCli([
        'scan',
        '--report',
        'json',
      ], projectRoot: testWorkspace);

      if (result.exitCode == 0) {
        // If scan succeeds, output should be JSON
        final output = result.stdout.toString();
        if (output.contains('{') && output.contains('schemaVersion')) {
          // This is JSON output - good
          expect(output, contains('schemaVersion'),
              reason: 'JSON output should have schemaVersion');
        }
      }
      // Otherwise test passes - we just wanted to verify the command runs
    }, timeout: const Timeout(Duration(seconds: 30)));
  });

  group('CLI Package Policy Flags Tests', () {
    test('validate command includes package policy flags in help', () async {
      final result = await runCli([
        'validate',
        '--help',
      ]);

      expect(result.exitCode, equals(0));
      final output = '${result.stdout}${result.stderr}';

      // Check that help includes package policy flags
      expect(output, contains('fail-on-package-missing'),
          reason: 'Help should include --fail-on-package-missing flag');
      expect(output, contains('fail-on-collision'),
          reason: 'Help should include --fail-on-collision flag');
    }, timeout: const Timeout(Duration(seconds: 30)));

    test('validate command accepts package policy flags', () async {
      // Clean up any existing baseline first
      final baselineDir = path.join(testWorkspace, '.flutter_keycheck');
      if (Directory(baselineDir).existsSync()) {
        try {
          Directory(baselineDir).deleteSync(recursive: true);
        } catch (_) {
          // Ignore cleanup errors
        }
      }

      // First create a baseline in the test workspace
      final baselineResult = await runCli([
        'baseline',
        'create',
      ], projectRoot: testWorkspace);

      // Check baseline was created successfully
      if (baselineResult.exitCode != 0) {
        print('Baseline creation failed: ${baselineResult.stderr}');
      }

      final result = await runCli([
        'validate',
        '--fail-on-package-missing',
        '--fail-on-collision',
      ], projectRoot: testWorkspace);

      // Should not fail with "Could not find an option named" error
      expect(result.stderr, isNot(contains('Could not find an option named')),
          reason: 'Should accept package policy flags');
    }, timeout: const Timeout(Duration(seconds: 30)));
  });
}

