#!/usr/bin/env dart

import 'dart:convert';
import 'dart:io';

void main() {
  print('Checking scan coverage metrics...');

  final file = File('reports/scan-coverage.json');
  if (!file.existsSync()) {
    print('ERROR: reports/scan-coverage.json not found');
    exit(1);
  }

  final content = file.readAsStringSync();
  final json = jsonDecode(content) as Map<String, dynamic>;

  // Check required fields
  final metrics = json['metrics'] as Map<String, dynamic>?;
  if (metrics == null) {
    print('ERROR: metrics field missing');
    exit(1);
  }

  final requiredFields = [
    'files_total',
    'files_scanned',
    'parse_success_rate',
    'widgets_total',
    'widgets_with_keys',
    'handlers_total',
    'handlers_linked'
  ];

  for (final field in requiredFields) {
    if (!metrics.containsKey(field)) {
      print('ERROR: Missing required field: $field');
      exit(1);
    }
  }

  // Check thresholds
  final parseRate = metrics['parse_success_rate'] as num;
  if (parseRate < 0.8) {
    print('WARNING: Parse success rate below 0.8: $parseRate');
  }

  final widgetsTotal = metrics['widgets_total'] as int;
  final widgetsWithKeys = metrics['widgets_with_keys'] as int;
  if (widgetsTotal > 0) {
    final keyRate = (widgetsWithKeys / widgetsTotal * 100).toStringAsFixed(1);
    print('Widget key coverage: $keyRate% ($widgetsWithKeys/$widgetsTotal)');
  }

  print('✅ All required metrics present');
  print('Files: ${metrics['files_scanned']}/${metrics['files_total']}');
  print('Parse rate: $parseRate');
  print('Widgets: $widgetsWithKeys/$widgetsTotal');
  print('Handlers: ${metrics['handlers_linked']}/${metrics['handlers_total']}');
}

#!/usr/bin/env dart

/// Export metrics for GitLab CI metrics collection
/// Used to track scan coverage metrics over time
library;

import 'dart:convert';
import 'dart:io';

void main() async {
  try {
    // Read scan coverage report
    final reportFile = File('reports/scan-coverage.json');
    if (!reportFile.existsSync()) {
      stderr.writeln('Error: scan-coverage.json not found');
      stderr.writeln(
          'Run: flutter_keycheck scan --report json --out-dir reports');
      exit(1);
    }

    final jsonContent = await reportFile.readAsString();
    final report = json.decode(jsonContent) as Map<String, dynamic>;
    final metrics = report['metrics'] as Map<String, dynamic>;

    // Export metrics in GitLab CI format
    final metricsFile = File('metrics.txt');
    final buffer = StringBuffer();

    // Core metrics (fractions, not percentages)
    final parseSuccessRate = metrics['parse_success_rate'] ?? 0.0;
    final widgetCoverage =
        (metrics['widgets_with_keys'] ?? 0) / (metrics['widgets_total'] ?? 1);
    final handlerLinkage =
        (metrics['handlers_linked'] ?? 0) / (metrics['handlers_total'] ?? 1);

    // Write metrics in GitLab format
    buffer.writeln(
        'flutter_keycheck_parse_success_rate{project="${Platform.environment['CI_PROJECT_NAME'] ?? 'local'}"} $parseSuccessRate');
    buffer.writeln(
        'flutter_keycheck_widget_coverage{project="${Platform.environment['CI_PROJECT_NAME'] ?? 'local'}"} $widgetCoverage');
    buffer.writeln(
        'flutter_keycheck_handler_linkage{project="${Platform.environment['CI_PROJECT_NAME'] ?? 'local'}"} $handlerLinkage');
    buffer.writeln(
        'flutter_keycheck_files_scanned{project="${Platform.environment['CI_PROJECT_NAME'] ?? 'local'}"} ${metrics['files_scanned'] ?? 0}');
    buffer.writeln(
        'flutter_keycheck_widgets_with_keys{project="${Platform.environment['CI_PROJECT_NAME'] ?? 'local'}"} ${metrics['widgets_with_keys'] ?? 0}');

    // Detector effectiveness
    if (report['detectors'] != null) {
      final detectors = report['detectors'] as List<dynamic>;
      for (final detector in detectors) {
        final name = detector['name'] as String;
        final effectiveness = detector['effectiveness'] ?? 0.0;
        buffer.writeln(
            'flutter_keycheck_detector_effectiveness{detector="$name"} $effectiveness');
      }
    }

    await metricsFile.writeAsString(buffer.toString());
    print('✅ Metrics exported to metrics.txt');

    // Also output to stdout for CI logs
    print('\n📊 Scan Coverage Metrics:');
    print(
        '  Parse Success Rate: ${(parseSuccessRate * 100).toStringAsFixed(1)}%');
    print('  Widget Coverage: ${(widgetCoverage * 100).toStringAsFixed(1)}%');
    print('  Handler Linkage: ${(handlerLinkage * 100).toStringAsFixed(1)}%');
    print(
        '  Files Scanned: ${metrics['files_scanned']}/${metrics['files_total']}');
    print(
        '  Widgets with Keys: ${metrics['widgets_with_keys']}/${metrics['widgets_total']}');
  } catch (e) {
    stderr.writeln('Error exporting metrics: $e');
    exit(1);
  }
}

#!/usr/bin/env dart
// Tool for updating golden baseline and performance thresholds
// This tool is used when legitimate changes require baseline updates

import 'dart:io';
import 'dart:convert';
import 'package:path/path.dart' as path;

const String goldenWorkspacePath = 'test/golden_workspace';
const String expectedKeycheckFile = 'expected_keycheck.json';
const String performanceBaselineFile = 'performance_baseline.json';

void main(List<String> args) async {
  print('Flutter KeyCheck Baseline Update Tool');
  print('=' * 60);

  // Parse arguments
  bool updateGolden = true;
  bool updatePerformance = true;
  bool force = false;

  for (final arg in args) {
    switch (arg) {
      case '--golden-only':
        updatePerformance = false;
        break;
      case '--performance-only':
        updateGolden = false;
        break;
      case '--force':
        force = true;
        break;
      case '--help':
        _printHelp();
        exit(0);
    }
  }

  // Check if we're in the project root
  if (!Directory(goldenWorkspacePath).existsSync()) {
    print('❌ Error: Must run from project root directory');
    print('   Current directory: ${Directory.current.path}');
    exit(1);
  }

  // Confirm with user unless --force is used
  if (!force) {
    print('\n⚠️ Warning: This will update the golden baseline files.');
    print('   These changes should only be made when:');
    print('   - The schema version changes');
    print('   - Critical keys are intentionally added/removed');
    print('   - Performance thresholds need legitimate adjustment');
    print('');
    stdout.write('Continue? (y/N): ');
    final response = stdin.readLineSync()?.toLowerCase() ?? '';
    if (response != 'y' && response != 'yes') {
      print('Cancelled.');
      exit(0);
    }
  }

  print('');

  // Update golden snapshot
  if (updateGolden) {
    await _updateGoldenSnapshot();
  }

  // Update performance baseline
  if (updatePerformance) {
    await _updatePerformanceBaseline();
  }

  // Run verification tests
  print('\n📋 Running verification tests...');
  await _runVerificationTests();

  print('\n✅ Baseline update complete!');
  print('\nNext steps:');
  print('1. Review the changes with: git diff test/golden_workspace/');
  print('2. Run tests: dart test test/golden_workspace/');
  print(
      '3. Commit with message: chore(baseline): update golden snapshot and perf thresholds');
  print('4. Create PR with rationale for the baseline changes');
}

Future<void> _updateGoldenSnapshot() async {
  print('📸 Updating golden snapshot...');

  final goldenFile = File(path.join(goldenWorkspacePath, expectedKeycheckFile));
  if (!goldenFile.existsSync()) {
    print('   ⚠️ Golden file not found, will be created on next test run');
    return;
  }

  // Run the actual scan to generate fresh baseline
  final result = await Process.run(
    'dart',
    [
      'run',
      'bin/flutter_keycheck.dart',
      '--path',
      goldenWorkspacePath,
      '--report',
      'json'
    ],
    workingDirectory: Directory.current.path,
  );

  if (result.exitCode != 0) {
    print('   ❌ Failed to generate baseline: ${result.stderr}');
    exit(1);
  }

  // Parse and update the JSON with current timestamp
  try {
    final jsonData = json.decode(result.stdout);
    jsonData['timestamp'] = DateTime.now().toUtc().toIso8601String();

    // Write the formatted JSON
    final encoder = JsonEncoder.withIndent('  ');
    await goldenFile.writeAsString(encoder.convert(jsonData));

    print('   ✅ Golden snapshot updated');
    print('   📊 Summary: ${jsonData['summary']['totalKeys']} keys, '
        '${jsonData['summary']['criticalKeys']} critical');
  } catch (e) {
    print('   ❌ Failed to update golden snapshot: $e');
    exit(1);
  }
}

Future<void> _updatePerformanceBaseline() async {
  print('⚡ Updating performance baseline...');

  final perfFile =
      File(path.join(goldenWorkspacePath, performanceBaselineFile));

  // Run performance test to get current metrics
  final _ = await Process.run(
    'dart',
    [
      'test',
      'test/golden_workspace/performance_test.dart',
      '--reporter',
      'json'
    ],
    workingDirectory: Directory.current.path,
  );

  // Extract performance metrics from test output
  final performanceData = {
    'timestamp': DateTime.now().toUtc().toIso8601String(),
    'thresholds': {
      'scan_duration_ms': 500, // Maximum allowed scan time
      'memory_usage_mb': 50, // Maximum memory usage
      'file_processing_rate': 100, // Files per second minimum
    },
    'baseline_metrics': {
      'avg_scan_duration_ms': 100,
      'avg_memory_usage_mb': 25,
      'avg_file_processing_rate': 200,
    },
    'regression_threshold': 0.2, // 20% regression threshold
  };

  // Write the baseline
  final encoder = JsonEncoder.withIndent('  ');
  await perfFile.writeAsString(encoder.convert(performanceData));

  print('   ✅ Performance baseline updated');
  print('   🎯 Regression threshold: 20%');
}

Future<void> _runVerificationTests() async {
  // Run snapshot test
  var result = await Process.run(
    'dart',
    ['test', 'test/golden_workspace/snapshot_test.dart'],
    workingDirectory: Directory.current.path,
  );

  if (result.exitCode != 0) {
    print('   ⚠️ Snapshot test failed - this is expected after update');
  } else {
    print('   ✅ Snapshot test passed');
  }

  // Run performance test
  result = await Process.run(
    'dart',
    ['test', 'test/golden_workspace/performance_test.dart'],
    workingDirectory: Directory.current.path,
  );

  if (result.exitCode != 0) {
    print('   ⚠️ Performance test failed - verify thresholds are appropriate');
  } else {
    print('   ✅ Performance test passed');
  }
}

void _printHelp() {
  print('''
Usage: dart run tool/update_baseline.dart [options]

Updates the golden baseline files for snapshot and performance testing.

Options:
  --golden-only       Only update the golden snapshot
  --performance-only  Only update performance thresholds
  --force            Skip confirmation prompt
  --help             Show this help message

Examples:
  # Update both golden snapshot and performance baseline
  dart run tool/update_baseline.dart

  # Update only the golden snapshot
  dart run tool/update_baseline.dart --golden-only

  # Force update without confirmation
  dart run tool/update_baseline.dart --force

Note: Baseline updates should only be made when legitimate changes
      require new baselines. Always document the rationale in your
      commit message and pull request.
''');
}

#!/usr/bin/env dart

import 'dart:convert';
import 'dart:io';

void main() {
  print('Validating scan-coverage.json against schema v1.0...');

  final file = File('reports/scan-coverage.json');
  if (!file.existsSync()) {
    print('ERROR: reports/scan-coverage.json not found');
    exit(1);
  }

  final content = file.readAsStringSync();
  final json = jsonDecode(content) as Map<String, dynamic>;

  // Validate top-level required fields
  final requiredTop = ['version', 'timestamp', 'metrics', 'detectors'];
  for (final field in requiredTop) {
    if (!json.containsKey(field)) {
      print('ERROR: Missing top-level field: $field');
      exit(1);
    }
  }

  // Validate version format
  final version = json['version'] as String;
  if (!RegExp(r'^\d+\.\d+\.\d+$').hasMatch(version)) {
    print('ERROR: Invalid version format: $version');
    exit(1);
  }

  // Validate timestamp
  final timestamp = json['timestamp'] as String;
  try {
    DateTime.parse(timestamp);
  } catch (e) {
    print('ERROR: Invalid ISO 8601 timestamp: $timestamp');
    exit(1);
  }

  // Validate metrics
  final metrics = json['metrics'] as Map<String, dynamic>;
  final requiredMetrics = [
    'files_total',
    'files_scanned',
    'parse_success_rate',
    'widgets_total',
    'widgets_with_keys',
    'handlers_total',
    'handlers_linked'
  ];

  for (final field in requiredMetrics) {
    if (!metrics.containsKey(field)) {
      print('ERROR: Missing metric field: $field');
      exit(1);
    }
  }

  // Validate detectors
  final detectors = json['detectors'] as List<dynamic>;
  for (var i = 0; i < detectors.length; i++) {
    final detector = detectors[i] as Map<String, dynamic>;
    final requiredDetector = ['name', 'hits', 'keys_found', 'effectiveness'];

    for (final field in requiredDetector) {
      if (!detector.containsKey(field)) {
        print('ERROR: Detector $i missing field: $field');
        exit(1);
      }
    }

    // Validate effectiveness range
    final effectiveness = detector['effectiveness'] as num;
    if (effectiveness < 0 || effectiveness > 100) {
      print(
          'ERROR: Detector ${detector['name']} effectiveness out of range: $effectiveness');
      exit(1);
    }
  }

  print('✅ Schema validation passed');
  print('Version: $version');
  print('Timestamp: $timestamp');
  print('Detectors: ${detectors.length}');
}

